sub _control_flow_effects_prove_loop_repeat_pending_spawn_local_do_drain($actor, $transaction_name, $loop_kind, $spawn_instances, $do_child, $options) {
    return 0 unless defined($transaction_name) && !ref($transaction_name);
    return 0 unless defined($loop_kind) && !ref($loop_kind) && ($loop_kind eq 'while' || $loop_kind eq 'until');
    my @spawn_instances = ref($spawn_instances) eq 'ARRAY' ? @$spawn_instances : ($spawn_instances);
    return 0 unless @spawn_instances;
    for my $spawn_instance (@spawn_instances) {
        return 0 unless defined($spawn_instance) && !ref($spawn_instance) && length($spawn_instance);
    }
    return 0 unless defined($do_child) && !ref($do_child) && length($do_child);
    $options = {} unless ref($options) eq 'HASH';

    my $loop_backedge = "${loop_kind}_retest";
    my @done_ports = map { "${_}_done" } @spawn_instances;
    my $allow_single_pending_await_any = $options->{allow_single_pending_await_any} ? 1 : 0;
    my $check = _control_flow_effect_check($actor);
    return 0 unless $check->{ok};

    for my $tx (@{$check->{transactions} || []}) {
        next unless ($tx->{name} // '') eq $transaction_name;
        my @proofs = @{$tx->{proofs} || []};
        my $has_loop_backedge_proof = grep {
            ($_->{code} // '') eq 'backedge_has_no_outstanding_children'
                && ($_->{region_kind} // '') eq $loop_kind
                && ($_->{backedge} // '') eq $loop_backedge
        } @proofs;
        next unless $has_loop_backedge_proof;

        my %repeat_region_ids = map { $_->{region_id} => 1 } grep {
            defined($_->{region_id})
                && ($_->{code} // '') eq 'backedge_has_no_outstanding_children'
                && ($_->{region_kind} // '') eq 'repeat'
                && ($_->{backedge} // '') eq 'repeat_check_nonzero'
                && _effect_path_matches($_->{path}, ['transaction', $loop_kind, 'repeat'])
        } @proofs;

        for my $region_id (sort keys %repeat_region_ids) {
            my $all_spawns_proven = 1;
            for my $i (0 .. $#spawn_instances) {
                my $spawn_instance = $spawn_instances[$i];
                my $done_port = $done_ports[$i];
                my ($spawn_effect_id) = map { $_->{effect_id} } grep {
                    ($_->{region_id} // '') eq $region_id
                        && ($_->{code} // '') eq 'generated_top_start_done_handoff_required'
                        && ($_->{instance} // '') eq $spawn_instance
                        && ($_->{done_signal} // '') eq $done_port
                        && defined($_->{effect_id})
                } @proofs;
                if (!defined($spawn_effect_id)) {
                    $all_spawns_proven = 0;
                    last;
                }
                if (!grep {
                    ($_->{region_id} // '') eq $region_id
                        && ($_->{code} // '') eq 'generated_child_instance_is_static'
                        && ($_->{instance} // '') eq $spawn_instance
                        && ($_->{effect_id} // '') eq $spawn_effect_id
                } @proofs) {
                    $all_spawns_proven = 0;
                    last;
                }
                if (!grep {
                    ($_->{region_id} // '') eq $region_id
                        && ($_->{code} // '') eq 'activation_target_is_same_domain'
                        && ($_->{effect_id} // '') eq $spawn_effect_id
                } @proofs) {
                    $all_spawns_proven = 0;
                    last;
                }
            }
            next unless $all_spawns_proven;

            my ($do_effect_id) = map { $_->{effect_id} } grep {
                ($_->{region_id} // '') eq $region_id
                    && ($_->{code} // '') eq 'blocking_do_drains_child_done'
                    && ($_->{child} // '') eq $do_child
                    && defined($_->{effect_id})
            } @proofs;
            next unless defined($do_effect_id);
            next unless grep {
                ($_->{region_id} // '') eq $region_id
                    && ($_->{code} // '') eq 'activation_target_is_same_domain'
                    && ($_->{child} // '') eq $do_child
                    && ($_->{effect_id} // '') eq $do_effect_id
            } @proofs;
            next unless grep {
                ($_->{region_id} // '') eq $region_id
                    && (($_->{code} // '') eq 'await_all_drains_outstanding_children'
                        || (@spawn_instances == 1 && $allow_single_pending_await_any
                            && ($_->{code} // '') eq 'await_any_single_pending_completes_outstanding_set'))
                    && _effect_done_ports_match($_->{done_ports}, \@done_ports)
            } @proofs;
            return 1;
        }
    }
    return 0;
}

sub _effect_path_matches($actual, $expected) {
    return 0 unless ref($actual) eq 'ARRAY' && ref($expected) eq 'ARRAY';
    return 0 unless @$actual == @$expected;
    for my $i (0 .. $#$expected) {
        return 0 unless defined($actual->[$i]) && $actual->[$i] eq $expected->[$i];
    }
    return 1;
}

sub _effect_done_ports_match($actual, $expected) {
    return 0 unless ref($actual) eq 'ARRAY' && ref($expected) eq 'ARRAY';
    return 0 unless @$actual == @$expected;
    for my $i (0 .. $#$expected) {
        return 0 unless defined($actual->[$i]) && $actual->[$i] eq $expected->[$i];
    }
    return 1;
}

# True when the actor declares an `(activation child (from SRC)(to DEST))`
# crossing that owns a cross-domain `(do child)` from `$caller_domain` into
# `$target_domain`. Such a `(do)` is routed through the two CDC synchronizers
# (`_emit_multi_domain_top`) rather than fail-closed at the same-domain check.
sub _activation_crossing_covers {
    my ($actor, $caller_domain, $target_domain, $child) = @_;
    return 0 unless defined($caller_domain) && defined($target_domain) && defined($child);
    for my $crossing (@{$actor->{crossings} || []}) {
        next unless ref($crossing) eq 'HASH' && ($crossing->{kind} // '') eq 'activation';
        return 1
            if ($crossing->{child} // '') eq $child
            && ($crossing->{from}{domain} // '') eq $caller_domain
            && ($crossing->{to}{domain} // '') eq $target_domain;
    }
    return 0;
}

sub _validate_drive_reuse_domains {
    my ($drive_use_domains) = @_;

    for my $drive (sort keys %$drive_use_domains) {
        my @domains = sort keys %{$drive_use_domains->{$drive} || {}};
        confess "ISF clock-domain violation: drive '$drive' is called from multiple domains (" . join(', ', @domains) . ") without a safe cross-domain drive reuse rule\n"
            if @domains > 1;
    }
    return 1;
}

sub _validate_drive_body_domain_refs {
    my ($actor, $drive_use_domains, $signal_domains, $constants) = @_;
    for my $name (sort keys %$drive_use_domains) {
        my $drive = $actor->{drives}{$name};
        for my $domain (sort keys %{$drive_use_domains->{$name}}) {
            # Parameters belong to the caller's scope; an outer declaration
            # with the same name cannot lend them its domain.
            my %local = map { $_ => $domain } @{$drive->{params} || []};
            for my $assignment (@{$drive->{body} || []}) {
                next unless ref($assignment) eq 'ARRAY' && @$assignment >= 2;
                my $context = "drive '$name' assignment";
                _validate_domain_signal_access($assignment->[0], 'write', $domain,
                    $signal_domains, \%local, $constants, $context);
                _validate_domain_expr_reads($assignment->[1], $domain,
                    $signal_domains, \%local, $constants, $context);
            }
        }
    }
    return 1;
}

sub _validate_child_transaction_refs($self, $actor) {
    my %transactions = map { $_->{name} => 1 } @{$actor->{transactions} || []};
    my %transaction_by_name = map { $_->{name} => $_ } @{$actor->{transactions} || []};
    # A per-domain module that owns the SRC side of a cross-domain activation
    # carries a `caller` external-activation entry for a child that lowers in the
    # OTHER domain's module. Such a `(do child)` is honored through promoted
    # handshake ports (see `_wire_external_activations`), so the target need not
    # be a transaction declared in this per-domain module.
    my %external_caller_children = map {
        $_->{child} => 1
    } grep {
        ref($_) eq 'HASH' && ($_->{role} // '') eq 'caller'
    } @{$actor->{external_activations} || []};
    my %generated_children;
    my %generated_instances;
    my @child_refs;
    my $constant_values = _actor_constant_value_map($actor);

    for my $tx (@{$actor->{transactions} || []}) {
        my $tx_name = $tx->{name};
        for my $child_ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx_name, $actor)) {
            my $clause = $child_ref->{clause};
            my $keyword = $child_ref->{keyword};
            my $label = $child_ref->{label};

            _validate_child_action_clause($clause, $tx_name, $label);

            my $target = $clause->[1];
            confess "Transaction '$tx_name': $keyword target must be a scalar transaction name\n"
                unless defined($target) && !ref($target) && length($target);
            confess "Transaction '$tx_name': $keyword target '$target' is not a declared transaction\n"
                unless $transactions{$target} || $external_caller_children{$target};
            # A cross-domain activation caller target is handled through promoted
            # handshake ports, not a same-module child; skip the generated-child
            # bookkeeping below (it would index a transaction that is absent here).
            next if !$transactions{$target} && $external_caller_children{$target};

            if ($keyword eq 'spawn') {
                confess "Transaction '$tx_name': spawn target '$target' conflicts with parent actor module name '$actor->{actor_name}'\n"
                    if $target eq $actor->{actor_name};
                $generated_children{$target} = 1;
            }
            $generated_children{$target} = 1
                if $keyword eq 'do'
                    && ($label eq 'transaction body' || $label eq 'repeat body')
                    && @{_do_parameter_overrides($clause, $tx_name, $label, $constant_values, $actor)};

            push @child_refs, {
                tx                  => $tx,
                tx_name             => $tx_name,
                clause              => $clause,
                keyword             => $keyword,
                target              => $target,
                label               => $label,
                repeat_parent_label => $child_ref->{repeat_parent_label},
                repeat_do_ordinal   => $child_ref->{repeat_do_ordinal},
            };
        }
    }
    for my $rule (@{$actor->{rules} || []}) {
        my $rule_name = $rule->{name};
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'trigger';

            _validate_rule_trigger_action_clause($action, $rule_name, 'rule action');

            my $target = $action->[1];
            confess "Rule '$rule_name': trigger target must be a scalar transaction name\n"
                unless defined($target) && !ref($target) && length($target);
            confess "Rule '$rule_name': trigger target '$target' is not a declared transaction\n"
                unless $transactions{$target};
            $generated_children{$target} = 1
                if @{_trigger_parameter_overrides($action, $rule_name, 'rule action', $constant_values, $actor)};
        }
    }

    for my $ref (@child_refs) {
        my $tx       = $ref->{tx};
        my $tx_name  = $ref->{tx_name};
        my $clause   = $ref->{clause};
        my $keyword  = $ref->{keyword};
        my $target   = $ref->{target};
        my $label    = $ref->{label};
        my $repeat_parent_label = $ref->{repeat_parent_label} // '';
        _validate_repeat_body_do_subset($ref, $actor);

        if ($keyword eq 'do'
            && $label eq 'repeat body'
            && _repeat_body_do_is_generated_activation($clause, $target, \%generated_children)) {
            my $nested_do_label = _nested_repeat_local_do_label($repeat_parent_label);
            my $uses_generated_params = _repeat_body_do_uses_generated_params($clause);
            my $uses_bindings = _repeat_body_do_uses_bindings($clause);
            my $uses_domain = _repeat_body_do_uses_domain($clause);
            my $nested_generated_child_do = (
                (!$uses_domain
                    || (($repeat_parent_label eq 'when body' || $repeat_parent_label eq 'switch branch') && $uses_generated_params))
                && (
                    (($repeat_parent_label eq 'when body' || $repeat_parent_label eq 'switch branch')
                        && !$uses_generated_params
                        && !$uses_bindings
                        && $generated_children{$target})
                    || (($repeat_parent_label eq 'when body' || $repeat_parent_label eq 'switch branch')
                        && $uses_generated_params)
                )
            );
            confess "Transaction '$tx_name': $nested_do_label nested repeat do supports only local child targets; target '$target' is already generated by another activation site\n"
                if defined($nested_do_label) && !$nested_generated_child_do;
        }

        my $repeat_body_generated_do = $keyword eq 'do'
            && $label eq 'repeat body'
            && _repeat_body_do_is_generated_activation($clause, $target, \%generated_children);
        my $generated_activation = $keyword eq 'spawn'
            || ($keyword eq 'do' && $label eq 'transaction body' && $generated_children{$target})
            || $repeat_body_generated_do;
        next unless $generated_activation;

        confess "Transaction '$tx_name': $keyword target '$target' conflicts with parent actor module name '$actor->{actor_name}'\n"
            if $target eq $actor->{actor_name};

        my $instance = $keyword eq 'spawn'
            ? $clause->[3]
            : $repeat_body_generated_do
                ? _generated_repeat_do_instance_name($tx_name, $target, $ref->{repeat_do_ordinal} // 0)
                : _generated_do_instance_name($tx_name, $target, _do_clause_ordinal($tx, $clause));

        confess "Transaction '$tx_name': $keyword instance '$instance' conflicts with parent actor instance name '$actor->{actor_name}'\n"
            if $instance eq $actor->{actor_name};
        if (my $previous = $generated_instances{$instance}) {
            my $duplicate_label = $keyword eq 'spawn' && $previous->{keyword} eq 'spawn'
                ? 'duplicate spawn instance'
                : 'duplicate generated child instance';
            confess "Transaction '$tx_name': $duplicate_label '$instance' in actor '$actor->{actor_name}'\n";
        }
        $generated_instances{$instance} = {
            keyword => $keyword,
            owner   => $tx_name,
            target  => $target,
        };

        my $declared_param_list = _transaction_param_declarations($transaction_by_name{$target}, $actor);
        my %declared_params = map {
            $_->{name} => $_
        } @$declared_param_list;
        my $repeat_count_params =
            _transaction_repeat_count_param_names($transaction_by_name{$target}, $declared_param_list);
        my $wait_count_params =
            _transaction_wait_count_param_names($transaction_by_name{$target}, $declared_param_list);
        my $latency_bound_params =
            _transaction_latency_bound_param_names($transaction_by_name{$target}, $declared_param_list);
        my $watchdog_limit_params =
            _transaction_watchdog_limit_param_names($transaction_by_name{$target}, $declared_param_list);
        my $data_op_width_params =
            _transaction_data_op_width_param_names($transaction_by_name{$target}, $declared_param_list);
        my $port_width_params =
            _transaction_port_width_param_names($transaction_by_name{$target}, $declared_param_list);
        for my $override (@{_activation_parameter_overrides($clause, $tx_name, $label, $constant_values, $actor)}) {
            my $name = $override->{name};
            confess "Transaction '$tx_name': $keyword instance '$instance' overrides unknown parameter '$name' on child '$target'\n"
                unless exists $declared_params{$name};
            confess "Transaction '$tx_name': $keyword instance '$instance' parameter '$name' shape does not match child '$target' declaration\n"
                unless _param_values_shape_compatible($declared_params{$name}{value}, $override->{value});
            confess "Transaction '$tx_name': $keyword instance '$instance' overrides repeat-count parameter '$name' on child '$target'; activation-site parameter override-specialized repeat counts remain deferred\n"
                if $repeat_count_params->{$name}
                    && !_activation_override_preserves_repeat_count_param($declared_params{$name}, $override);
            confess "Transaction '$tx_name': $keyword instance '$instance' overrides wait-count parameter '$name' on child '$target'; activation-site parameter override-specialized wait counts remain deferred\n"
                if $wait_count_params->{$name}
                    && !_activation_override_preserves_wait_count_param($declared_params{$name}, $override);
            confess "Transaction '$tx_name': $keyword instance '$instance' overrides latency-bound parameter '$name' on child '$target'; activation-site parameter override-specialized latency bounds remain deferred\n"
                if $latency_bound_params->{$name}
                    && !_activation_override_preserves_latency_bound_param($declared_params{$name}, $override);
            confess "Transaction '$tx_name': $keyword instance '$instance' overrides watchdog-limit parameter '$name' on child '$target'; activation-site parameter override-specialized watchdog limits remain deferred\n"
                if $watchdog_limit_params->{$name}
                    && !_activation_override_preserves_watchdog_limit_param($declared_params{$name}, $override);
            confess "Transaction '$tx_name': $keyword instance '$instance' overrides static-width parameter '$name' on child '$target'; activation-site parameter override-specialized data-op widths remain deferred\n"
                if $data_op_width_params->{$name}
                    && !_activation_override_preserves_data_op_width_param($declared_params{$name}, $override);
            confess "Transaction '$tx_name': $keyword instance '$instance' overrides static port-width parameter '$name' on child '$target'; activation-site parameter override-specialized transaction port widths remain deferred\n"
                if $port_width_params->{$name}
                    && !_activation_override_preserves_port_width_param($declared_params{$name}, $override);
        }
    }

    for my $ref (_rule_trigger_generated_refs($actor, \%generated_children)) {
        my $rule_name = $ref->{owner};
        my $target = $ref->{child};
        my $instance = $ref->{instance};

        confess "Rule '$rule_name': trigger target '$target' conflicts with parent actor module name '$actor->{actor_name}'\n"
            if $target eq $actor->{actor_name};
        confess "Rule '$rule_name': trigger instance '$instance' conflicts with parent actor instance name '$actor->{actor_name}'\n"
            if $instance eq $actor->{actor_name};
        if (my $previous = $generated_instances{$instance}) {
            confess "Rule '$rule_name': duplicate generated child instance '$instance' in actor '$actor->{actor_name}'\n";
        }
        $generated_instances{$instance} = {
            keyword => 'trigger',
            owner   => $rule_name,
            target  => $target,
        };

        my $declared_param_list = _transaction_param_declarations($transaction_by_name{$target}, $actor);
        my %declared_params = map {
            $_->{name} => $_
        } @$declared_param_list;
        my $repeat_count_params =
            _transaction_repeat_count_param_names($transaction_by_name{$target}, $declared_param_list);
        my $wait_count_params =
            _transaction_wait_count_param_names($transaction_by_name{$target}, $declared_param_list);
        my $latency_bound_params =
            _transaction_latency_bound_param_names($transaction_by_name{$target}, $declared_param_list);
        my $watchdog_limit_params =
            _transaction_watchdog_limit_param_names($transaction_by_name{$target}, $declared_param_list);
        my $data_op_width_params =
            _transaction_data_op_width_param_names($transaction_by_name{$target}, $declared_param_list);
        my $port_width_params =
            _transaction_port_width_param_names($transaction_by_name{$target}, $declared_param_list);
        for my $override (@{$ref->{parameter_overrides} || []}) {
            my $name = $override->{name};
            confess "Rule '$rule_name': trigger instance '$instance' overrides unknown parameter '$name' on child '$target'\n"
                unless exists $declared_params{$name};
            confess "Rule '$rule_name': trigger instance '$instance' parameter '$name' shape does not match child '$target' declaration\n"
                unless _param_values_shape_compatible($declared_params{$name}{value}, $override->{value});
            confess "Rule '$rule_name': trigger instance '$instance' overrides repeat-count parameter '$name' on child '$target'; activation-site parameter override-specialized repeat counts remain deferred\n"
                if $repeat_count_params->{$name}
                    && !_activation_override_preserves_repeat_count_param($declared_params{$name}, $override);
            confess "Rule '$rule_name': trigger instance '$instance' overrides wait-count parameter '$name' on child '$target'; activation-site parameter override-specialized wait counts remain deferred\n"
                if $wait_count_params->{$name}
                    && !_activation_override_preserves_wait_count_param($declared_params{$name}, $override);
            confess "Rule '$rule_name': trigger instance '$instance' overrides latency-bound parameter '$name' on child '$target'; activation-site parameter override-specialized latency bounds remain deferred\n"
                if $latency_bound_params->{$name}
                    && !_activation_override_preserves_latency_bound_param($declared_params{$name}, $override);
            confess "Rule '$rule_name': trigger instance '$instance' overrides watchdog-limit parameter '$name' on child '$target'; activation-site parameter override-specialized watchdog limits remain deferred\n"
                if $watchdog_limit_params->{$name}
                    && !_activation_override_preserves_watchdog_limit_param($declared_params{$name}, $override);
            confess "Rule '$rule_name': trigger instance '$instance' overrides static-width parameter '$name' on child '$target'; activation-site parameter override-specialized data-op widths remain deferred\n"
                if $data_op_width_params->{$name}
                    && !_activation_override_preserves_data_op_width_param($declared_params{$name}, $override);
            confess "Rule '$rule_name': trigger instance '$instance' overrides static port-width parameter '$name' on child '$target'; activation-site parameter override-specialized transaction port widths remain deferred\n"
                if $port_width_params->{$name}
                    && !_activation_override_preserves_port_width_param($declared_params{$name}, $override);
        }
    }

    return 1;
}

sub _validate_transaction_parameter_clauses($self, $actor, $generated_children, $pruned_transactions = undef) {
    $pruned_transactions ||= {};
    for my $tx (@{$actor->{transactions} || []}) {
        my $params = _transaction_param_declarations($tx, $actor);
        next unless @$params;

        my $tx_name = $tx->{name};
        next if $generated_children->{$tx_name};
        next if $pruned_transactions->{$tx_name};
        next if _transaction_params_used_by_monitor_window($tx, $params);
        next if _transaction_params_used_by_data_op_width($tx, $params);
        next if _transaction_params_used_by_transaction_port_width($tx, $params);
        next if _transaction_params_used_by_repeat_count($tx, $params);
        next if _transaction_params_used_by_wait_count($tx, $params);
        next if _transaction_params_used_by_latency_bound($tx, $params);
        next if _transaction_params_used_by_watchdog_limit($tx, $params);

        confess "Transaction '$tx_name': params are supported only on generated child transactions, same-transaction temporal contract or monitor windows, same-transaction data-operation width evidence, same-transaction transaction-port width evidence, same-transaction repeat counts, same-transaction wait counts, same-transaction latency bounds, or same-transaction top-level await-local watchdog limits\n";
    }
    return 1;
}

# ISF-TRIGGER-ANCHOR.4: a check's `(monitor (within S N))` window may reference a transaction/actor
# parameter exactly like a `(contract …)` window, so the parameter-usage gate must recognise it too.
sub _transaction_params_used_by_monitor_window {
    my ($tx, $params) = @_;
    my $used = _transaction_monitor_window_param_names($tx, $params);
    return keys %$used ? 1 : 0;
}

sub _transaction_monitor_window_param_names {
    my ($tx, $params) = @_;
    return {} unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return {} unless keys %declared;

    my %used;
    for my $clause (@{$tx->{clauses} || []}) {
        my $value = _monitor_within_value_if_present($clause);
        _collect_isf_value_declared_name_refs($value, \%declared, \%used)
            if defined $value;
    }

    return \%used;
}

# The `within` token of a check's `(monitor (within S N))` clause, or undef if the clause is not one.
# Clause shape (plain nested arrays): ['assert'|'cover'|'assume', ['monitor', ['within', S, N]], "msg"?].
sub _monitor_within_value_if_present {
    my ($clause) = @_;
    return undef unless ref($clause) eq 'ARRAY'
        && defined($clause->[0])
        && !ref($clause->[0])
        && ($clause->[0] eq 'assert' || $clause->[0] eq 'cover' || $clause->[0] eq 'assume')
        && ref($clause->[1]) eq 'ARRAY'
        && defined($clause->[1][0])
        && !ref($clause->[1][0])
        && $clause->[1][0] eq 'monitor'
        && ref($clause->[1][1]) eq 'ARRAY';

    my $within = $clause->[1][1];
    return undef unless @$within == 3
        && defined($within->[0])
        && !ref($within->[0])
        && $within->[0] eq 'within'
        && defined($within->[2]);

    return $within->[2];
}

sub _transaction_params_used_by_data_op_width {
    my ($tx, $params) = @_;
    return 0 unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return 0 unless keys %declared;

    my %used;
    _collect_data_op_width_declared_name_refs($tx->{clauses}, \%declared, \%used);
    return keys %used ? 1 : 0;
}

sub _transaction_params_used_by_transaction_port_width {
    my ($tx, $params) = @_;
    return 0 unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return 0 unless keys %declared;

    my $used = $tx->{_transaction_param_port_widths};
    return 0 unless ref($used) eq 'HASH';
    for my $name (keys %$used) {
        return 1 if $declared{$name};
    }
    return 0;
}

sub _transaction_params_used_by_repeat_count {
    my ($tx, $params) = @_;
    return keys %{_transaction_repeat_count_param_names($tx, $params)} ? 1 : 0;
}

sub _transaction_params_used_by_wait_count {
    my ($tx, $params) = @_;
    return keys %{_transaction_wait_count_param_names($tx, $params)} ? 1 : 0;
}

sub _transaction_params_used_by_latency_bound {
    my ($tx, $params) = @_;
    return keys %{_transaction_latency_bound_param_names($tx, $params)} ? 1 : 0;
}

sub _transaction_params_used_by_watchdog_limit {
    my ($tx, $params) = @_;
    return keys %{_transaction_watchdog_limit_param_names($tx, $params)} ? 1 : 0;
}

sub _transaction_repeat_count_param_names {
    my ($tx, $params) = @_;
    return {} unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return {} unless keys %declared;

    my %used;
    _collect_repeat_count_declared_name_refs($tx->{clauses}, \%declared, \%used);
    return \%used;
}

sub _transaction_wait_count_param_names {
    my ($tx, $params) = @_;
    return {} unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return {} unless keys %declared;

    my %used;
    _collect_wait_count_declared_name_refs($tx->{clauses}, \%declared, \%used);
    return \%used;
}

sub _transaction_latency_bound_param_names {
    my ($tx, $params) = @_;
    return {} unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return {} unless keys %declared;

    my %used;
    _collect_latency_bound_declared_name_refs($tx->{clauses}, \%declared, \%used);
    return \%used;
}

sub _transaction_watchdog_limit_param_names {
    my ($tx, $params) = @_;
    return {} unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return {} unless keys %declared;

    my %used;
    _collect_await_watchdog_declared_name_refs($tx->{clauses}, \%declared, \%used);
    return \%used;
}

sub _collect_repeat_count_declared_name_refs {
    my ($node, $declared, $used) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 2 && defined($node->[0]) && !ref($node->[0]) && $node->[0] eq 'repeat') {
        _collect_isf_value_declared_name_refs($node->[1], $declared, $used);
    }

    for my $child (@$node) {
        _collect_repeat_count_declared_name_refs($child, $declared, $used)
            if ref($child) eq 'ARRAY';
    }
}

sub _collect_wait_count_declared_name_refs {
    my ($node, $declared, $used) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 2 && defined($node->[0]) && !ref($node->[0]) && $node->[0] eq 'wait') {
        _collect_isf_value_declared_name_refs($node->[1], $declared, $used);
    }

    for my $child (@$node) {
        _collect_wait_count_declared_name_refs($child, $declared, $used)
            if ref($child) eq 'ARRAY';
    }
}

sub _collect_latency_bound_declared_name_refs {
    my ($node, $declared, $used) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 2 && defined($node->[0]) && !ref($node->[0]) && $node->[0] eq 'latency') {
        for my $option (@{$node}[1 .. $#$node]) {
            next unless ref($option) eq 'ARRAY'
                && @$option == 2
                && defined($option->[0])
                && !ref($option->[0])
                && ($option->[0] eq 'min' || $option->[0] eq 'max');
            _collect_isf_value_declared_name_refs($option->[1], $declared, $used);
        }
    }

    for my $child (@$node) {
        _collect_latency_bound_declared_name_refs($child, $declared, $used)
            if ref($child) eq 'ARRAY';
    }
}

sub _collect_await_watchdog_declared_name_refs {
    my ($clauses, $declared, $used) = @_;
    return unless ref($clauses) eq 'ARRAY';

    for my $node (@$clauses) {
        next unless ref($node) eq 'ARRAY'
            && @$node >= 3
            && defined($node->[0])
            && !ref($node->[0])
            && $node->[0] eq 'await';
        for my $option (@{$node}[2 .. $#$node]) {
            next unless ref($option) eq 'ARRAY'
                && @$option == 2
                && defined($option->[0])
                && !ref($option->[0])
                && $option->[0] eq 'watchdog';
            _collect_isf_value_declared_name_refs($option->[1], $declared, $used);
        }
    }
}

sub _collect_data_op_width_declared_name_refs {
    my ($node, $declared, $used) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node && defined($node->[0]) && !ref($node->[0])) {
        my $keyword = $node->[0];
        if ($keyword eq 'shift_left' || $keyword eq 'shift_right') {
            for my $option (@{$node}[3 .. $#$node]) {
                next unless ref($option) eq 'ARRAY'
                    && @$option >= 2
                    && defined($option->[0])
                    && !ref($option->[0])
                    && $option->[0] eq 'width';
                _collect_isf_value_declared_name_refs($option->[1], $declared, $used);
            }
        }
        elsif ($keyword eq 'assemble' || $keyword eq 'extract') {
            for my $option (@$node) {
                next unless ref($option) eq 'ARRAY'
                    && @$option >= 2
                    && defined($option->[0])
                    && !ref($option->[0])
                    && $option->[0] eq 'widths';
                for my $width (@{$option}[1 .. $#$option]) {
                    _collect_isf_value_declared_name_refs($width, $declared, $used);
                }
            }
        }
    }

    for my $child (@$node) {
        _collect_data_op_width_declared_name_refs($child, $declared, $used)
            if ref($child) eq 'ARRAY';
    }
}

sub _transaction_data_op_width_param_names {
    my ($tx, $params) = @_;
    return {} unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return {} unless keys %declared;

    my %used;
    _collect_data_op_width_declared_name_refs($tx->{clauses}, \%declared, \%used);
    return \%used;
}

sub _transaction_port_width_param_names {
    my ($tx, $params) = @_;
    return {} unless ref($tx) eq 'HASH' && ref($params) eq 'ARRAY' && @$params;

    my %declared = map { ($_->{name} // '') => 1 } grep { ref($_) eq 'HASH' } @$params;
    return {} unless keys %declared;

    my $used = $tx->{_transaction_param_port_widths};
    return {} unless ref($used) eq 'HASH';

    my %filtered;
    for my $name (keys %$used) {
        $filtered{$name} = 1 if $declared{$name};
    }
    return \%filtered;
}

