sub _build_child_ports {
    my ($self, $actor, $tx, $states, $dts, $used_drives) = @_;

    my %local_ports = _transaction_port_map($tx);
    my %actor_output_width = map {
        $_->{name} => ($_->{width} // 1)
    } @{$actor->{interface}{outputs} || []};

    my @ports;
    my %seen;
    for my $input (@{$actor->{interface}{inputs} || []}) {
        next if exists $local_ports{$input->{name}};
        _push_port(\@ports, \%seen, $input->{name}, 'input', $input->{width} // 1);
    }

    for my $input (@{($tx->{ports} || {})->{inputs} || []}) {
        _push_port(\@ports, \%seen, $input->{name}, 'input', $input->{width} // 1);
    }

    my %assigned_public_outputs;
    for my $assignment (_all_ir_assignments($states, $dts)) {
        my $lhs = $assignment->{lhs};
        next unless defined($lhs) && !ref($lhs);
        next if exists $local_ports{$lhs};
        next unless exists $actor_output_width{$lhs};
        next if ($assignment->{source_kind} // '') =~ /\Adrive_call_/;
        $assigned_public_outputs{$lhs} = 1;
    }

    for my $name (sort keys %assigned_public_outputs) {
        _push_port(\@ports, \%seen, $name, 'output', $actor_output_width{$name});
    }

    for my $output (@{($tx->{ports} || {})->{outputs} || []}) {
        _push_port(\@ports, \%seen, $output->{name}, 'output', $output->{width} // 1);
    }

    _push_port(\@ports, \%seen, 'start', 'input', 1);
    _push_port(\@ports, \%seen, 'done', 'output', 1);

    for my $drive_name (sort keys %{$used_drives || {}}) {
        my $drive = ($actor->{drives} || {})->{$drive_name} || next;
        _push_port(\@ports, \%seen, "${drive_name}_start", 'output', 1);
        for my $param (@{$drive->{params} || []}) {
            _push_port(\@ports, \%seen, "${drive_name}_$param", 'output',
                _drive_param_width($actor, $drive_name, $param));
        }
    }

    return \@ports;
}

sub _push_port {
    my ($ports, $seen, $name, $direction, $width) = @_;
    return if !defined($name) || ref($name) || !length($name);
    return if $seen->{$name}++;
    push @$ports, { name => $name, direction => $direction, width => $width || 1 };
}

sub _ensure_port {
    my ($ports, $name, $direction, $width, $context) = @_;
    for my $port (@$ports) {
        my $prefix = defined($context) && length($context)
            ? $context
            : 'ISF generated handoff';
        confess "$prefix port '$name' conflicts with existing actor interface port '$name'\n"
            if $port->{name} eq $name;
    }
    push @$ports, { name => $name, direction => $direction, width => $width, isf_handoff => 1 };
}

sub _collect_named_drive_call_names {
    my ($node, $drives) = @_;
    my %used;
    _collect_named_drive_call_names_into($node, $drives || {}, \%used);
    return %used;
}

sub _collect_named_drive_call_names_into {
    my ($node, $drives, $used) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 2
        && defined($node->[0])
        && !ref($node->[0])
        && $node->[0] eq 'drive'
        && defined($node->[1])
        && !ref($node->[1])
        && exists $drives->{$node->[1]})
    {
        $used->{$node->[1]} = 1;
    }

    for my $child (@$node) {
        _collect_named_drive_call_names_into($child, $drives, $used)
            if ref($child) eq 'ARRAY';
    }
}

sub _register_drive_call_signal_widths {
    my ($actor, $counters, $used_drives, $storage_roles) = @_;
    for my $drive_name (sort keys %{$used_drives || {}}) {
        my $drive = ($actor->{drives} || {})->{$drive_name} || next;
        $counters->{"${drive_name}_start"} = 1;
        $storage_roles->{"${drive_name}_start"} = 'drive_request'
            if ref($storage_roles) eq 'HASH';
        for my $param (@{$drive->{params} || []}) {
            $counters->{"${drive_name}_$param"} = _drive_param_width($actor, $drive_name, $param);
            $storage_roles->{"${drive_name}_$param"} = 'drive_payload'
                if ref($storage_roles) eq 'HASH';
        }
    }
}

sub _drive_param_width {
    my ($actor, $drive_name, $param) = @_;
    my $drive = ($actor->{drives} || {})->{$drive_name} || {};
    my $width = 1;
    for my $pair (@{$drive->{body} || []}) {
        next unless ref($pair) eq 'ARRAY' && @$pair >= 2 && $pair->[1] eq $param;
        for my $port (@{$actor->{interface}{outputs} || []}) {
            $width = $port->{width} if $port->{name} eq $pair->[0];
        }
    }
    return $width || 1;
}

sub _all_ir_assignments {
    my ($states, $dts) = @_;
    my @assignments;
    for my $state (@{$states || []}) {
        push @assignments, @{$state->{assignments} || []};
    }
    for my $dt (@{$dts || []}) {
        push @assignments, @{$dt->{assignments} || []};
    }
    return @assignments;
}

sub _build_signal_width_map {
    my ($actor, $tx) = @_;
    my %widths;
    for my $i (@{$actor->{interface}{inputs}})  { $widths{$i->{name}} = $i->{width} // 1; }
    for my $o (@{$actor->{interface}{outputs}}) { $widths{$o->{name}} = $o->{width} // 1; }
    for my $entry (@{$actor->{storage} || []}) {
        for my $signal (@{$entry->{signals} || []}) {
            $widths{$signal->{name}} = $signal->{width};
        }
    }
    for my $direction (qw(inputs outputs)) {
        for my $port (@{($tx->{ports} || {})->{$direction} || []}) {
            $widths{$port->{name}} = $port->{width} // 1;
        }
    }
    _collect_sample_widths($tx->{clauses}, \%widths);
    my $record_samples = FSM::Scheduler::ISF::RecordSamples->transaction_plan($actor, $tx);
    for my $alias (keys %{$record_samples ? $record_samples->{record_aliases} : {}}) {
        $widths{$alias} = $record_samples->{bindings}{$alias}{type_spec}{width};
    }
    _collect_shift_widths($tx->{clauses}, \%widths, $actor, $tx->{name});
    _collect_data_widths($tx->{clauses}, \%widths, $actor, $tx->{name});
    _collect_extract_widths($tx->{clauses}, \%widths, $actor, $tx->{name});
    _collect_data_widths($tx->{clauses}, \%widths, $actor, $tx->{name});
    return \%widths;
}

sub _collect_sample_widths {
    my ($node, $widths) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 4 && $node->[0] eq 'sample' && $node->[2] eq 'as') {
        my ($source, $alias) = ($node->[1], $node->[3]);
        $widths->{$alias} = $widths->{$source} if exists $widths->{$source};
    }

    for my $child (@$node) {
        _collect_sample_widths($child, $widths) if ref($child) eq 'ARRAY';
    }
}

sub _collect_data_widths {
    my ($node, $widths, $actor, $tn) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 4 && $node->[0] eq 'assemble') {
        my ($target, $parts, $explicit_widths) = _parse_assemble_clause($node, $actor, $tn);
        my ($part_widths, $total) = _resolve_assemble_widths($target, $parts, $explicit_widths, $widths);
        for my $idx (0 .. $#$parts) {
            next unless defined($part_widths->[$idx]) && $part_widths->[$idx] > 0;
            my $part = $parts->[$idx];
            $widths->{$part} = $part_widths->[$idx]
                unless exists($widths->{$part}) && defined($widths->{$part}) && $widths->{$part} > 0;
        }
        $widths->{$target} = $total
            if defined($total)
                && $total > 0
                && !(defined($widths->{$target}) && $widths->{$target} > 0);
    }

    for my $child (@$node) {
        _collect_data_widths($child, $widths, $actor, $tn) if ref($child) eq 'ARRAY';
    }
}

sub _collect_shift_widths {
    my ($node, $widths, $actor, $tn) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 4 && ($node->[0] eq 'shift_left' || $node->[0] eq 'shift_right')) {
        my $keyword = $node->[0];
        my $explicit_width = _static_data_width_evidence_value(
            _parse_shift_width($node, $keyword),
            $actor,
            $tn,
            "$keyword width",
        );
        my $target = $node->[1];
        if (defined($explicit_width) && defined($target) && !ref($target)) {
            my $known_width = $widths->{$target};
            confess "$keyword explicit width $explicit_width conflicts with known width $known_width for '$target'\n"
                if defined($known_width) && $known_width > 0 && $known_width != $explicit_width;
            $widths->{$target} = $explicit_width unless defined($known_width) && $known_width > 0;
        }
    }

    for my $child (@$node) {
        _collect_shift_widths($child, $widths, $actor, $tn) if ref($child) eq 'ARRAY';
    }
}

sub _collect_extract_widths {
    my ($node, $widths, $actor, $tn) = @_;
    return unless ref($node) eq 'ARRAY';

    if (@$node >= 4 && $node->[0] eq 'extract') {
        my ($word, $fields, $explicit_widths) = _parse_extract_clause($node, $actor, $tn);
        my @field_widths = _resolve_extract_field_widths(
            $word,
            $fields,
            $explicit_widths,
            $widths,
            { strict => 0 },
        );
        for my $idx (0 .. $#$fields) {
            next unless defined($field_widths[$idx]) && $field_widths[$idx] > 0;
            my $field = $fields->[$idx];
            $widths->{$field} = $field_widths[$idx]
                unless exists($widths->{$field}) && defined($widths->{$field}) && $widths->{$field} > 0;
        }
    }

    for my $child (@$node) {
        _collect_extract_widths($child, $widths, $actor, $tn) if ref($child) eq 'ARRAY';
    }
}

sub _as_index {
    my ($cl, $start) = @_;
    for my $idx ($start .. $#$cl) {
        return $idx if defined $cl->[$idx] && !ref($cl->[$idx]) && $cl->[$idx] eq 'as';
    }
    return undef;
}

sub _parse_assemble_clause {
    my ($cl, $actor, $tn) = @_;
    my $as_idx = _as_index($cl, 2);
    confess "assemble requires '(assemble part... as target [(widths N|TX_PARAM|PARAM|CONST|PACKAGE.CONSTANT...)])'\n"
        unless defined $as_idx && $as_idx > 1 && ($as_idx == $#$cl - 1 || $as_idx == $#$cl - 2);

    my @parts = @{$cl}[1 .. $as_idx - 1];
    my $target = $cl->[$as_idx + 1];
    my @raw_explicit_widths;
    my $saw_widths;

    if ($as_idx == $#$cl - 2) {
        my $option = $cl->[$as_idx + 2];
        confess "assemble optional arguments must be '(widths N|TX_PARAM|PARAM|CONST|PACKAGE.CONSTANT...)'\n"
            unless ref($option) eq 'ARRAY'
                && @$option >= 1
                && defined($option->[0])
                && !ref($option->[0])
                && $option->[0] eq 'widths';
        $saw_widths = 1;
        @raw_explicit_widths = @{$option}[1 .. $#$option];
        for my $width (@raw_explicit_widths) {
            confess "assemble widths must be positive integer literals, same-transaction scalar parameters, actor constants, actor scalar parameters, or qualified package scalar constants\n"
                if !defined($width) || ref($width) || !length($width);
        }
    }

    for my $part (@parts) {
        confess "assemble parts must be scalar names\n"
            if !defined($part) || ref($part) || !length($part);
    }
    confess "assemble target must be a scalar name\n"
        if !defined($target) || ref($target) || !length($target);
    confess "assemble '(widths ...)' count must match the part count\n"
        if $saw_widths && @raw_explicit_widths != @parts;

    my @explicit_widths;
    for my $idx (0 .. $#raw_explicit_widths) {
        push @explicit_widths, _static_data_width_evidence_value(
            $raw_explicit_widths[$idx],
            $actor,
            $tn,
            "assemble width for '$parts[$idx]'",
        );
    }

    return ($target, \@parts, \@explicit_widths);
}

sub _resolve_assemble_widths {
    my ($target, $parts, $explicit_widths, $widths) = @_;
    my @part_widths;
    my @unknown_indices;
    my $known_total = 0;

    for my $idx (0 .. $#$parts) {
        my $part = $parts->[$idx];
        my $explicit_width = $explicit_widths->[$idx];
        my $known_width = $widths->{$part};

        confess "assemble explicit width for '$part' conflicts with known width\n"
            if defined($explicit_width)
                && defined($known_width)
                && $known_width > 0
                && $explicit_width != $known_width;

        my $part_width = defined($explicit_width) ? $explicit_width : $known_width;
        if (defined($part_width) && $part_width > 0) {
            $part_widths[$idx] = $part_width;
            $known_total += $part_width;
            next;
        }

        push @unknown_indices, $idx;
    }

    my $target_width = $widths->{$target};
    if (@unknown_indices == 1 && defined($target_width) && $target_width > 0) {
        my $idx = $unknown_indices[0];
        my $part = $parts->[$idx];
        my $inferred_width = $target_width - $known_total;
        confess "assemble known part widths sum $known_total leaves no positive width for '$part' in known width $target_width target '$target'\n"
            unless $inferred_width > 0;
        $part_widths[$idx] = $inferred_width;
        @unknown_indices = ();
    }

    return (\@part_widths, undef) if @unknown_indices;

    my $total = 0;
    $total += $_ for @part_widths;
    confess "assemble part widths sum $total conflicts with known width $target_width for '$target'\n"
        if defined($target_width) && $target_width > 0 && $target_width != $total;

    return (\@part_widths, $total);
}

sub _parse_extract_clause {
    my ($cl, $actor, $tn) = @_;
    confess "extract requires '(extract word as field...)'\n"
        unless @$cl >= 4 && defined $cl->[2] && !ref($cl->[2]) && $cl->[2] eq 'as';

    my $word = $cl->[1];
    my @items = @{$cl}[3 .. $#$cl];
    my @fields;
    my @raw_explicit_widths;
    my $saw_widths;

    confess "extract word must be a scalar name\n"
        if !defined($word) || ref($word) || !length($word);
    confess "extract requires at least one scalar field\n" unless @items;

    for my $item (@items) {
        if (ref($item) eq 'ARRAY') {
            confess "extract field must be a scalar name\n"
                if @$item == 1 || grep { !defined($_) || ref($_) } @$item;
            confess "extract accepts at most one '(widths ...)' option\n"
                if $saw_widths;
            confess "extract optional arguments must be '(widths N|TX_PARAM|PARAM|CONST|PACKAGE.CONSTANT...)'\n"
                unless @$item >= 2
                    && defined($item->[0])
                    && !ref($item->[0])
                    && $item->[0] eq 'widths';
            $saw_widths = 1;
            @raw_explicit_widths = @{$item}[1 .. $#$item];
            for my $width (@raw_explicit_widths) {
                confess "extract widths must be positive integer literals, same-transaction scalar parameters, actor constants, actor scalar parameters, or qualified package scalar constants\n"
                    if !defined($width) || ref($width) || !length($width);
            }
            next;
        }

        confess "extract fields must precede the '(widths ...)' option\n" if $saw_widths;
        confess "extract field must be a scalar name\n"
            if !defined($item) || ref($item) || !length($item);
        push @fields, $item;
    }

    confess "extract requires at least one scalar field\n" unless @fields;
    confess "extract '(widths ...)' count must match the field count\n"
        if @raw_explicit_widths && @raw_explicit_widths != @fields;

    my @explicit_widths;
    for my $idx (0 .. $#raw_explicit_widths) {
        push @explicit_widths, _static_data_width_evidence_value(
            $raw_explicit_widths[$idx],
            $actor,
            $tn,
            "extract width for '$fields[$idx]'",
        );
    }

    return ($word, \@fields, \@explicit_widths);
}

sub _resolve_extract_field_widths {
    my ($word, $fields, $explicit_widths, $widths, $options) = @_;
    $options ||= {};
    my $strict = exists($options->{strict}) ? $options->{strict} : 1;
    my @field_widths;
    my @unknown_indices;
    my $known_total = 0;

    for my $idx (0 .. $#$fields) {
        my $field = $fields->[$idx];
        my $explicit_width = $explicit_widths->[$idx];
        my $known_width = $widths->{$field};

        confess "extract explicit width for '$field' conflicts with known width\n"
            if defined($explicit_width)
                && defined($known_width)
                && $known_width > 0
                && $explicit_width != $known_width;

        my $field_width = defined($explicit_width) ? $explicit_width : $known_width;
        if (defined($field_width) && $field_width > 0) {
            $field_widths[$idx] = $field_width;
            $known_total += $field_width;
            next;
        }

        push @unknown_indices, $idx;
    }

    my $word_width = $widths->{$word};
    if (@unknown_indices == 1 && defined($word_width) && $word_width > 0) {
        my $idx = $unknown_indices[0];
        my $field = $fields->[$idx];
        my $inferred_width = $word_width - $known_total;
        confess "extract known field widths sum $known_total leaves no positive width for '$field' in known width $word_width source '$word'\n"
            unless $inferred_width > 0;
        $field_widths[$idx] = $inferred_width;
        @unknown_indices = ();
    }

    for my $idx (@unknown_indices) {
        my $field = $fields->[$idx];
        confess "extract width for '$field' is unknown; add an interface width or '(widths ...)' option\n"
            if $strict;
    }

    my $total_field_width = 0;
    my $all_fields_known = 1;
    for my $idx (0 .. $#$fields) {
        my $field_width = $field_widths[$idx];
        if (defined($field_width) && $field_width > 0) {
            $total_field_width += $field_width;
            next;
        }
        $all_fields_known = 0;
    }
    confess "extract field widths sum $total_field_width conflicts with known width $word_width for '$word'\n"
        if $all_fields_known && defined($word_width) && $word_width > 0 && $word_width != $total_field_width;

    return @field_widths;
}

sub _parse_shift_right_width {
    return _parse_shift_width($_[0], 'shift_right');
}

sub _parse_shift_left_width {
    return _parse_shift_width($_[0], 'shift_left');
}

sub _parse_shift_width {
    my ($cl, $keyword) = @_;
    $keyword //= $cl->[0];
    my $width;

    for my $idx (3 .. $#$cl) {
        my $option = $cl->[$idx];
        confess "$keyword optional arguments must be '(width N|TX_PARAM|PARAM|CONST|PACKAGE.CONSTANT)'\n"
            unless ref($option) eq 'ARRAY' && @$option == 2 && $option->[0] eq 'width';
        confess "$keyword accepts at most one '(width N|TX_PARAM|PARAM|CONST|PACKAGE.CONSTANT)' option\n"
            if defined $width;
        confess "$keyword width must be a positive integer literal, same-transaction scalar parameter, actor constant, actor scalar parameter, or qualified package scalar constant\n"
            if !defined($option->[1]) || ref($option->[1]) || !length($option->[1]);
        confess "$keyword width must be a positive integer literal, same-transaction scalar parameter, actor constant, actor scalar parameter, or qualified package scalar constant\n"
            unless $option->[1] =~ /\A[1-9][0-9]*\z/
                || _is_hdl_identifier($option->[1])
                || _is_package_constant_reference_shape($option->[1]);
        $width = $option->[1] =~ /\A[1-9][0-9]*\z/ ? 0 + $option->[1] : $option->[1];
    }

    return $width;
}

sub _static_data_width_evidence_value {
    my ($token, $actor, $tn, $context) = @_;
    return undef unless defined($token);
    $tn //= 'unknown';
    $context //= 'data-operation width';

    return 0 + $token
        if !ref($token) && $token =~ /\A[1-9][0-9]*\z/;

    my $accepted_sources = 'positive integer literals, same-transaction scalar parameters, actor constants, actor scalar parameters, or qualified package scalar constants';

    confess "$context must be a positive integer literal, same-transaction scalar parameter, actor constant, actor scalar parameter, or qualified package scalar constant\n"
        if ref($token)
            || !length($token)
            || (!_is_hdl_identifier($token) && !_is_package_constant_reference_shape($token));

    if (my $package_constant = _actor_package_constant_reference($actor, $token)) {
        my ($package_name, $constant_name, $suffix) = @$package_constant;
        my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
        if (defined $constant_payload) {
            confess "Transaction '$tn': $context token '$token' is ambiguous: it matches local enum member '$token' and imported package constant '$token'\n"
                if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
            confess "Transaction '$tn': $context package constant '$package_name.$constant_name' aggregate/member path '$token' remains deferred; data-operation width evidence accepts only qualified package scalar constants in this slice\n"
                if $suffix ne '';
            my $constant_value = _package_constant_scalar_value($constant_payload);
            my $integer_value = defined($constant_value) && !ref($constant_value)
                ? _non_negative_integer_from_literal($constant_value)
                : undef;
            confess "Transaction '$tn': $context package constant '$package_name.$constant_name' must resolve to a positive integer scalar\n"
                unless defined($integer_value) && $integer_value > 0;
            return $integer_value;
        }

        confess "Transaction '$tn': $context references unknown package constant '$token'\n"
            if $suffix eq '' && !_actor_local_enum_member_exists($actor, $package_name, $constant_name);
    }

    my $transaction_param = _transaction_param_by_name($actor, $tn, $token);
    if ($transaction_param) {
        my $param_value = _non_negative_integer_from_literal(_param_resolved_value($transaction_param));
        confess "Transaction '$tn': $context transaction parameter '$token' must resolve to a positive integer\n"
            unless defined($param_value) && $param_value > 0;
        return $param_value;
    }

    my $constant = _actor_constant_by_name($actor, $token);
    if ($constant) {
        my $constant_value = _non_negative_integer_from_literal(_constant_resolved_value($constant));
        confess "Transaction '$tn': $context constant '$token' must resolve to a positive integer\n"
            unless defined($constant_value) && $constant_value > 0;
        return $constant_value;
    }

    my $param = _actor_param_by_name($actor, $token);
    if ($param) {
        my $param_value = _non_negative_integer_from_literal(_param_resolved_value($param));
        confess "Transaction '$tn': $context parameter '$token' must resolve to a positive integer\n"
            unless defined($param_value) && $param_value > 0;
        return $param_value;
    }

    confess "Transaction '$tn': $context token '$token' is a runtime interface signal; data-operation width evidence accepts $accepted_sources only\n"
        if _actor_interface_signal_by_name($actor, $token);

    confess "Transaction '$tn': $context token '$token' is not a same-transaction scalar parameter, declared actor constant, actor scalar parameter, or imported package scalar constant\n";
}

sub _register_counter_width {
    my ($counters, $name, $width) = @_;
    $width = 8 unless defined($width) && $width > 0;
    $counters->{$name} = $width
        if !defined($counters->{$name}) || $counters->{$name} < $width;
}

sub _register_repeat_counters {
    my ($counters, $storage_roles, $repeat_counter, $repeat_width, $dynamic_wait_counters) = @_;
    if (defined($repeat_counter) && length($repeat_counter)) {
        _register_counter_width($counters, $repeat_counter, $repeat_width)
            if $counters;
        $storage_roles->{$repeat_counter} = 'repeat_counter'
            if ref($storage_roles) eq 'HASH';
    }

    for my $entry (@{$dynamic_wait_counters || []}) {
        next unless ref($entry) eq 'HASH';
        _register_counter_width($counters, $entry->{name}, $entry->{width})
            if $counters;
        $storage_roles->{$entry->{name}} = 'dynamic_wait_counter'
            if ref($storage_roles) eq 'HASH';
    }
}

sub _repeat_count_width {
    my ($count, $widths, $actor, $tn) = @_;
    return 8 if ref($count);
    my $transaction_param_value = _transaction_param_repeat_count_value($count, $actor, $tn);
    return _repeat_count_width_for_integer($transaction_param_value)
        if defined $transaction_param_value;
    return $widths->{$count}
        if defined($count) && exists($widths->{$count}) && $widths->{$count} > 0;
    my $constant_value = _actor_constant_repeat_count_value($count, $actor);
    return _repeat_count_width_for_integer($constant_value)
        if defined $constant_value;
    my $param_value = _actor_param_repeat_count_value($count, $actor);
    return _repeat_count_width_for_integer($param_value)
        if defined $param_value;
    my $package_constant_value = _package_constant_repeat_count_value($count, $actor);
    return _repeat_count_width_for_integer($package_constant_value)
        if defined $package_constant_value;
    if (defined($count)) {
        my $literal_width = _literal_repeat_count_width($count);
        return $literal_width if defined $literal_width;
    }
    return 8;
}

sub _static_repeat_count_value {
    my ($count, $actor, $tn) = @_;
    return undef unless defined($count) && !ref($count);

    my $transaction_param_value = _transaction_param_repeat_count_value($count, $actor, $tn);
    return $transaction_param_value if defined $transaction_param_value;

    my $literal_value = _non_negative_integer_from_literal($count);
    return $literal_value if defined $literal_value;

    my $constant_value = _actor_constant_repeat_count_value($count, $actor);
    return $constant_value if defined $constant_value;

    my $param_value = _actor_param_repeat_count_value($count, $actor);
    return $param_value if defined $param_value;

    return _package_constant_repeat_count_value($count, $actor);
}

sub _actor_constant_repeat_count_value {
    my ($count, $actor) = @_;
    return undef unless defined($count) && !ref($count);

    if (_is_hdl_identifier($count)) {
        my $constant = _actor_constant_by_name($actor, $count);
        if ($constant) {
            my $constant_value = _non_negative_integer_from_literal(_constant_resolved_value($constant));
            return $constant_value if defined $constant_value;
        }
    }

    return undef;
}

sub _actor_param_repeat_count_value {
    my ($count, $actor) = @_;
    return undef unless defined($count) && !ref($count);

    if (_is_hdl_identifier($count)) {
        my $param = _actor_param_by_name($actor, $count);
        if ($param) {
            my $param_value = _non_negative_integer_from_literal(_param_resolved_value($param));
            return $param_value if defined $param_value;
        }
    }

    return undef;
}

sub _package_constant_repeat_count_value {
    my ($count, $actor) = @_;
    return undef unless defined($count) && !ref($count);

    my $package_constant = _actor_package_constant_reference($actor, $count);
    return undef unless $package_constant;
    my ($package_name, $constant_name, $suffix) = @$package_constant;
    return undef unless $suffix eq '';

    my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
    return undef unless defined $constant_payload;
    my $constant_value = _package_constant_scalar_value($constant_payload);
    return defined($constant_value) && !ref($constant_value)
        ? _non_negative_integer_from_literal($constant_value)
        : undef;
}

sub _transaction_param_repeat_count_value {
    my ($count, $actor, $tn) = @_;
    return undef unless defined($tn) && defined($count) && !ref($count) && _is_hdl_identifier($count);

    my $param = _transaction_param_by_name($actor, $tn, $count);
    return undef unless $param;

    my $param_value = exists($param->{resolved_value})
        ? $param->{resolved_value}
        : $param->{value};
    return _non_negative_integer_from_literal($param_value)
        if defined($param_value) && !ref($param_value);

    return undef;
}

sub _transaction_param_wait_count_value {
    my ($count, $actor, $tn) = @_;
    return undef unless defined($tn) && defined($count) && !ref($count) && _is_hdl_identifier($count);

    my $param = _transaction_param_by_name($actor, $tn, $count);
    return undef unless $param;

    my $param_value = exists($param->{resolved_value})
        ? $param->{resolved_value}
        : $param->{value};
    return _non_negative_integer_from_literal($param_value)
        if defined($param_value) && !ref($param_value);

    return undef;
}

sub _repeat_count_load_value {
    my ($count, $actor, $tn) = @_;

    # ISF-COUNTED-REPEAT-TERMINATION (check-first): load the counter with the count value
    # AS-IS (a literal/constant copy, or a runtime signal copy) — never an expression. The
    # repeat_check (reached first, before the body) performs the count==0 -> exit test and
    # the per-iteration decrement, so loading the raw count yields exactly `count`
    # iterations. Keeping the load a copy (not a `(- count 1)` expression) is essential:
    # the decrement is the counter's only expression-assignment, so the generated one-hot
    # write-enable selector stays disjoint (two expression-assignments would alias to one
    # `<counter>_expr_en` wire and trip the multi-driver assertion).
    my $transaction_param_value = _transaction_param_repeat_count_value($count, $actor, $tn);
    return $transaction_param_value if defined $transaction_param_value;

    return $count;
}

sub _is_static_zero_repeat_count {
    my ($count, $actor, $tn) = @_;
    my $static_value = _static_repeat_count_value($count, $actor, $tn);

    return defined($static_value) && $static_value == 0 ? 1 : 0;
}

sub _validate_repeat_count_source {
    my ($count, $widths, $actor, $tn) = @_;

    if (defined($count) && !ref($count) && _is_hdl_identifier($count)
        && _transaction_param_by_name($actor, $tn, $count)) {
        my $param_value = _transaction_param_repeat_count_value($count, $actor, $tn);
        return 1 if defined($param_value);

        confess "Transaction '$tn': repeat count transaction parameter '$count' must resolve to a non-negative integer literal\n";
    }

    if (my $package_constant = _actor_package_constant_reference($actor, $count)) {
        my ($package_name, $constant_name, $suffix) = @$package_constant;
        my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
        if (defined $constant_payload) {
            confess "Transaction '$tn': repeat count token '$count' is ambiguous: it matches local enum member '$count' and imported package constant '$count'\n"
                if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
            confess "Transaction '$tn': repeat count package constant '$package_name.$constant_name' aggregate/member path '$count' remains deferred; repeat counts accept only qualified package scalar constants in this slice\n"
                if $suffix ne '';
            my $constant_value = _package_constant_scalar_value($constant_payload);
            my $integer_value = defined($constant_value) && !ref($constant_value)
                ? _non_negative_integer_from_literal($constant_value)
                : undef;
            confess "Transaction '$tn': repeat count package constant '$package_name.$constant_name' must resolve to a non-negative integer scalar\n"
                unless defined($integer_value);
            return 1;
        }

        confess "Transaction '$tn': repeat count references unknown package constant '$count'\n"
            if $suffix eq '' && !_actor_local_enum_member_exists($actor, $package_name, $constant_name);
    }

    my $static_value = _static_repeat_count_value($count, $actor, $tn);
    return 1 if defined($static_value);

    if (defined($count) && !ref($count) && _is_hdl_identifier($count)) {
        if (_actor_constant_by_name($actor, $count)) {
            confess "Transaction '$tn': repeat count actor constant '$count' must resolve to a non-negative integer literal\n";
        }
        if (_actor_param_by_name($actor, $count)) {
            confess "Transaction '$tn': repeat count actor parameter '$count' must resolve to a non-negative integer literal\n";
        }
        return 1 if defined _runtime_repeat_count_source($count, $widths, $actor, $tn);

        confess "Transaction '$tn': repeat count '$count' is neither a declared non-negative actor constant, actor scalar parameter, qualified package scalar constant, nor a known-width runtime scalar\n";
    }

    confess "Transaction '$tn': repeat count '$count' must be a non-negative decimal literal, declared non-negative actor constant, actor scalar parameter, qualified package scalar constant, or known-width runtime scalar name\n";
}

sub _runtime_repeat_count_source {
    my ($count, $widths, $actor, $tn) = @_;
    return undef unless defined($count) && !ref($count) && _is_hdl_identifier($count);
    return undef if defined _static_repeat_count_value($count, $actor, $tn);
    return undef if _actor_param_by_name($actor, $count);
    return undef unless ref($widths) eq 'HASH'
        && exists($widths->{$count})
        && defined($widths->{$count})
        && $widths->{$count} > 0;

    return $count;
}

sub _transaction_param_by_name {
    my ($actor, $tx_name, $name) = @_;
    return undef unless defined($name) && !ref($name) && _is_hdl_identifier($name);

    my ($tx) = grep {
        ref($_) eq 'HASH'
            && defined($_->{name})
            && !ref($_->{name})
            && $_->{name} eq $tx_name
    } @{$actor->{transactions} || []};
    return undef unless $tx;

    for my $param (@{_transaction_param_declarations($tx, $actor)}) {
        return $param if ($param->{name} // '') eq $name;
    }

    return undef;
}

sub _actor_transaction_param_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $tx (@{$actor->{transactions} || []}) {
        next unless ref($tx) eq 'HASH';
        my $tx_name = $tx->{name};
        next unless defined($tx_name) && !ref($tx_name);
        return $tx if _transaction_param_by_name($actor, $tx_name, $name);
    }

    return undef;
}

sub _literal_repeat_count_width {
    my ($count) = @_;
    return undef unless defined($count) && !ref($count) && $count =~ /\A(?:\+)?([0-9]+)\z/;

    return _repeat_count_width_for_integer(0 + $1);
}

sub _repeat_count_width_for_integer {
    my ($limit) = @_;
    return undef unless defined($limit) && !ref($limit) && $limit =~ /\A[0-9]+\z/;

    my $width = 1;
    my $max_value = 1;
    while ($max_value < $limit) {
        ++$width;
        $max_value = (2 ** $width) - 1;
    }
    return $width;
}

# --- Transaction → IR states ---
sub _build_transaction($self, $tx, $actor, $txi, $generated_children = undef, $point_bindings = undef, $preallocation = undef) {
    my $tn  = $tx->{name};
    my $wd  = _watchdog_limit_cycles($actor->{watchdog}, $actor, $tn, 'actor watchdog');
    my $drives = $actor->{drives} || {};
    $generated_children ||= {};
    # ISF-TRIGGER-ANCHOR.5: module-wide name -> state map for (point NAME) / (on … as NAME),
    # consumed by (at NAME) resolution after all transactions lower. Local fallback for callers
    # that do not thread one (no (at …) resolution needed there).
    $point_bindings = {} unless ref($point_bindings) eq 'HASH';
    my $constant_values = _actor_constant_value_map($actor);
    _validate_supported_transaction_clauses($tx->{clauses}, $tn, 'transaction', undef, $generated_children, $actor);
    my $widths = _build_signal_width_map($actor, $tx);
    my $record_samples = FSM::Scheduler::ISF::RecordSamples->transaction_plan($actor, $tx);
    my @st;
    my %ct;
    my %reset_values;   # ISF-REGISTER-RESET-VALUES: signal -> hardware reset value (opt-in)
    my @dt;
    my @ps;
    my @doc;
    my @spc;
    my @dps;
    my @contracts;
    my @asserts;
    my %check_ordinal;
    my @bank_accesses;
    my %storage_roles;
    my $si  = 0; my $ha = 0; my $wdc; my $lat;
    my $do_ordinal = 0;
    my $repeat_do_ordinal = 0;

    my %transaction_ports = _transaction_port_map($tx);
    for my $port (values %transaction_ports) {
        $ct{$port->{name}} = $port->{width} // 1;
        $storage_roles{$port->{name}} = 'transaction_port';
    }

    for my $cl (@{$tx->{clauses}}) {
        next unless ref($cl) eq 'ARRAY';
        my $k = $cl->[0];
        if    ($k eq 'on')       { push @st, _ir_on($cl, $tn, $si++, $point_bindings); }
        elsif ($k eq 'drive')    {
            push @st, _ir_transaction_drive_clause($cl, $tn, $si++, $drives, [splice @ps]);
        }
        elsif ($k eq 'await')    {
            $ha=1; $wdc="${tn}_wd";
            my $wd_limit = _await_watchdog_limit($cl, $actor, $tn, $wd);
            push @st, _ir_await($cl, $tn, $si++, $wd_limit, [splice @ps]);
        }
        elsif ($k eq 'atl_trigger') { push @st, _ir_atl_trigger($cl, $tn, $si++, [splice @ps]); }
        elsif ($k eq 'atl_trigger_batch') { push @st, _ir_atl_trigger_batch($cl, $tn, $si++, [splice @ps]); }
        elsif ($k eq 'sample')   { push @ps, $cl; }
        elsif ($k eq 'wait') {
            my $wait = _wait_count_spec($cl, $tn, 'transaction body', $actor, $widths, 1);
            if ($wait->{kind} eq 'static') {
                if ($wait->{cycles} > 0) {
                    push @st, @{_ir_wait($cl, $tn, \$si, [splice @ps], $actor, 'transaction body', $wait)};
                }
            } else {
                my ($states, $counter, $width) = _ir_dynamic_wait($cl, $tn, \$si, $wait, [splice @ps]);
                push @st, @$states;
                _register_counter_width(\%ct, $counter, $width);
                $storage_roles{$counter} = 'dynamic_wait_counter';
            }
        }
        elsif ($k eq 'while') {
            push @st, @{
                _ir_while(
                    $cl, $tn, \$si, [splice @ps], $wd, $drives, $widths,
                    \%ct, \%storage_roles, $actor, \@bank_accesses,
                    \@spc, $constant_values, $generated_children, \$repeat_do_ordinal,
                )
            };
        }
        elsif ($k eq 'until') {
            push @st, @{
                _ir_until(
                    $cl, $tn, \$si, [splice @ps], $wd, $drives, $widths,
                    \%ct, \%storage_roles, $actor, \@bank_accesses,
                    \@spc, $constant_values, $generated_children, \$repeat_do_ordinal,
                )
            };
        }
        elsif ($k eq 'update' || $k eq 'set') { _push_sample_state(\@st,$tn,\@ps,\$si); push @st, _ir_update($cl,$tn,$si++,$k); }
        elsif ($k eq 'phase')       { push @st, _ir_phase($cl,$tn,$si++); }
        elsif ($k eq 'point')       { push @st, _ir_point($cl,$tn,$si++,$point_bindings); }
        elsif ($k eq 'stage')       { _push_sample_state(\@st,$tn,\@ps,\$si); push @st, _ir_stage($cl,$tn,$si++,$actor); }
        elsif ($k eq 'assert' || $k eq 'cover' || $k eq 'assume') {
            if (_is_monitor_check($cl)) {
                # (assert (monitor (within S N))) — synthesizable-monitor output-mode: an arm state
                # at this position + a monitor DT, asserting the monitor never fails (ISF-TRIGGER-ANCHOR).
                _push_sample_state(\@st, $tn, \@ps, \$si);
                my ($ms, $mdt, $massert) =
                    _ir_monitor_check($cl, $tn, $si++, $actor, $widths, \%ct, \%storage_roles, $preallocation);
                push @st, $ms;
                push @dt, $mdt;
                push @asserts, $massert;
            }
            else {
                push @asserts, _ir_check($cl, $tn, $check_ordinal{$k}++);
            }
        }
        elsif ($k eq 'shift_left')  { _push_sample_state(\@st,$tn,\@ps,\$si); push @st, _ir_shift_left($cl,$tn,$si++,$widths,$actor); }
        elsif ($k eq 'shift_right') { _push_sample_state(\@st,$tn,\@ps,\$si); push @st, _ir_shift_right($cl,$tn,$si++,$widths,$actor); }
        elsif ($k eq 'assemble')    { _push_sample_state(\@st,$tn,\@ps,\$si); push @st, _ir_assemble($cl,$tn,$si++,$actor); }
        elsif ($k eq 'extract')     { _push_sample_state(\@st,$tn,\@ps,\$si); push @st, _ir_extract($cl,$tn,$si++,$widths,$actor); }
        elsif ($k eq 'store' || $k eq 'load') {
            _push_sample_state(\@st, $tn, \@ps, \$si);
            my ($state, $accesses) = _ir_bank_access($cl, $tn, $si++, $actor, $widths, 'transaction');
            push @st, $state;
            push @bank_accesses, @$accesses;
        }
        elsif ($k eq 'complete') { push @st, _ir_complete($cl, $tn, $si++); }
        elsif ($k eq 'when' && !@st) { push @st, _ir_when_activation($cl,$tn,$si++); }
        elsif ($k eq 'when')     {
            my ($ws) = _expand_when($cl,$tn,\$si,\@ps,$drives,$wd,$widths,\%ct,\%storage_roles,$actor,\@bank_accesses,\@spc,$constant_values,$generated_children,\$repeat_do_ordinal);
            push @st, @$ws;
        }
        elsif ($k eq 'switch')   {
            my ($ss) = _expand_switch($cl,$tn,\$si,\@ps,$drives,$wd,$widths,\%ct,\%storage_roles,$actor,\@bank_accesses,\@spc,$constant_values,$generated_children,\$repeat_do_ordinal);
            push @st, @$ss;
        }
        elsif ($k eq 'repeat')   { my ($rs,$rc,$rw,$rdw) = _ir_repeat($cl,$tn,\$si,\@ps,$wd,$drives,$widths,$actor,\@bank_accesses,\@spc,$constant_values,$generated_children,\$repeat_do_ordinal); push @st,@$rs; _register_repeat_counters(\%ct,\%storage_roles,$rc,$rw,$rdw); }
        elsif ($k eq 'latency')  { $lat = _parse_latency($cl, $tn, $actor); }
        elsif ($k eq 'params')   { next; }
        elsif ($k eq 'local')    {
            my ($ln, $lw, $linit, $lreset) = _parse_local_decl($cl, $tn, $actor, \%ct);
            $ct{$ln} = $lw;
            $reset_values{$ln} = $lreset if defined $lreset;
            if (defined $linit) {
                _push_sample_state(\@st, $tn, \@ps, \$si);
                push @st, _ir_update([ 'set', $ln, $linit ], $tn, $si++, 'set');
            }
        }
        elsif ($k eq 'do')       {
            my $do_ref = _do_ref_from_clause($cl, $tn, $do_ordinal++, $generated_children, $constant_values, $actor);
            push @doc, $do_ref;
            push @spc, _clone_isf_value($do_ref) if $do_ref->{generated_child};
            push @st, _ir_do($cl, $tn, $si++, $do_ref);
        }
        elsif ($k eq 'spawn')    { push @spc, _spawn_ref_from_clause($cl,$tn,$constant_values,$actor); push @dps, "$spc[-1]{instance}_done"; push @st, _ir_spawn($cl,$tn,$si++); }
        elsif ($k eq 'await_all') { push @st, _ir_sync_all($tn,$si++,\@dps); @dps = (); }
        elsif ($k eq 'await_any') { push @st, _ir_sync_any($tn,$si++,\@dps); @dps = () if @dps <= 1; }
    }

    if (@ps) { push @st, _ir_sample_state($tn, \@ps, $si++); }

    # Watchdog
    if ($ha && $wdc) {
        my $lim = _transaction_watchdog_limit(\@st, $wd, $tn);
        $ct{$wdc} = int(log($lim)/log(2)) + 1;
        $storage_roles{$wdc} = 'watchdog_counter';
        _inj_watchdog(\@st, $tn, $wdc, $lim, \%ct);
    }

    # Latency
    if ($lat) {
        my ($cc,$inc,$err,$cdt) = _inj_latency(\@st, $tn, $lat, $ha, \%ct);
        $ct{$cc} = int(log($lat->{max}//256)/log(2)) + 1;
        $storage_roles{$cc} = 'latency_counter';
        $ct{$inc} = 1; $ct{$err} = 1;
        push @dt, $cdt;
    }

    _merge_sequential(\@st) if 0;  # disabled — needs more work
    _link_states(\@st, $tn);
    $ct{can_accept} = 1;
    FSM::Scheduler::ISF::RecordSamples->declare_transaction_aliases(
        $record_samples, \%ct, \%storage_roles, $widths, $tn);
    for my $s (@st) { next unless $s->{kind} eq 'entry'; unshift @{$s->{assignments}}, { lhs => 'can_accept', rhs => 1, op => '=' }; }
    $_->{transaction} = $tn for @st;
    $_->{source_owner} = {kind => 'transaction', name => $tn} for @dt;
    return (\@st, \%ct, \@dt, \@doc, \@spc, \@contracts, { %{$widths || {}} }, \%storage_roles, \@bank_accesses, \%reset_values, \@asserts);
}

sub _merge_signal_widths {
    my ($merged, $widths, $transaction) = @_;
    return unless ref($widths) eq 'HASH';

    for my $name (sort keys %$widths) {
        my $width = $widths->{$name};
        next unless defined($width) && $width > 0;
        confess "signal width for '$name' conflicts across transactions while merging '$transaction'\n"
            if defined($merged->{$name}) && $merged->{$name} > 0 && $merged->{$name} != $width;
        $merged->{$name} = $width;
    }
}

sub _merge_signal_type_refs {
    my ($merged, $types) = @_;
    return unless ref($types) eq 'HASH';

    for my $name (sort keys %$types) {
        my $type = $types->{$name};
        next unless defined($type) && !ref($type) && length($type);
        $merged->{$name} = $type;
    }
}

sub _merge_storage_roles {
    my ($merged, $roles, $transaction) = @_;
    return unless ref($roles) eq 'HASH';

    for my $name (sort keys %$roles) {
        my $role = $roles->{$name};
        next unless defined($role) && length($role);
        confess "storage role for '$name' conflicts across transactions while merging '$transaction'\n"
            if defined($merged->{$name}) && $merged->{$name} ne $role;
        $merged->{$name} = $role;
    }
}

sub _validate_supported_transaction_clauses {
    my ($clauses, $tn, $context, $context_depths, $generated_children, $actor) = @_;
    return unless ref($clauses) eq 'ARRAY';
    $context_depths ||= {};
    $generated_children ||= {};

    my $allowed = $SUPPORTED_TRANSACTION_CLAUSES{$context} || {};
    my $label = $TRANSACTION_CONTEXT_LABEL{$context} || $context;

    for (my $clause_index = 0; $clause_index < @$clauses; $clause_index++) {
        my $clause = $clauses->[$clause_index];
        confess "Transaction '$tn': transaction clauses must be list forms in $label\n"
            unless ref($clause) eq 'ARRAY';
        next unless @$clause;

        my $keyword = $clause->[0];
        confess "Transaction '$tn': transaction clause heads must be scalar in $label\n"
            unless defined($keyword) && !ref($keyword) && length($keyword);

        if (defined($keyword) && !ref($keyword) && $keyword eq 'stage' && $context ne 'transaction') {
            confess "Transaction '$tn': pipeline '(stage ...)' clauses are supported only as top-level transaction clauses\n";
        }
        if (defined($keyword) && !ref($keyword) && $keyword eq 'assign') {
            confess _removed_assign_clause_diagnostic($tn, $label);
        }
        confess "Transaction '$tn': unsupported '($keyword ...)' clause in $label\n"
            unless $allowed->{$keyword};

        if ($keyword eq 'on') {
            _validate_on_clause($clause, $tn, $label);
        } elsif ($keyword eq 'complete') {
            _validate_complete_clause($clause, $tn, $label);
        } elsif ($keyword eq 'sample') {
            _validate_sample_clause($clause, $tn, $label);
        } elsif ($keyword eq 'wait') {
            _validate_wait_clause($clause, $tn, $label);
        } elsif ($keyword eq 'update' || $keyword eq 'set') {
            _validate_update_clause($clause, $tn, $label, $keyword);
        } elsif ($keyword eq 'store' || $keyword eq 'load') {
            _validate_bank_access_clause($clause, $tn, $label);
        } elsif ($keyword eq 'shift_left' || $keyword eq 'shift_right') {
            _validate_shift_clause($clause, $tn, $label);
        } elsif ($keyword eq 'when') {
            _validate_when_clause($clause, $tn, $label);
            my %next_depths = (%$context_depths, when => (($context_depths->{when} // 0) + 1));
            _validate_supported_transaction_clauses([@{$clause}[2 .. $#$clause]], $tn, 'when', \%next_depths, $generated_children, $actor);
        } elsif ($keyword eq 'repeat') {
            _validate_repeat_clause($clause, $tn, $label);
            my $parent_exit_sync_after_repeat = $context eq 'transaction'
                ? _next_transaction_body_sync_after($clauses, $clause_index)
                : undef;
            _validate_repeat_body_spawn_subset(
                $clause,
                $tn,
                $label,
                $context_depths,
                $generated_children,
                $actor,
                {
                    parent_exit_sync_after_repeat => $parent_exit_sync_after_repeat,
                },
            )
                unless ref($actor) eq 'HASH' && _is_static_zero_repeat_count($clause->[1], $actor, $tn);
            _validate_supported_transaction_clauses([@{$clause}[2 .. $#$clause]], $tn, 'repeat', $context_depths, $generated_children, $actor);
        } elsif ($keyword eq 'while' || $keyword eq 'until') {
            _validate_loop_clause($clause, $tn, $label, $keyword);
            my %next_depths = (%$context_depths, $keyword => (($context_depths->{$keyword} // 0) + 1));
            _validate_supported_transaction_clauses([@{$clause}[2 .. $#$clause]], $tn, $keyword, \%next_depths, $generated_children, $actor);
        } elsif ($keyword eq 'await_all' || $keyword eq 'await_any') {
            _validate_sync_clause($clause, $tn, $label);
        } elsif ($keyword eq 'do' || $keyword eq 'spawn') {
            _validate_child_action_clause($clause, $tn, $label);
        } elsif ($keyword eq 'stage') {
            _validate_stage_clause($clause, $tn, $label);
        } elsif ($keyword eq 'switch') {
            _validate_switch_clause($clause, $tn, $label);
            for my $branch (@{$clause}[2 .. $#$clause]) {
                next unless ref($branch) eq 'ARRAY';
                my %next_depths = (%$context_depths, switch => (($context_depths->{switch} // 0) + 1));
                _validate_supported_transaction_clauses([@{$branch}[1 .. $#$branch]], $tn, 'switch', \%next_depths, $generated_children, $actor);
            }
        }
    }
}

sub _next_transaction_body_sync_after {
    my ($clauses, $clause_index) = @_;
    return undef unless ref($clauses) eq 'ARRAY';

    for my $later (@{$clauses}[$clause_index + 1 .. $#$clauses]) {
        next unless ref($later) eq 'ARRAY' && @$later;
        my $keyword = $later->[0];
        next unless defined($keyword) && !ref($keyword);
        next unless $keyword eq 'await_all' || $keyword eq 'await_any';
        my $signal = defined($later->[1]) && !ref($later->[1]) && length($later->[1])
            ? $later->[1]
            : 'done';
        return {
            keyword => $keyword,
            signal  => $signal,
            form    => "($keyword $signal)",
        };
    }

    return undef;
}

sub _validate_on_clause {
    my ($clause, $tn, $label) = @_;

    confess "Transaction '$tn': on requires '(on port [sample...])' in $label\n"
        unless @$clause >= 2
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1]);

    # ISF-TRIGGER-ANCHOR.5b: an optional bare `as NAME` activation label (like (sample … as …) /
    # (spawn … as …)) names the entry/accept state for `(at NAME)`. It is a scalar `as` followed by
    # a scalar identifier at the top level of `(on …)` (sample sub-clauses are arrays).
    my $saw_as_label = 0;
    my $i = 2;
    while ($i <= $#$clause) {
        my $body_clause = $clause->[$i];
        if (defined($body_clause) && !ref($body_clause) && $body_clause eq 'as') {
            my $name = $clause->[$i + 1];
            confess "Transaction '$tn': '(on SIGNAL as NAME)' activation label requires a scalar name in $label\n"
                unless defined($name) && !ref($name) && length($name);
            confess "Transaction '$tn': '(on …)' activation label name '$name' must be an HDL identifier in $label\n"
                unless $name =~ /\A[A-Za-z_]\w*\z/;
            confess "Transaction '$tn': '(on …)' accepts a single 'as NAME' activation label in $label\n"
                if $saw_as_label++;
            $i += 2;
            next;
        }
        if (ref($body_clause) eq 'ARRAY'
            && @$body_clause
            && defined($body_clause->[0])
            && !ref($body_clause->[0])
            && $body_clause->[0] eq 'params') {
            confess "Transaction '$tn': on body does not accept '(params ...)'; "
                . "direct '(on ...)' activation is an entry guard, not a generated activation-site parameter override\n";
        }
        confess "Transaction '$tn': on body supports only '(sample port as name)' clauses or a single 'as NAME' activation label\n"
            unless ref($body_clause) eq 'ARRAY'
                && @$body_clause
                && defined($body_clause->[0])
                && !ref($body_clause->[0])
                && $body_clause->[0] eq 'sample';
        _validate_sample_clause($body_clause, $tn, 'on body');
        $i++;
    }

    return 1;
}

sub _validate_shift_clause {
    my ($clause, $tn, $label) = @_;
    my $keyword = $clause->[0];
    my $shape = $keyword eq 'shift_left'
        ? '(shift_left reg bit [(width N|TX_PARAM|PARAM|CONST|PACKAGE.CONSTANT)])'
        : '(shift_right reg bit [(width N|TX_PARAM|PARAM|CONST|PACKAGE.CONSTANT)])';

    confess "Transaction '$tn': $keyword requires '$shape' in $label\n"
        unless @$clause >= 3
            && @$clause <= 4
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1])
            && defined($clause->[2])
            && !ref($clause->[2])
            && length($clause->[2]);

    return 1;
}

sub _validate_when_clause {
    my ($clause, $tn, $label) = @_;

    confess "Transaction '$tn': when requires '(when condition body...)' in $label\n"
        unless @$clause >= 3
            && defined($clause->[1])
            && (
                (ref($clause->[1]) eq 'ARRAY' && @{$clause->[1]})
                || (!ref($clause->[1]) && length($clause->[1]))
            );

    for my $body_clause (@{$clause}[2 .. $#$clause]) {
        confess "Transaction '$tn': when body clauses must be list forms in $label\n"
            unless ref($body_clause) eq 'ARRAY';
    }

    return 1;
}

sub _validate_switch_clause {
    my ($clause, $tn, $label) = @_;

    confess "Transaction '$tn': switch requires '(switch signal (value body...)...)' in $label\n"
        unless @$clause >= 3
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1]);

    for my $branch (@{$clause}[2 .. $#$clause]) {
        confess "Transaction '$tn': switch branches require '(value body...)' in $label\n"
            unless ref($branch) eq 'ARRAY'
                && @$branch >= 2
                && defined($branch->[0])
                && !ref($branch->[0])
                && length($branch->[0]);

        for my $body_clause (@{$branch}[1 .. $#$branch]) {
            confess "Transaction '$tn': switch branches require '(value body...)' in $label\n"
                unless ref($body_clause) eq 'ARRAY';
        }
    }

    return 1;
}

sub _removed_assign_clause_diagnostic {
    my ($tn, $label) = @_;
    return "Transaction '$tn': removed '(assign ...)' clause is unsupported in $label; "
        . "use '(set var expr)' for explicit scalar flopped updates, "
        . "'(update var expr)' for the older transaction-local spelling, "
        . "'(drive ...)' for protocol/output drives, rule '(set port expr)' or '(port expr)' actions "
        . "for rule-driven assignments, or '(complete port)' for completion pulses\n";
}

sub _validate_stage_clause {
    my ($clause, $tn, $label) = @_;

    _parse_stage_handshake_clause($clause, $tn, $label);
    return 1;
}

sub _parse_stage_handshake_clause {
    my ($clause, $tn, $label) = @_;

    confess "Transaction '$tn': stage requires '(stage name (ready ready_signal) (valid valid_signal))' or '(stage name (input ready_signal) (output valid_signal))' in $label\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause >= 2
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1]);

    my %seen;
    my %role_for = (
        input  => 'ready',
        ready  => 'ready',
        output => 'valid',
        valid  => 'valid',
    );
    my %parsed = (name => $clause->[1]);

    for my $subclause (@{$clause}[2 .. $#$clause]) {
        confess "Transaction '$tn': stage '$parsed{name}' subclauses must be '(ready ready_signal)'/'(valid valid_signal)' or '(input ready_signal)'/'(output valid_signal)' in $label\n"
            unless ref($subclause) eq 'ARRAY'
                && @$subclause == 2
                && defined($subclause->[0])
                && !ref($subclause->[0])
                && length($subclause->[0]);

        my ($head, $signal) = @$subclause;
        confess "Transaction '$tn': stage '$parsed{name}' has unsupported subclause '$head'\n"
            unless exists $role_for{$head};
        my $role = $role_for{$head};
        confess "Transaction '$tn': duplicate stage '$parsed{name}' $role endpoint\n"
            if $seen{$role}++;
        confess "Transaction '$tn': stage '$parsed{name}' $head signal must be scalar\n"
            unless defined($signal) && !ref($signal) && length($signal);

        $parsed{$role} = $signal;
    }

    confess "Transaction '$tn': stage '$parsed{name}' requires '(ready ready_signal)' or '(input ready_signal)'\n"
        unless defined($parsed{ready});
    confess "Transaction '$tn': stage '$parsed{name}' requires '(valid valid_signal)' or '(output valid_signal)'\n"
        unless defined($parsed{valid});

    return \%parsed;
}

# Resolve a `(monitor (within S N))` window to a positive integer cycle count. `N` may be a positive
# literal, a same-transaction/actor scalar parameter, an actor constant, or a qualified package scalar
# constant (shared by the monitor output-mode; formerly the `(contract …)` within-cycles resolver).
sub _resolve_monitor_window_cycles {
    my ($token, $actor, $tn, $window_owner, $label) = @_;
    my $accepted_sources = 'positive integer literals, same-transaction scalar parameters, actor constants, actor scalar parameters, or qualified package scalar constants';

    return 0 + $token
        if defined($token) && !ref($token) && $token =~ /\A[1-9][0-9]*\z/;

    confess "Transaction '$tn': monitor window '$window_owner' must be a positive cycle count in $label\n"
        if defined($token) && !ref($token) && $token =~ /\A0+\z/;

    my $package_window = _resolve_monitor_window_package_constant($token, $actor, $tn, $window_owner, $label);
    return $package_window if defined $package_window;

    if (defined($token) && !ref($token) && _is_hdl_identifier($token)) {
        return $token unless ref($actor) eq 'HASH';

        my $transaction_param = _transaction_param_by_name($actor, $tn, $token);
        if ($transaction_param) {
            my $param_value = _non_negative_integer_from_literal(_param_resolved_value($transaction_param));
            confess "Transaction '$tn': monitor window '$window_owner' transaction parameter '$token' must resolve to a positive cycle count in $label\n"
                unless defined($param_value) && $param_value > 0;
            return $param_value;
        }

        my $constant = _actor_constant_by_name($actor, $token);
        if ($constant) {
            my $constant_value = _non_negative_integer_from_literal(_constant_resolved_value($constant));
            confess "Transaction '$tn': monitor window '$window_owner' constant '$token' must resolve to a positive cycle count in $label\n"
                unless defined($constant_value) && $constant_value > 0;
            return $constant_value;
        }

        my $param = _actor_param_by_name($actor, $token);
        if ($param) {
            my $param_value = _non_negative_integer_from_literal(_param_resolved_value($param));
            confess "Transaction '$tn': monitor window '$window_owner' parameter '$token' must resolve to a positive cycle count in $label\n"
                unless defined($param_value) && $param_value > 0;
            return $param_value;
        }

        confess "Transaction '$tn': monitor window '$window_owner' token '$token' is a runtime interface signal; monitor windows accept $accepted_sources only in $label\n"
            if _actor_interface_signal_by_name($actor, $token);

        confess "Transaction '$tn': monitor window '$window_owner' token '$token' is not a same-transaction scalar parameter, declared actor constant, actor scalar parameter, or qualified package scalar constant in $label\n";
    }

    confess "Transaction '$tn': monitor window '$window_owner' must be a positive cycle count or a parameter/constant that resolves to one in $label\n";
}

sub _resolve_monitor_window_package_constant {
    my ($token, $actor, $tn, $window_owner, $label) = @_;
    return undef unless defined($token) && !ref($token);

    my $package_constant = _actor_package_constant_reference($actor, $token);
    if (!$package_constant) {
        confess "Transaction '$tn': monitor window '$window_owner' references unknown package constant '$token' in $label\n"
            if _is_package_constant_reference_shape($token);
        return undef;
    }

    my ($package_name, $constant_name, $suffix) = @$package_constant;
    my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
    if (defined $constant_payload) {
        confess "Transaction '$tn': monitor window '$window_owner' token '$token' is ambiguous: it matches local enum member '$token' and imported package constant '$token' in $label\n"
            if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
        confess "Transaction '$tn': monitor window '$window_owner' package constant '$package_name.$constant_name' aggregate/member path '$token' remains deferred; monitor windows accept only qualified package scalar constants in this slice\n"
            if $suffix ne '';
        my $constant_value = _package_constant_scalar_value($constant_payload);
        my $integer_value = defined($constant_value) && !ref($constant_value)
            ? _non_negative_integer_from_literal($constant_value)
            : undef;
        confess "Transaction '$tn': monitor window '$window_owner' package constant '$package_name.$constant_name' must resolve to a positive integer scalar cycle count in $label\n"
            unless defined($integer_value) && $integer_value > 0;
        return $integer_value;
    }

    confess "Transaction '$tn': monitor window '$window_owner' references unknown package constant '$token' in $label\n"
        if !_actor_local_enum_member_exists($actor, $package_name, $constant_name);

    return undef;
}

sub _validate_child_action_clause {
    my ($clause, $tn, $label) = @_;
    my $keyword = $clause->[0];

    if ($keyword eq 'do') {
        confess "Transaction '$tn': do requires '(do transaction [(domain name)] [(params (NAME value) ...)] [(bind ...)])' in $label\n"
            unless @$clause >= 2
                && defined($clause->[1])
                && !ref($clause->[1])
                && length($clause->[1]);

        my %seen_subclause;
        for my $subclause (@{$clause}[2 .. $#$clause]) {
            confess "Transaction '$tn': do subclauses must be '(domain ...)', '(params ...)', or '(bind ...)' in $label\n"
                unless ref($subclause) eq 'ARRAY'
                    && @$subclause
                    && defined($subclause->[0])
                    && !ref($subclause->[0])
                    && length($subclause->[0]);
            my $head = $subclause->[0];
            confess "Transaction '$tn': do has duplicate '$head' subclause in $label\n"
                if $seen_subclause{$head}++;
            if ($head eq 'params') {
                _validate_activation_params_clause_shape($subclause, $tn, 'do', $clause->[1], $label);
                next;
            }
            if ($head eq 'domain') {
                _activation_domain_from_clause(['do', $clause->[1], $subclause], $tn, $label);
                next;
            }
            if ($head eq 'bind') {
                _parse_activation_bind_clause($subclause, "Transaction '$tn': do target '$clause->[1]'");
                next;
            }
            confess "Transaction '$tn': do has unsupported '$head' subclause in $label\n";
        }
        _activation_bindings_from_clause($clause, $tn, $label);
        return 1;
    }

    confess "Transaction '$tn': spawn requires '(spawn transaction as instance [(domain name)] [(params (NAME value) ...)] [(bind ...)])' in $label\n"
        unless @$clause >= 4
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1])
            && defined($clause->[2])
            && !ref($clause->[2])
            && $clause->[2] eq 'as'
            && defined($clause->[3])
            && !ref($clause->[3])
            && length($clause->[3]);

    FSM::Support::HDLInstanceIdentifierPolicy->assert_authored_instance_identifier(
        $clause->[3],
        origin => "Transaction '$tn' spawn instance",
    );

    my %seen_subclause;
    for my $subclause (@{$clause}[4 .. $#$clause]) {
        confess "Transaction '$tn': spawn subclauses must be '(domain ...)', '(params ...)', or '(bind ...)' in $label\n"
            unless ref($subclause) eq 'ARRAY'
                && @$subclause
                && defined($subclause->[0])
                && !ref($subclause->[0])
                && length($subclause->[0]);
        my $head = $subclause->[0];
        confess "Transaction '$tn': spawn has duplicate '$head' subclause in $label\n"
            if $seen_subclause{$head}++;
        if ($head eq 'params') {
            _validate_activation_params_clause_shape($subclause, $tn, 'spawn', $clause->[3], $label);
            next;
        }
        if ($head eq 'domain') {
            _activation_domain_from_clause(['spawn', $clause->[1], 'as', $clause->[3], $subclause], $tn, $label);
            next;
        }
        if ($head eq 'bind') {
            _parse_activation_bind_clause($subclause, "Transaction '$tn': spawn instance '$clause->[3]'");
            next;
        }
        confess "Transaction '$tn': spawn has unsupported '$head' subclause in $label\n";
    }

    return 1;
}

sub _validate_rule_trigger_action_clause {
    my ($clause, $rule_name, $label) = @_;

    confess "Rule '$rule_name': trigger requires '(trigger transaction [(params (NAME value) ...)] [(bind ...)])' in $label\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause >= 2
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'trigger'
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1]);

    my $target = $clause->[1];
    my %seen_subclause;
    for my $subclause (@{$clause}[2 .. $#$clause]) {
        confess "Rule '$rule_name': trigger subclauses must be '(params ...)' or '(bind ...)' in $label\n"
            unless ref($subclause) eq 'ARRAY'
                && @$subclause
                && defined($subclause->[0])
                && !ref($subclause->[0])
                && length($subclause->[0]);
        my $head = $subclause->[0];
        confess "Rule '$rule_name': trigger has duplicate '$head' subclause in $label\n"
            if $seen_subclause{$head}++;
        if ($head eq 'params') {
            _validate_activation_params_clause_shape($subclause, $rule_name, 'trigger', $target, $label);
            next;
        }
        if ($head eq 'bind') {
            _parse_activation_bind_clause($subclause, "Rule '$rule_name': trigger target '$target'");
            next;
        }
        confess "Rule '$rule_name': trigger has unsupported '$head' subclause in $label\n";
    }

    return 1;
}

sub _validate_sync_clause {
    my ($clause, $tn, $label) = @_;
    my $keyword = $clause->[0];

    confess "Transaction '$tn': $keyword requires '($keyword done_port)' in $label\n"
        unless @$clause == 2
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1]);

    return 1;
}

sub _transaction_param_declarations {
    my ($tx, $actor) = @_;
    return [] unless ref($tx) eq 'HASH';

    my $tx_name = $tx->{name} // 'unknown';
    my @param_clauses = grep {
        ref($_) eq 'ARRAY' && @$_ && defined($_->[0]) && !ref($_->[0]) && $_->[0] eq 'params'
    } @{$tx->{clauses} || []};

    confess "Transaction '$tx_name': transaction parameters allow at most one '(params ...)' clause\n"
        if @param_clauses > 1;
    return [] unless @param_clauses;

    my $params_clause = $param_clauses[0];
    confess "Transaction '$tx_name': params require '(params (NAME value) ...)'\n"
        unless @$params_clause >= 2;

    my @params;
    my %seen;
    my %declared_transaction_params;
    my %earlier_scalar_transaction_param_values;
    for my $entry (@{$params_clause}[1 .. $#$params_clause]) {
        next unless ref($entry) eq 'ARRAY' && @$entry >= 1;
        my $declared_name = $entry->[0];
        next unless defined($declared_name) && !ref($declared_name);
        $declared_transaction_params{$declared_name}++;
    }

    for my $entry (@{$params_clause}[1 .. $#$params_clause]) {
        confess "Transaction '$tx_name': params entries require '(NAME value)'\n"
            unless ref($entry) eq 'ARRAY' && @$entry == 2;
        my ($name, $value) = @$entry;
        confess "Transaction '$tx_name': parameter names must be scalar HDL identifiers\n"
            unless _is_hdl_identifier($name);
        confess "Transaction '$tx_name': duplicate parameter '$name'\n"
            if $seen{$name}++;
        my ($published_value, $resolved_value, $has_resolved_value) = _resolve_transaction_param_default_value(
            $value,
            "Transaction '$tx_name': parameter '$name'",
            $actor,
            \%declared_transaction_params,
            \%earlier_scalar_transaction_param_values,
        );
        my %param = (
            name  => $name,
            value => _clone_isf_value($published_value),
        );
        $param{resolved_value} = _clone_isf_value($resolved_value)
            if $has_resolved_value;
        push @params, \%param;
        _record_earlier_scalar_transaction_param_value(\%earlier_scalar_transaction_param_values, \%param);
    }

    return \@params;
}

sub _spawn_ref_from_clause {
    my ($clause, $tn, $constant_values, $actor, $label) = @_;
    $label //= 'transaction body';
    my $instance = $clause->[3] // "${tn}_spawn";
    my $ref = {
        child => $clause->[1],
        instance => $instance,
        parameter_overrides => _spawn_parameter_overrides($clause, $tn, $label, $constant_values, $actor),
    };
    my $domain = _activation_domain_from_clause($clause, $tn, $label);
    $ref->{domain} = $domain if defined $domain;
    my $port_bindings = _activation_bindings_from_clause($clause, $tn, $label);
    $ref->{port_bindings} = $port_bindings if @$port_bindings;
    return $ref;
}

sub _do_ref_from_clause {
    my ($clause, $tn, $ordinal, $generated_children, $constant_values, $actor) = @_;
    my $child = $clause->[1];
    my $generated_child = $generated_children && $generated_children->{$child} ? 1 : 0;
    my $ref = {
        child           => $child,
        activation_kind => 'do',
        generated_child => $generated_child,
    };

    my $overrides = _do_parameter_overrides($clause, $tn, 'transaction body', $constant_values, $actor);
    if ($generated_child) {
        my $instance = _generated_do_instance_name($tn, $child, $ordinal);
        $ref->{instance} = $instance;
        $ref->{parameter_overrides} = $overrides;
        my $domain = _activation_domain_from_clause($clause, $tn, 'transaction body');
        $ref->{domain} = $domain if defined $domain;
        my $port_bindings = _activation_bindings_from_clause($clause, $tn, 'transaction body');
        $ref->{port_bindings} = $port_bindings if @$port_bindings;
    }

    return $ref;
}

sub _repeat_do_ref_from_clause {
    my ($clause, $tn, $ordinal, $constant_values, $actor, $generated_children) = @_;
    my $child = $clause->[1];
    my $overrides = _do_parameter_overrides($clause, $tn, 'repeat body', $constant_values, $actor);
    my $generated_child = (
        @$overrides
            || (ref($generated_children) eq 'HASH' && $generated_children->{$child})
    ) ? 1 : 0;
    my $ref = {
        child           => $child,
        activation_kind => 'do',
        generated_child => $generated_child,
    };

    if ($generated_child) {
        $ref->{instance} = _generated_repeat_do_instance_name($tn, $child, $ordinal);
        $ref->{parameter_overrides} = $overrides;
        my $domain = _activation_domain_from_clause($clause, $tn, 'repeat body');
        $ref->{domain} = $domain if defined $domain;
        my $port_bindings = _activation_bindings_from_clause($clause, $tn, 'repeat body');
        $ref->{port_bindings} = $port_bindings if @$port_bindings;
    }

    return $ref;
}

# ISF-CONDITIONAL-CHILD-ACTIVATION.5a: build the do-ref for a `(do child)` in a
# branch/loop body. For a generated child (a `(params ...)` override, or a target
# generated elsewhere) it carries a `cond_do` instance name + overrides/bindings,
# so the expander, `_register_generated_activation_instance`, and the top wiring
# all share one instance identity (the expander pushes this same ref to
# `$spawn_refs`). `$ordinal` must be unique within the owning transaction.
sub _conditional_do_ref_from_clause {
    my ($clause, $tn, $ordinal, $constant_values, $actor, $generated_children, $label) = @_;
    my $child = $clause->[1];
    my $overrides = _do_parameter_overrides($clause, $tn, $label, $constant_values, $actor);
    my $generated_child = (
        @$overrides
            || (ref($generated_children) eq 'HASH' && $generated_children->{$child})
    ) ? 1 : 0;
    my $ref = {
        child           => $child,
        activation_kind => 'do',
        generated_child => $generated_child,
    };
    if ($generated_child) {
        $ref->{instance} = _generated_conditional_do_instance_name($tn, $child, $ordinal);
        $ref->{branch_do} = 1;
        $ref->{parameter_overrides} = $overrides;
        my $domain = _activation_domain_from_clause($clause, $tn, $label);
        $ref->{domain} = $domain if defined $domain;
        my $port_bindings = _activation_bindings_from_clause($clause, $tn, $label);
        $ref->{port_bindings} = $port_bindings if @$port_bindings;
    }
    return $ref;
}

sub _generated_conditional_do_instance_name {
    my ($owner, $child, $ordinal) = @_;
    return "${owner}_${child}_cond_do_$ordinal";
}

sub _repeat_body_do_is_generated_activation {
    my ($clause, $target, $generated_children) = @_;
    return 1 if _repeat_body_do_uses_generated_params($clause);
    return 1 if ref($generated_children) eq 'HASH'
        && defined($target)
        && !ref($target)
        && $generated_children->{$target};
    return 0;
}

sub _repeat_body_do_uses_generated_params {
    my ($clause) = @_;
    return 0 unless ref($clause) eq 'ARRAY' && @$clause >= 3;
    for my $subclause (@{$clause}[2 .. $#$clause]) {
        next unless ref($subclause) eq 'ARRAY'
            && @$subclause
            && defined($subclause->[0])
            && !ref($subclause->[0]);
        return 1 if $subclause->[0] eq 'params';
    }
    return 0;
}

sub _repeat_body_do_uses_bindings {
    my ($clause) = @_;
    return 0 unless ref($clause) eq 'ARRAY' && @$clause >= 3;
    for my $subclause (@{$clause}[2 .. $#$clause]) {
        next unless ref($subclause) eq 'ARRAY'
            && @$subclause
            && defined($subclause->[0])
            && !ref($subclause->[0]);
        return 1 if $subclause->[0] eq 'bind';
    }
    return 0;
}

sub _repeat_body_do_uses_domain {
    my ($clause) = @_;
    return 0 unless ref($clause) eq 'ARRAY' && @$clause >= 3;
    for my $subclause (@{$clause}[2 .. $#$clause]) {
        next unless ref($subclause) eq 'ARRAY'
            && @$subclause
            && defined($subclause->[0])
            && !ref($subclause->[0]);
        return 1 if $subclause->[0] eq 'domain';
    }
    return 0;
}

sub _repeat_body_do_is_cross_domain_attempt {
    my ($actor, $calling_tx_name, $target_tx_name) = @_;
    return 0 unless ref($actor) eq 'HASH';
    return 0 unless _actor_has_clock_domains($actor);
    my $default_domain = $actor->{clock_domains}{default};
    my ($calling_domain, $target_domain);
    for my $tx (@{$actor->{transactions} || []}) {
        next unless ref($tx) eq 'HASH';
        $calling_domain = _domain_for_entry($tx, $default_domain)
            if defined($tx->{name}) && $tx->{name} eq $calling_tx_name;
        $target_domain = _domain_for_entry($tx, $default_domain)
            if defined($tx->{name}) && $tx->{name} eq $target_tx_name;
    }
    return 0 unless defined($calling_domain) && defined($target_domain);
    return $calling_domain ne $target_domain ? 1 : 0;
}

sub _spawn_parameter_overrides {
    my ($clause, $tn, $label, $constant_values, $actor) = @_;
    return _activation_parameter_overrides($clause, $tn, $label, $constant_values, $actor);
}

sub _do_parameter_overrides {
    my ($clause, $tn, $label, $constant_values, $actor) = @_;
    return _activation_parameter_overrides($clause, $tn, $label, $constant_values, $actor);
}

sub _trigger_parameter_overrides {
    my ($clause, $rule_name, $label, $constant_values, $actor) = @_;
    return _activation_parameter_overrides($clause, $rule_name, $label, $constant_values, $actor);
}

sub _activation_parameter_overrides {
    my ($clause, $tn, $label, $constant_values, $actor) = @_;
    return [] unless ref($clause) eq 'ARRAY' && @$clause;
    my $keyword = $clause->[0];
    return [] unless defined($keyword) && !ref($keyword) && ($keyword eq 'spawn' || $keyword eq 'do' || $keyword eq 'trigger');
    my $start = $keyword eq 'spawn' ? 4 : 2;
    return [] if $#$clause < $start;

    my $instance = $keyword eq 'spawn'
        ? $clause->[3]
        : $clause->[1];
    for my $subclause (@{$clause}[$start .. $#$clause]) {
        next unless ref($subclause) eq 'ARRAY'
            && @$subclause
            && defined($subclause->[0])
            && !ref($subclause->[0])
            && $subclause->[0] eq 'params';
        return _parse_activation_params_clause($subclause, $tn, $keyword, $instance, $label, $constant_values, $actor);
    }
    return [];
}

sub _activation_domain_from_clause {
    my ($clause, $tn, $label) = @_;
    return undef unless ref($clause) eq 'ARRAY' && @$clause;
    my $keyword = $clause->[0];
    return undef unless defined($keyword) && !ref($keyword) && ($keyword eq 'spawn' || $keyword eq 'do');
    my $start = $keyword eq 'spawn' ? 4 : 2;
    return undef if $#$clause < $start;

    my $domain;
    for my $subclause (@{$clause}[$start .. $#$clause]) {
        next unless ref($subclause) eq 'ARRAY'
            && @$subclause
            && defined($subclause->[0])
            && !ref($subclause->[0])
            && $subclause->[0] eq 'domain';
        confess "Transaction '$tn': $keyword has duplicate '(domain ...)' subclause in $label\n"
            if defined $domain;
        confess "Transaction '$tn': $keyword domain requires '(domain name)' in $label\n"
            unless @$subclause == 2 && _is_hdl_identifier($subclause->[1]);
        $domain = $subclause->[1];
    }

    return $domain;
}

sub _parse_spawn_params_clause {
    my ($params_clause, $tn, $instance, $label, $constant_values, $actor) = @_;
    return _parse_activation_params_clause($params_clause, $tn, 'spawn', $instance, $label, $constant_values, $actor);
}

sub _parse_activation_params_clause {
    my ($params_clause, $tn, $activation_kind, $instance, $label, $constant_values, $actor) = @_;
    _validate_activation_params_clause_shape($params_clause, $tn, $activation_kind, $instance, $label);

    my @overrides;
    for my $entry (@{$params_clause}[1 .. $#$params_clause]) {
        my ($name, $value) = @$entry;
        my $resolved_value = _resolve_activation_param_value(
            $value,
            "Transaction '$tn': $activation_kind instance '$instance' parameter '$name'",
            $constant_values,
            $actor,
            1,
        );
        push @overrides, {
            name  => $name,
            value => $resolved_value,
        };
    }

    return \@overrides;
}

sub _validate_activation_params_clause_shape {
    my ($params_clause, $tn, $activation_kind, $instance, $label) = @_;
    confess "Transaction '$tn': $activation_kind params require '(params (NAME value) ...)' in $label\n"
        unless ref($params_clause) eq 'ARRAY'
            && @$params_clause >= 2
            && defined($params_clause->[0])
            && !ref($params_clause->[0])
            && $params_clause->[0] eq 'params';

    my %seen;
    for my $entry (@{$params_clause}[1 .. $#$params_clause]) {
        confess "Transaction '$tn': $activation_kind params entries require '(NAME value)' in $label\n"
            unless ref($entry) eq 'ARRAY' && @$entry == 2;
        my ($name, $value) = @$entry;
        confess "Transaction '$tn': $activation_kind parameter override names must be scalar HDL identifiers\n"
            unless _is_hdl_identifier($name);
        confess "Transaction '$tn': $activation_kind instance '$instance' has duplicate parameter override '$name'\n"
            if $seen{$name}++;
        confess "Transaction '$tn': $activation_kind instance '$instance' parameter '$name' value must be defined in $label\n"
            unless defined $value;
    }

    return 1;
}

sub _generated_do_instance_name {
    my ($owner, $child, $ordinal) = @_;
    return "${owner}_${child}_do_$ordinal";
}

sub _generated_repeat_do_instance_name {
    my ($owner, $child, $ordinal) = @_;
    return "${owner}_${child}_repeat_do_$ordinal";
}

sub _generated_rule_trigger_instance_name {
    my ($rule, $target, $ordinal) = @_;
    return "${rule}_${target}_trigger_$ordinal";
}

sub _do_clause_ordinal {
    my ($tx, $target_clause) = @_;
    my $ordinal = 0;
    for my $clause (@{$tx->{clauses} || []}) {
        next unless ref($clause) eq 'ARRAY'
            && @$clause
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'do';
        return $ordinal if $clause == $target_clause;
        ++$ordinal;
    }
    return 0;
}

sub _activation_bindings_from_clause {
    my ($clause, $owner, $label) = @_;
    return [] unless ref($clause) eq 'ARRAY' && @$clause;

    my $keyword = $clause->[0];
    my $start = $keyword eq 'spawn' ? 4 : 2;
    return [] if $#$clause < $start;

    my @bindings;
    my $saw_bind;
    for my $subclause (@{$clause}[$start .. $#$clause]) {
        confess "Transaction '$owner': activation subclauses must be list forms in $label\n"
            unless ref($subclause) eq 'ARRAY'
                && @$subclause
                && defined($subclause->[0])
                && !ref($subclause->[0])
                && length($subclause->[0]);
        my $head = $subclause->[0];
        next if ($keyword eq 'spawn' || $keyword eq 'do' || $keyword eq 'trigger') && $head eq 'params';
        next if ($keyword eq 'spawn' || $keyword eq 'do') && $head eq 'domain';
        confess "Transaction '$owner': activation has duplicate '(bind ...)' subclause in $label\n"
            if $head eq 'bind' && $saw_bind++;
        confess "Transaction '$owner': activation supports only '(bind ...)' subclauses in $label\n"
            unless $head eq 'bind';
        @bindings = @{_parse_activation_bind_clause($subclause, "Transaction '$owner': activation")};
    }

    return \@bindings;
}

sub _parse_activation_bind_clause {
    my ($clause, $context) = @_;
    confess "$context bind requires '(bind (input port signal) ...)'\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause >= 2
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'bind';

    my @bindings;
    my %seen;
    my %seen_output_actor_target;
    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "$context bind entries must be '(input port expr [(timing snapshot|live)])' or '(output port signal)'\n"
            unless ref($entry) eq 'ARRAY' && (@$entry == 3 || @$entry == 4);
        my ($role, $port, $actor_endpoint, $timing_clause) = @$entry;
        confess "$context bind role must be input or output\n"
            unless defined($role) && !ref($role) && ($role eq 'input' || $role eq 'output');
        confess "$context bind transaction port must be a scalar HDL identifier\n"
            unless _is_hdl_identifier($port);
        my $timing_mode;
        if (defined $timing_clause) {
            confess "$context output bind timing selection is supported only on input bindings\n"
                if $role eq 'output';
            $timing_mode = _parse_activation_binding_timing_clause($timing_clause, $context);
        }
        if ($role eq 'output') {
            confess "$context output bind actor target must be a scalar HDL identifier\n"
                unless _is_hdl_identifier($actor_endpoint);
            confess "$context output bindings target actor signal '$actor_endpoint' more than once\n"
                if $seen_output_actor_target{$actor_endpoint}++;
        } else {
            confess "$context input bind expression must be a scalar signal, numeric/exact-width literal, or non-empty list expression\n"
                unless _is_activation_input_binding_expr_shape($actor_endpoint);
        }
        confess "$context has duplicate binding for transaction port '$port'\n"
            if $seen{$port}++;

        my $actor_expr = _clone_isf_value($actor_endpoint);
        my $actor_signal = _is_hdl_identifier($actor_endpoint) ? $actor_endpoint : undef;
        push @bindings, {
            role             => $role,
            port             => $port,
            actor_signal     => $actor_signal,
            actor_expr       => $actor_expr,
            actor_expression => _format_isf_expr($actor_expr),
            (defined($timing_mode) ? (timing_mode => $timing_mode) : ()),
        };
    }

    return \@bindings;
}

sub _parse_activation_binding_timing_clause {
    my ($clause, $context) = @_;

    confess "$context input bind timing must be '(timing snapshot)' or '(timing live)'\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause == 2
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'timing'
            && defined($clause->[1])
            && !ref($clause->[1])
            && ($clause->[1] eq 'snapshot' || $clause->[1] eq 'live');

    return $clause->[1];
}

sub _validate_activation_bindings {
    my ($actor, $owner_tx, $target_tx, $bindings, $context, $options) = @_;
    $options ||= {};
    $bindings ||= [];

    my %ports = _transaction_port_map($target_tx);
    my @declared_ports = sort keys %ports;
    confess "$context requires '(bind ...)' because transaction '$target_tx->{name}' declares ports\n"
        if @declared_ports && !@$bindings;
    confess "$context has '(bind ...)' but transaction '$target_tx->{name}' declares no ports\n"
        if !@declared_ports && @$bindings;

    my %seen;
    for my $binding (@$bindings) {
        my $port_name = $binding->{port};
        confess "$context binds unknown transaction port '$port_name' on '$target_tx->{name}'\n"
            unless exists $ports{$port_name};

        my $port = $ports{$port_name};
        confess "$context binding for port '$port_name' uses role '$binding->{role}' but the transaction declares '$port->{direction}'\n"
            unless $binding->{role} eq $port->{direction};
        confess "$context output binding for port '$port_name' requires a generated-child rule trigger completion identity; direct/local rule-trigger targets do not provide one yet\n"
            if exists($options->{allow_outputs}) && !$options->{allow_outputs} && $binding->{role} eq 'output';
        confess "$context has duplicate binding for transaction port '$port_name'\n"
            if $seen{$port_name}++;

        if ($binding->{role} eq 'input') {
            _validate_activation_input_binding_expr($actor, $owner_tx, $binding, $port, $context);
            _validate_activation_input_binding_timing($binding, $context, $options);
        } else {
            my $signal = $binding->{actor_signal};
            my $info = _binding_signal_info($actor, $owner_tx, $signal);
            confess "$context binding for port '$port_name' references unknown actor signal '$signal'\n"
                unless $info;
            confess "$context output binding for port '$port_name' targets actor input '$signal', but actor inputs are read-only\n"
                if $info->{kind} eq 'actor_input';

            my $port_width = $port->{width} // 1;
            my $signal_width = $info->{width} // 1;
            confess "$context binding for port '$port_name' width $port_width does not match actor signal '$signal' width $signal_width\n"
                unless $port_width == $signal_width;
        }
    }

    for my $port_name (@declared_ports) {
        confess "$context does not bind transaction port '$port_name'\n"
            unless $seen{$port_name};
    }

    return 1;
}

sub _validate_activation_input_binding_timing {
    my ($binding, $context, $options) = @_;
    my $mode = $binding->{timing_mode};
    return 1 unless defined($mode);

    my $site_kind = $options->{site_kind} // 'do';
    my $current_timing = _activation_input_binding_current_timing(
        $site_kind,
        $options->{generated_instance} ? 1 : 0,
    );
    my $matches = $mode eq 'snapshot'
        ? ($current_timing eq 'activation_region' || $current_timing eq 'trigger_payload')
        : ($current_timing eq 'generated_live_handoff');

    confess "$context input binding for port '$binding->{port}' requested timing '$mode', but this activation currently uses '$current_timing'; behavior-changing timing conversion is not supported yet\n"
        unless $matches;

    return 1;
}

sub _activation_input_binding_current_timing {
    my ($site_kind, $generated_instance) = @_;

    return 'trigger_payload' if $site_kind eq 'rule_trigger';
    return 'generated_live_handoff' if $generated_instance;
    return 'activation_region';
}

sub _transaction_port_map {
    my ($tx) = @_;
    my (%ports, %source_names);
    for my $direction (qw(input output)) {
        my $key = "${direction}s";
        for my $port (@{($tx->{ports} || {})->{$key} || []}) {
            my $source_name = $port->{name};
            if (exists $port->{_isf_formal_identity}) {
                my $origin = $port->{_isf_formal_identity};
                confess "Transaction '$tx->{name}': malformed or stale formal identity projection\n"
                    unless ref($origin) eq 'HASH' && keys(%$origin) == 2
                        && defined($origin->{physical_name}) && !ref($origin->{physical_name})
                        && $origin->{physical_name} eq $port->{name}
                        && ref($origin->{source}) eq 'ARRAY' && @{$origin->{source}} == 4
                        && !(grep { !defined($_) || ref($_) || !_is_hdl_identifier($_) } @{$origin->{source}})
                        && $origin->{source}[0] eq 'transaction_port'
                        && $origin->{source}[2] eq $tx->{name};
                $source_name = $origin->{source}[3];
            }
            confess "Transaction '$tx->{name}': duplicate formal source identity '$source_name'\n"
                if $source_names{$source_name}++;
            $ports{$port->{name}} = {
                name      => $port->{name},
                source_name => $source_name,
                direction => $direction,
                width     => $port->{width} // 1,
            };
        }
    }
    return %ports;
}

sub _binding_signal_info {
    my ($actor, $tx, $name) = @_;
    return undef unless _is_hdl_identifier($name);

    # Actuals belong to the caller's lexical scope. An explicit formal owns
    # its spelling even when the actor declares a pin or storage with that
    # name. Do not use the whole inferred width map here: it also contains
    # actor inputs/outputs, whose read/write restrictions must survive.
    if ($tx) {
        my %ports = _transaction_port_map($tx);
        return { kind => 'transaction_variable', width => $ports{$name}{width} }
            if exists $ports{$name};
    }

    for my $input (@{$actor->{interface}{inputs} || []}) {
        return { kind => 'actor_input', width => $input->{width} // 1 }
            if $input->{name} eq $name;
    }
    for my $output (@{$actor->{interface}{outputs} || []}) {
        return { kind => 'actor_output', width => $output->{width} // 1 }
            if $output->{name} eq $name;
    }
    for my $entry (@{$actor->{storage} || []}) {
        for my $signal (@{$entry->{signals} || []}) {
            return { kind => 'actor_storage', width => $signal->{width} // 1 }
                if $signal->{name} eq $name;
        }
    }

    if ($tx) {
        my $widths = _build_signal_width_map($actor, $tx);
        return { kind => 'transaction_variable', width => $widths->{$name} }
            if exists $widths->{$name};
    }

    return undef;
}

sub _is_hdl_identifier {
    my ($value) = @_;
    return defined($value) && !ref($value) && $value =~ /\A[A-Za-z_]\w*\z/;
}

sub _is_enum_member_reference {
    my ($value) = @_;
    return defined($value)
        && !ref($value)
        && $value =~ /\A[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+\z/;
}

sub _is_package_constant_path_reference_shape {
    my ($value) = @_;
    return defined($value)
        && !ref($value)
        && $value =~ /\A[A-Za-z_]\w*\.[A-Za-z_]\w*(?:\.[A-Za-z_]\w*|\[\d+\])+\z/;
}

sub _is_package_constant_reference_shape {
    my ($value) = @_;
    return defined($value)
        && !ref($value)
        && $value =~ /\A[A-Za-z_]\w*\.[A-Za-z_]\w*(?:\.[A-Za-z_]\w*|\[\d+\])*\z/;
}

sub _is_activation_input_binding_expr_shape {
    my ($expr) = @_;
    return 1 if ref($expr) eq 'ARRAY' && @$expr;
    return 0 if ref($expr);
    return 0 unless defined($expr) && length($expr);
    return 1 if _is_hdl_identifier($expr);
    return 1 if _is_numeric_or_exact_width_literal($expr);
    return 0;
}

sub _activation_binding_actor_expr_text {
    my ($binding) = @_;
    return $binding->{actor_expression}
        if ref($binding) eq 'HASH' && exists($binding->{actor_expression});
    return _format_isf_expr($binding->{actor_expr})
        if ref($binding) eq 'HASH' && exists($binding->{actor_expr});
    return $binding->{actor_signal};
}

sub _activation_binding_actor_endpoint_kind {
    my ($binding) = @_;
    return 'signal'
        if ref($binding) eq 'HASH'
            && defined($binding->{actor_signal})
            && length($binding->{actor_signal});

    my $expr = ref($binding) eq 'HASH' && exists($binding->{actor_expr})
        ? $binding->{actor_expr}
        : undef;
    return 'literal' if _is_numeric_or_exact_width_literal($expr);
    return 'expression';
}

sub _validate_activation_input_binding_expr {
    my ($actor, $owner_tx, $binding, $port, $context) = @_;
    my $port_name = $binding->{port};
    my $expr = exists($binding->{actor_expr}) ? $binding->{actor_expr} : $binding->{actor_signal};
    my $actor_signal = $binding->{actor_signal};

    if (defined $actor_signal) {
        my $info = _binding_signal_info($actor, $owner_tx, $actor_signal);
        confess "$context binding for port '$port_name' references unknown actor signal '$actor_signal'\n"
            unless $info;
        confess "$context input binding for port '$port_name' reads actor output '$actor_signal', but actor output readback is not public\n"
            if $info->{kind} eq 'actor_output';

        my $port_width = $port->{width} // 1;
        my $signal_width = $info->{width} // 1;
        confess "$context binding for port '$port_name' width $port_width does not match actor signal '$actor_signal' width $signal_width\n"
            unless $port_width == $signal_width;
        return 1;
    }

    my %seen_refs;
    for my $ref (_activation_binding_expr_signals($expr)) {
        next if $seen_refs{$ref}++;
        my $info = _binding_signal_info($actor, $owner_tx, $ref);
        confess "$context input binding expression for port '$port_name' references unknown actor signal '$ref'\n"
            unless $info;
        confess "$context input binding expression for port '$port_name' reads actor output '$ref', but actor output readback is not public\n"
            if $info->{kind} eq 'actor_output';
    }

    my $widths = _build_signal_width_map($actor, $owner_tx || { clauses => [] });
    my $expr_width = _activation_binding_expr_width($expr, $widths);
    my $port_width = $port->{width} // 1;
    confess "$context input binding expression for port '$port_name' width $expr_width does not match transaction port width $port_width\n"
        if defined($expr_width) && $expr_width > 0 && $expr_width != $port_width;

    return 1;
}

sub _activation_binding_expr_signals {
    my ($expr) = @_;
    return () unless defined $expr;
    if (!ref($expr)) {
        return _is_hdl_identifier($expr) ? ($expr) : ();
    }
    return () unless ref($expr) eq 'ARRAY';

    my @signals;
    for my $index (0 .. $#$expr) {
        next if $index == 0 && !ref($expr->[$index]);
        push @signals, _activation_binding_expr_signals($expr->[$index]);
    }
    return @signals;
}

sub _activation_binding_expr_width {
    my ($expr, $widths) = @_;
    my $known = _known_expr_width($expr, $widths);
    return $known if defined $known;
    return undef unless ref($expr) eq 'ARRAY' && @$expr;

    my $op = $expr->[0];
    return undef if ref($op);
    my @operand_widths = map { _activation_binding_expr_width($_, $widths) } @{$expr}[1 .. $#$expr];

    if ($op eq 'concat') {
        return undef if grep { !defined($_) || $_ <= 0 } @operand_widths;
        my $total = 0;
        $total += $_ for @operand_widths;
        return $total;
    }

    return 1 if $op =~ /\A(?:==|!=|<|<=|>|>=|&&|\|\|)\z/;
    return 1 if $op eq '!';
    return $operand_widths[0] if ($op eq '~' || $op eq '<<' || $op eq '>>') && defined($operand_widths[0]);
    if ($op =~ /\A(?:\+|-|\*|\/|%|&|\||\^)\z/) {
        return undef if grep { !defined($_) || $_ <= 0 } @operand_widths;
        my $max = 1;
        for my $width (@operand_widths) {
            $max = $width if $width > $max;
        }
        return $max;
    }

    return undef;
}

sub _validate_isf_param_value {
    my ($value, $context) = @_;
    if (!ref($value)) {
        confess "$context uses unsupported parameter value '$value'; first ISF parameter binding accepts numeric, exact-width, and aggregate/list literals only\n"
            unless defined($value) && _is_numeric_or_exact_width_literal($value);
        return 1;
    }

    confess "$context uses unsupported parameter value shape; first ISF parameter binding accepts non-empty aggregate/list literals only\n"
        unless ref($value) eq 'ARRAY' && @$value;

    for my $item (@$value) {
        _validate_isf_param_value($item, $context);
    }
    return 1;
}

sub _validate_transaction_param_value {
    my ($value, $context, $actor, $transaction_param_names, $earlier_scalar_transaction_params) = @_;

    _resolve_transaction_param_default_value(
        $value,
        $context,
        $actor,
        $transaction_param_names || {},
        $earlier_scalar_transaction_params || {},
    );
    return 1;
}

sub _resolve_transaction_param_default_value {
    my ($value, $context, $actor, $transaction_param_names, $earlier_scalar_transaction_params) = @_;
    $transaction_param_names ||= {};
    $earlier_scalar_transaction_params ||= {};

    if (!ref($value)) {
        confess "$context uses undefined parameter value; transaction parameter defaults accept numeric, exact-width, aggregate/list, earlier scalar transaction parameter, actor constant, actor scalar parameter, scalar enum member, and qualified package scalar constant literals only\n"
            unless defined($value);

        return (_clone_isf_value($value), _clone_isf_value($value), 0)
            if defined($value) && _is_numeric_or_exact_width_literal($value);

        if (my $package_constant = _actor_package_constant_reference($actor, $value)) {
            my ($package_name, $constant_name, $suffix) = @$package_constant;
            my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
            if (defined $constant_payload) {
                confess "$context token '$value' is ambiguous: it matches local enum member '$value' and imported package constant '$value'\n"
                    if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
                confess "$context package constant '$package_name.$constant_name' aggregate/member path '$value' remains deferred; transaction parameter defaults accept only qualified package scalar constants in this slice\n"
                    if $suffix ne '';
                my $resolved_value = _package_constant_scalar_value($constant_payload);
                confess "$context package constant '$package_name.$constant_name' must resolve to a scalar numeric or exact-width literal value\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return (_clone_isf_value($value), _clone_isf_value($resolved_value), 1);
            }

            confess "$context references unknown package constant '$value'\n"
                if $suffix eq '' && !_actor_local_enum_member_exists($actor, $package_name, $constant_name);
        }

        if (_is_enum_member_reference($value)) {
            my $resolved_value = _resolve_actor_enum_member_value($actor, $value);
            confess "$context references unknown enum member '$value'\n"
                unless defined($resolved_value) && !ref($resolved_value);
            confess "$context enum member '$value' must resolve to a non-negative integer literal value\n"
                unless defined _non_negative_integer_from_literal($resolved_value);
            return (_clone_isf_value($value), _clone_isf_value($resolved_value), 1);
        }

        if (_is_hdl_identifier($value)) {
            if (exists $earlier_scalar_transaction_params->{$value}) {
                my $resolved_value = $earlier_scalar_transaction_params->{$value};
                return (_clone_isf_value($value), _clone_isf_value($resolved_value), 1);
            }

            confess "$context transaction parameter '$value' must reference an earlier scalar transaction parameter default\n"
                if $transaction_param_names->{$value};

            if (my $constant = _actor_constant_by_name($actor, $value)) {
                my $resolved_value = _constant_resolved_value($constant);
                confess "$context actor constant '$value' must resolve to a scalar numeric or exact-width literal value\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return (_clone_isf_value($resolved_value), _clone_isf_value($resolved_value), 1);
            }

            if (my $param = _actor_param_by_name($actor, $value)) {
                my $resolved_value = _param_resolved_value($param);
                confess "$context actor parameter '$value' must resolve to a scalar numeric or exact-width literal value\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return (_clone_isf_value($resolved_value), _clone_isf_value($resolved_value), 1);
            }

            confess "$context token '$value' is a runtime interface signal; transaction parameter defaults accept literals, earlier scalar transaction parameters, declared actor constants, actor scalar parameters, enum members, and qualified package scalar constants only\n"
                if _actor_interface_signal_by_name($actor, $value);

            confess "$context token '$value' is not an earlier scalar transaction parameter, declared actor constant, actor scalar parameter, enum member, or qualified package scalar constant\n";
        }

        confess "$context uses unsupported parameter value '$value'; transaction parameter defaults accept numeric, exact-width, aggregate/list, earlier scalar transaction parameter, actor constant, actor scalar parameter, scalar enum member, and qualified package scalar constant literals only\n";
    }

    confess "$context uses unsupported parameter value shape; transaction parameter defaults accept non-empty aggregate/list literals\n"
        unless ref($value) eq 'ARRAY' && @$value;

    my @published;
    my @resolved;
    my $has_resolved_leaf = 0;
    for my $item (@$value) {
        my ($published_item, $resolved_item, $item_has_resolved_leaf) =
            _resolve_transaction_param_default_value(
                $item,
                $context,
                $actor,
                $transaction_param_names,
                $earlier_scalar_transaction_params,
            );
        push @published, $published_item;
        push @resolved, $resolved_item;
        $has_resolved_leaf ||= $item_has_resolved_leaf;
    }

    return (\@published, \@resolved, $has_resolved_leaf);
}

sub _record_earlier_scalar_transaction_param_value {
    my ($earlier_scalar_transaction_param_values, $param) = @_;
    return unless ref($earlier_scalar_transaction_param_values) eq 'HASH';
    return unless ref($param) eq 'HASH';

    my $name = $param->{name};
    return unless defined($name) && !ref($name) && length($name);
    return if ref($param->{value});

    my $resolved_value = exists($param->{resolved_value})
        ? $param->{resolved_value}
        : $param->{value};
    return unless defined($resolved_value)
        && !ref($resolved_value)
        && _is_numeric_or_exact_width_literal($resolved_value);

    $earlier_scalar_transaction_param_values->{$name} = _clone_isf_value($resolved_value);
}

sub _resolve_activation_param_value {
    my ($value, $context, $constant_values, $actor, $allow_enum_member) = @_;
    $constant_values ||= {};
    $allow_enum_member //= 0;

    if (!ref($value)) {
        confess "$context uses undefined parameter value; activation parameter values accept numeric, exact-width, actor-constant, actor scalar parameter, scalar enum member, qualified package scalar constant, and aggregate/list literal values only\n"
            unless defined($value);
        return _clone_isf_value($value)
            if _is_numeric_or_exact_width_literal($value);
        return _clone_isf_value($constant_values->{$value})
            if _is_hdl_identifier($value) && exists $constant_values->{$value};
        if (_is_hdl_identifier($value)) {
            my $param = _actor_param_by_name($actor, $value);
            if ($param) {
                my $resolved_value = _param_resolved_value($param);
                confess "$context actor parameter '$value' must resolve to a scalar numeric or exact-width literal\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return _clone_isf_value($resolved_value);
            }
        }
        if (my $package_constant = _actor_package_constant_reference($actor, $value)) {
            my ($package_name, $constant_name, $suffix) = @$package_constant;
            my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
            if (defined $constant_payload) {
                confess "$context token '$value' is ambiguous: it matches local enum member '$value' and imported package constant '$value'\n"
                    if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
                confess "$context package constant '$package_name.$constant_name' aggregate/member path '$value' remains deferred; activation parameter overrides accept only qualified package scalar constants in this slice\n"
                    if $suffix ne '';
                my $resolved_value = _package_constant_scalar_value($constant_payload);
                confess "$context package constant '$package_name.$constant_name' must resolve to a scalar numeric or exact-width literal value\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return _clone_isf_value($resolved_value);
            }

            confess "$context references unknown package constant '$value'\n"
                if $suffix eq '' && !_actor_local_enum_member_exists($actor, $package_name, $constant_name);
        }
        if (_is_enum_member_reference($value)) {
            confess "$context uses unsupported aggregate/list override leaf '$value'; activation parameter aggregate/list overrides accept numeric, exact-width, actor-constant, actor scalar parameter, enum member, and qualified package scalar constant leaves only when enum members resolve to non-negative integer literal values\n"
                unless $allow_enum_member;
            my $resolved_value = _resolve_actor_enum_member_value($actor, $value);
            confess "$context references unknown enum member '$value'\n"
                unless defined($resolved_value) && !ref($resolved_value);
            confess "$context enum member '$value' must resolve to a non-negative integer literal value\n"
                unless defined _non_negative_integer_from_literal($resolved_value);
            return _clone_isf_value($resolved_value);
        }

        confess "$context uses unsupported parameter value '$value'; activation parameter values accept numeric, exact-width, actor-constant, actor scalar parameter, scalar enum member, qualified package scalar constant, and aggregate/list literal values only\n";
    }

    confess "$context uses unsupported parameter value shape; activation parameter values accept non-empty aggregate/list literal values only\n"
        unless ref($value) eq 'ARRAY' && @$value;

    return [
        map {
            _resolve_activation_param_value($_, $context, $constant_values, $actor, $allow_enum_member)
        } @$value
    ];
}

sub _is_numeric_or_exact_width_literal {
    my ($value) = @_;
    return 0 unless defined($value) && !ref($value);
    return 1 if $value =~ /\A\d+\z/;
    return 1 if $value =~ /\A\d+'[bBoOdDhH][0-9a-fA-F_xXzZ]+\z/;
    return 0;
}

sub _param_values_shape_compatible {
    my ($declared, $override) = @_;
    return 1 if !ref($declared) && !ref($override);
    return 0 unless ref($declared) eq 'ARRAY' && ref($override) eq 'ARRAY';
    return 0 unless @$declared == @$override;
    for my $index (0 .. $#$declared) {
        return 0 unless _param_values_shape_compatible($declared->[$index], $override->[$index]);
    }
    return 1;
}

sub _clone_isf_value {
    my ($value) = @_;
    return [ map { _clone_isf_value($_) } @$value ] if ref($value) eq 'ARRAY';
    return { map { $_ => _clone_isf_value($value->{$_}) } keys %$value } if ref($value) eq 'HASH';
    return $value;
}

sub _actor_constant_value_map {
    my ($actor) = @_;
    my %values;
    return \%values unless ref($actor) eq 'HASH';

    for my $constant (@{$actor->{constants} || []}) {
        next unless ref($constant) eq 'HASH';
        my $name = $constant->{name};
        next unless _is_hdl_identifier($name);
        $values{$name} = _clone_isf_value(_constant_resolved_value($constant));
    }

    return \%values;
}

sub _resolve_actor_enum_member_value {
    my ($actor, $member_ref) = @_;
    return undef unless ref($actor) eq 'HASH' && _is_enum_member_reference($member_ref);

    my $symbols = $actor->{enum_symbols} || {};
    if ($member_ref =~ /\A([A-Za-z_]\w*)\.([A-Za-z_]\w*)\.([A-Za-z_]\w*)\z/) {
        my ($package_name, $enum_name, $member_name) = ($1, $2, $3);
        return _clone_isf_value(((($symbols->{packages} || {})->{$package_name} || {})->{$enum_name} || {})->{$member_name});
    }

    if ($member_ref =~ /\A([A-Za-z_]\w*)\.([A-Za-z_]\w*)\z/) {
        my ($enum_name, $member_name) = ($1, $2);
        return _clone_isf_value((($symbols->{local} || {})->{$enum_name} || {})->{$member_name});
    }

    return undef;
}

sub _actor_package_constant_reference {
    my ($actor, $value) = @_;
    return undef unless defined($value) && !ref($value);
    return undef unless $value =~ /\A([A-Za-z_]\w*)\.([A-Za-z_]\w*)((?:\.[A-Za-z_]\w*|\[\d+\])*)\z/;

    my ($package_name, $constant_name, $suffix) = ($1, $2, $3 // '');
    my $package_constants = (($actor->{constant_symbols} || {})->{packages} || {});
    return undef unless exists $package_constants->{$package_name};
    return [ $package_name, $constant_name, $suffix ];
}

sub _actor_package_constant_payload {
    my ($actor, $package_name, $constant_name) = @_;
    my $package_constants = (($actor->{constant_symbols} || {})->{packages} || {});
    return undef unless exists $package_constants->{$package_name};
    return undef unless exists(($package_constants->{$package_name} || {})->{$constant_name});
    return _clone_isf_value($package_constants->{$package_name}{$constant_name});
}

sub _actor_local_enum_member_exists {
    my ($actor, $enum_name, $member_name) = @_;
    return exists(((($actor->{enum_symbols} || {})->{local} || {})->{$enum_name} || {})->{$member_name});
}

sub _package_constant_scalar_value {
    my ($payload) = @_;
    return undef unless defined $payload;
    return $payload unless ref($payload) eq 'HASH';
    return undef unless ($payload->{kind} || '') eq 'scalar';
    return $payload->{payload};
}

sub _constant_resolved_value {
    my ($constant) = @_;
    return undef unless ref($constant) eq 'HASH';
    return exists($constant->{resolved_value})
        ? $constant->{resolved_value}
        : $constant->{value};
}

sub _param_resolved_value {
    my ($param) = @_;
    return undef unless ref($param) eq 'HASH';
    return exists($param->{resolved_value})
        ? $param->{resolved_value}
        : $param->{value};
}

sub _validate_repeat_clause {
    my ($clause, $tn, $label) = @_;

    confess "Transaction '$tn': repeat requires '(repeat count body...)' in $label\n"
        unless @$clause >= 3
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1]);

    return 1;
}

sub _validate_repeat_body_spawn_subset {
    my ($clause, $tn, $label, $context_depths, $generated_children, $actor, $options) = @_;
    $context_depths ||= {};
    $generated_children ||= {};
    $options ||= {};
    my $parent_exit_sync_after_repeat = $options->{parent_exit_sync_after_repeat};
    my @pending_spawns;
    my $awaiting_multi_pending_drain = 0;
    my $pending_local_do_before_drain = 0;
    my $pending_generated_do_before_drain = 0;
    my $pending_generated_do_kind_before_drain;
    my $spawn_after_local_do_before_drain = 0;
    my $spawn_after_generated_do_before_drain = 0;
    my $spawn_after_generated_do_kind_before_drain;
    my $pending_loop_local_do_before_drain = 0;
    my $top_level_repeat = $label eq 'transaction body';
    my $when_body_repeat = $label eq 'when body'
        && _context_depths_match_exactly($context_depths, { when => 1 });
    my $switch_branch_repeat = $label eq 'switch branch'
        && _context_depths_match_exactly($context_depths, { switch => 1 });
    # A repeat directly inside a single (while ...)/(until ...) body, with no
    # other branch/loop nesting. Only a plain local (do child) is enabled here
    # (a validator gate relaxation; the lowering already handles it). spawn,
    # generated do, await-sync, and deeper nesting stay deferred.
    my $loop_body_repeat = ($label eq 'while body' || $label eq 'until body')
        && (_context_depths_match_exactly($context_depths, { while => 1 })
            || _context_depths_match_exactly($context_depths, { until => 1 }));
    my $while_then_when_repeat = _repeat_body_context_is_while_then_when($label, $context_depths) ? 1 : 0;
    # A repeat reached through deeper branch nesting (when+ -> repeat,
    # switch -> when+ -> repeat). Returns 0 for loop-contained and top-level/
    # single-branch contexts, so this is exactly the deeper branch case.
    my $deeper_nested_repeat = _repeat_body_context_is_deeper_nested($label, $context_depths) ? 1 : 0;
    my $pending_local_do_label = $when_body_repeat
        ? 'when-body'
        : $switch_branch_repeat
            ? 'switch-branch'
            : undef;
    my $pending_generated_do_label = $when_body_repeat
        ? 'when-body'
        : $switch_branch_repeat
            ? 'switch-branch'
            : undef;

    for my $body_clause (@{$clause}[2 .. $#$clause]) {
        next unless ref($body_clause) eq 'ARRAY' && @$body_clause;
        my $keyword = $body_clause->[0];
        next unless defined($keyword) && !ref($keyword);

        if ($keyword eq 'spawn') {
            confess "Transaction '$tn': loop-contained repeat-body spawn cannot follow local do while generated spawns are pending; drain with same-body '(await_all done)' before spawning again\n"
                if $pending_loop_local_do_before_drain;
            # A repeat directly in a single while/until body ($loop_body_repeat),
            # or reached through deeper branch nesting ($deeper_nested_repeat),
            # supports the basic spawn + same-body '(await_all done)' (or
            # single-pending '(await_any done)') subset. The mandatory drain is
            # enforced at the end of this routine; multi-pending '(await_any)' in
            # these contexts is deferred at the await_any site below.
            if (!($top_level_repeat || $when_body_repeat || $switch_branch_repeat || $loop_body_repeat || $deeper_nested_repeat)) {
                confess "Transaction '$tn': loop-contained repeat-body spawn remains deferred\n"
                    if _repeat_body_context_is_loop_contained($context_depths);
                confess "Transaction '$tn': deeper-nested repeat-body spawn remains deferred\n"
                    if _repeat_body_context_is_deeper_nested($label, $context_depths);
                confess "Transaction '$tn': repeat-body spawn is supported only for top-level repeat clauses, top-level when-body nested repeat clauses, or top-level switch-branch nested repeat clauses\n";
            }
            my $allowed_branch_spawn_after_prior_await_any_local_do_before_drain =
                ($when_body_repeat || $switch_branch_repeat)
                && $awaiting_multi_pending_drain
                && $pending_local_do_before_drain
                && !$pending_generated_do_before_drain
                && @pending_spawns;
            my $allowed_branch_spawn_after_prior_await_any_generated_child_do_before_drain =
                ($when_body_repeat || $switch_branch_repeat)
                && $awaiting_multi_pending_drain
                && !$pending_local_do_before_drain
                && $pending_generated_do_before_drain
                && (($pending_generated_do_kind_before_drain // '') eq 'generated-child do'
                    || ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params'
                    || ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params and bindings'
                    || ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params and same-domain metadata')
                && @pending_spawns;
            confess "Transaction '$tn': repeat-body spawn cannot follow multi-pending await_any before same-body await_all drains outstanding children\n"
                if $awaiting_multi_pending_drain
                    && !$allowed_branch_spawn_after_prior_await_any_local_do_before_drain
                    && !$allowed_branch_spawn_after_prior_await_any_generated_child_do_before_drain;
            my $allowed_branch_spawn_after_local_do_before_drain =
                ($when_body_repeat || $switch_branch_repeat)
                && $pending_local_do_before_drain
                && !$pending_generated_do_before_drain
                && @pending_spawns;
            my $allowed_branch_spawn_after_generated_do_before_drain =
                ($when_body_repeat || $switch_branch_repeat)
                && !$pending_local_do_before_drain
                && $pending_generated_do_before_drain
                && (($pending_generated_do_kind_before_drain // '') eq 'generated-child do'
                    || ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params'
                    || ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params and bindings'
                    || ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params and same-domain metadata')
                && @pending_spawns;
            confess "Transaction '$tn': $pending_local_do_label nested repeat spawn cannot follow local do while generated spawns are pending; drain with same-body '(await_all done)' before spawning again\n"
                if defined $pending_local_do_label
                    && $pending_local_do_before_drain
                    && @pending_spawns
                    && !$allowed_branch_spawn_after_local_do_before_drain;
            confess "Transaction '$tn': $pending_generated_do_label nested repeat spawn cannot follow $pending_generated_do_kind_before_drain while generated spawns are pending; drain with same-body '(await_all done)' before spawning again\n"
                if defined $pending_generated_do_label
                    && $pending_generated_do_before_drain
                    && @pending_spawns
                    && !$allowed_branch_spawn_after_generated_do_before_drain;
            for my $subclause (@{$body_clause}[4 .. $#$body_clause]) {
                confess "Transaction '$tn': repeat-body spawn subclauses must be '(params ...)', '(bind ...)', or '(domain ...)' in the spawn domain subset\n"
                    unless ref($subclause) eq 'ARRAY'
                        && @$subclause
                        && defined($subclause->[0])
                        && !ref($subclause->[0])
                        && length($subclause->[0]);
                my $head = $subclause->[0];
                next if $head eq 'params' || $head eq 'bind' || $head eq 'domain';
                confess "Transaction '$tn': repeat-body spawn supports only optional '(params ...)', '(bind ...)', and '(domain ...)' subclauses in the spawn domain subset\n";
            }
            $spawn_after_local_do_before_drain = 1
                if $allowed_branch_spawn_after_local_do_before_drain;
            if ($allowed_branch_spawn_after_generated_do_before_drain) {
                $spawn_after_generated_do_before_drain = 1;
                $spawn_after_generated_do_kind_before_drain = $pending_generated_do_kind_before_drain;
            }
            push @pending_spawns, $body_clause->[3];
            next;
        }

        if ($keyword eq 'do') {
            my $uses_generated_params = _repeat_body_do_uses_generated_params($body_clause);
            my $uses_bindings = _repeat_body_do_uses_bindings($body_clause);
            my $uses_domain = _repeat_body_do_uses_domain($body_clause);
            my $target = $body_clause->[1];
            my $generated_do = _repeat_body_do_is_generated_activation($body_clause, $target, $generated_children);
            # A repeat directly inside a single while/until body ($loop_body_repeat),
            # or reached through deeper branch nesting ($deeper_nested_repeat:
            # when+ -> repeat, switch -> when+ -> repeat), runs both a plain local
            # (do child) and a same-domain generated (do child (params ...)) [+
            # (bind ...)/(domain NAME)] do. Cross-domain generated do and spawn
            # stay deferred (handled by the cross-domain check below / the spawn
            # branch). A repeat reached through a loop ancestor (loop-contained)
            # routes through the loop-contained deferral. ($deeper_nested_repeat
            # is computed once at function scope.)
            if (!($top_level_repeat || $when_body_repeat || $switch_branch_repeat || $loop_body_repeat || $while_then_when_repeat)) {
                confess "Transaction '$tn': loop-contained repeat-body do remains deferred\n"
                    if _repeat_body_context_is_loop_contained($context_depths);
                confess "Transaction '$tn': repeat-body do is supported only for top-level repeat clauses, top-level when-body nested repeat clauses, or top-level switch-branch nested repeat clauses\n"
                    unless $deeper_nested_repeat;
            }
            for my $subclause (@{$body_clause}[2 .. $#$body_clause]) {
                confess "Transaction '$tn': repeat-body generated do supports only static '(params ...)', '(bind ...)', and '(domain ...)' in the generated blocking-do subset\n"
                    unless ref($subclause) eq 'ARRAY'
                        && @$subclause
                        && defined($subclause->[0])
                        && !ref($subclause->[0])
                        && ($subclause->[0] eq 'params' || $subclause->[0] eq 'bind' || $subclause->[0] eq 'domain');
            }
            my $nested_do_label = $when_body_repeat ? 'when-body' : $switch_branch_repeat ? 'switch-branch' : undef;
            if ($uses_domain
                    && _repeat_body_do_is_cross_domain_attempt($actor, $tn, $target)) {
                my $context_label = $when_body_repeat
                    ? 'when-body nested repeat'
                    : $switch_branch_repeat
                        ? 'switch-branch nested repeat'
                        : 'repeat-body';
                confess "Transaction '$tn': $context_label generated do target '$target' is in a different clock domain than the calling transaction; cross-domain repeat-body do remains deferred\n";
            }
            if ($when_body_repeat) {
                confess "Transaction '$tn': when-body nested repeat generated do bindings require static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                    if $uses_bindings && !$uses_generated_params;
                confess "Transaction '$tn': when-body nested repeat generated do domain metadata requires static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                    if $uses_domain && !$uses_generated_params;
            } elsif ($switch_branch_repeat) {
                confess "Transaction '$tn': switch-branch nested repeat generated do bindings require static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                    if $uses_bindings && !$uses_generated_params;
                confess "Transaction '$tn': switch-branch nested repeat generated do domain metadata requires static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                    if $uses_domain && !$uses_generated_params;
            }
            confess "Transaction '$tn': repeat-body generated do bindings require static '(params ...)' overrides in the current generated blocking-do subset\n"
                if ($top_level_repeat || $loop_body_repeat || $deeper_nested_repeat) && $uses_bindings && !$uses_generated_params;
            confess "Transaction '$tn': repeat-body generated do domain metadata requires static '(params ...)' overrides in the current generated blocking-do subset\n"
                if ($top_level_repeat || $loop_body_repeat || $deeper_nested_repeat) && $uses_domain && !$uses_generated_params;
            confess "Transaction '$tn': while-then-when repeat-body do supports only plain local '(do child)' in the current loop-plus-branch subset\n"
                if $while_then_when_repeat
                    && ($uses_generated_params || $uses_bindings || $uses_domain || $generated_do);
            if (@pending_spawns) {
                my $plain_local_do = !$uses_generated_params && !$uses_bindings && !$uses_domain && !$generated_do;
                my $plain_generated_child_do = !$uses_generated_params && !$uses_bindings && !$uses_domain && $generated_do;
                my $static_parameter_generated_do = $uses_generated_params && !$uses_bindings && !$uses_domain && $generated_do;
                my $static_bound_generated_do = $uses_generated_params && $uses_bindings && !$uses_domain && $generated_do;
                my $static_domain_generated_do = $uses_generated_params && $uses_domain && $generated_do;
                my $allowed_static_parameter_generated_do = defined($pending_generated_do_label) && $static_parameter_generated_do;
                my $allowed_static_bound_generated_do = defined($pending_generated_do_label) && $static_bound_generated_do;
                my $allowed_static_domain_generated_do = ($when_body_repeat || $switch_branch_repeat) && $static_domain_generated_do;
                my $allowed_local_do_after_multi_pending_await_any =
                    ($when_body_repeat || $switch_branch_repeat)
                    && $plain_local_do
                    && $awaiting_multi_pending_drain;
                my $allowed_generated_child_do_after_multi_pending_await_any =
                    ($when_body_repeat || $switch_branch_repeat)
                    && $plain_generated_child_do
                    && $awaiting_multi_pending_drain;
                my $allowed_static_parameter_generated_do_after_multi_pending_await_any =
                    ($when_body_repeat || $switch_branch_repeat)
                    && $static_parameter_generated_do
                    && $awaiting_multi_pending_drain;
                my $allowed_static_bound_generated_do_after_multi_pending_await_any =
                    ($when_body_repeat || $switch_branch_repeat)
                    && $static_bound_generated_do
                    && $awaiting_multi_pending_drain;
                my $allowed_static_domain_generated_do_after_multi_pending_await_any =
                    ($when_body_repeat || $switch_branch_repeat)
                    && $static_domain_generated_do
                    && $awaiting_multi_pending_drain;
                my $pending_spawn_local_do_loop_kind =
                    $label eq 'while body' ? 'while' :
                    $label eq 'until body' ? 'until' :
                    undef;
                my $loop_pending_spawn_count = scalar @pending_spawns;
                my $selected_loop_multi_pending_local_do =
                    defined($pending_spawn_local_do_loop_kind)
                    && ($pending_spawn_local_do_loop_kind eq 'while' || $pending_spawn_local_do_loop_kind eq 'until')
                    && $loop_pending_spawn_count > 1;
                my $allowed_loop_pending_spawn_local_do =
                    $loop_body_repeat
                    && defined($pending_spawn_local_do_loop_kind)
                    && $plain_local_do
                    && ($loop_pending_spawn_count == 1 || $selected_loop_multi_pending_local_do)
                    && !$awaiting_multi_pending_drain
                    && !$pending_loop_local_do_before_drain
                    && _control_flow_effects_prove_loop_repeat_pending_spawn_local_do_drain(
                        $actor,
                        $tn,
                        $pending_spawn_local_do_loop_kind,
                        \@pending_spawns,
                        $target,
                        {
                            allow_single_pending_await_any => $loop_pending_spawn_count == 1,
                        },
                    );
                my $allowed_pending_do = $plain_local_do
                    || (defined $pending_generated_do_label && $plain_generated_child_do)
                    || $allowed_static_parameter_generated_do
                    || $allowed_static_bound_generated_do
                    || $allowed_static_domain_generated_do;
                my $supported_pending_do = ($when_body_repeat || $switch_branch_repeat)
                    ? "local plain '(do child)', plain generated-child '(do child)', static generated '(do child (params ...))', static bound generated '(do child (params ...) (bind ...))', or static same-domain generated '(do child (params ...) [(bind ...)] (domain ...))'"
                    : defined($pending_generated_do_label)
                        ? "local plain '(do child)', plain generated-child '(do child)', static generated '(do child (params ...))', or static bound generated '(do child (params ...) (bind ...))'"
                    : "local plain '(do child)'";
                confess "Transaction '$tn': $pending_local_do_label nested repeat local do while generated spawns are pending is supported only before a later same-body '(await_all done)' drain, with no prior multi-pending await_any observation\n"
                    if defined $pending_local_do_label
                        && $plain_local_do
                        && $awaiting_multi_pending_drain
                        && !$allowed_local_do_after_multi_pending_await_any;
                confess "Transaction '$tn': $pending_generated_do_label nested repeat generated-child do while generated spawns are pending is supported only before a later same-body '(await_all done)' drain, with no prior multi-pending await_any observation\n"
                    if defined $pending_generated_do_label
                        && $plain_generated_child_do
                        && $awaiting_multi_pending_drain
                        && !$allowed_generated_child_do_after_multi_pending_await_any;
                confess "Transaction '$tn': $pending_generated_do_label nested repeat generated do with static params while generated spawns are pending is supported only before a later same-body '(await_all done)' drain, with no prior multi-pending await_any observation\n"
                    if $allowed_static_parameter_generated_do
                        && $awaiting_multi_pending_drain
                        && !$allowed_static_parameter_generated_do_after_multi_pending_await_any;
                confess "Transaction '$tn': $pending_generated_do_label nested repeat generated do with static params and bindings while generated spawns are pending is supported only before a later same-body '(await_all done)' drain, with no prior multi-pending await_any observation\n"
                    if $allowed_static_bound_generated_do
                        && $awaiting_multi_pending_drain
                        && !$allowed_static_bound_generated_do_after_multi_pending_await_any;
                confess "Transaction '$tn': $pending_generated_do_label nested repeat generated do with static params and same-domain metadata while generated spawns are pending is supported only before a later same-body '(await_all done)' drain, with no prior multi-pending await_any observation\n"
                    if $allowed_static_domain_generated_do
                        && $awaiting_multi_pending_drain
                        && !$allowed_static_domain_generated_do_after_multi_pending_await_any;
                confess "Transaction '$tn': $pending_generated_do_label nested repeat do while generated spawns are pending supports only $supported_pending_do in the current subset\n"
                    if defined $pending_generated_do_label && !$awaiting_multi_pending_drain && !$allowed_pending_do;
                confess "Transaction '$tn': $pending_local_do_label nested repeat do while generated spawns are pending supports only local plain '(do child)' in the current subset\n"
                    if !defined $pending_generated_do_label && defined $pending_local_do_label && !$awaiting_multi_pending_drain && !$allowed_pending_do;
                my $allowed_branch_pending_do =
                    defined($pending_local_do_label)
                    && $allowed_pending_do
                    && (!$awaiting_multi_pending_drain
                        || $allowed_local_do_after_multi_pending_await_any
                        || $allowed_generated_child_do_after_multi_pending_await_any
                        || $allowed_static_parameter_generated_do_after_multi_pending_await_any
                        || $allowed_static_bound_generated_do_after_multi_pending_await_any
                        || $allowed_static_domain_generated_do_after_multi_pending_await_any);
                confess "Transaction '$tn': repeat-body do cannot appear while repeat-body spawn clauses are pending; wait for spawned children before blocking do\n"
                    unless $allowed_branch_pending_do || $allowed_loop_pending_spawn_local_do;
                if ($allowed_loop_pending_spawn_local_do) {
                    $pending_loop_local_do_before_drain = 1;
                } else {
                    $pending_local_do_before_drain = 1 if $plain_local_do;
                }
                if ($plain_generated_child_do || $allowed_static_parameter_generated_do || $allowed_static_bound_generated_do || $allowed_static_domain_generated_do) {
                    $pending_generated_do_before_drain = 1;
                    $pending_generated_do_kind_before_drain = $plain_generated_child_do
                        ? 'generated-child do'
                        : $allowed_static_domain_generated_do
                            ? 'generated do with static params and same-domain metadata'
                            : $allowed_static_bound_generated_do
                                ? 'generated do with static params and bindings'
                                : 'generated do with static params';
                }
            }
            next;
        }

        if ($keyword eq 'await_all' || $keyword eq 'await_any') {
            confess "Transaction '$tn': repeat-body $keyword is supported only after repeat-body spawn clauses\n"
                unless @pending_spawns;
            my $selected_loop_local_do_before_post_await_any =
                $pending_loop_local_do_before_drain
                && (($label eq 'while body'
                        && _context_depths_match_exactly($context_depths, { while => 1 })
                        && @pending_spawns > 1)
                    || ($label eq 'until body'
                        && _context_depths_match_exactly($context_depths, { until => 1 })
                        && @pending_spawns > 1))
                && $keyword eq 'await_any'
                && !$awaiting_multi_pending_drain;
            confess "Transaction '$tn': loop-contained repeat-body local do while generated spawns are pending requires same-body '(await_all done)' drain; '(await_any done)' after the do remains deferred\n"
                if $pending_loop_local_do_before_drain
                    && $keyword eq 'await_any'
                    && @pending_spawns != 1
                    && !$selected_loop_local_do_before_post_await_any;
            my $allowed_local_spawn_after_do_before_post_await_any =
                defined($pending_local_do_label)
                && $spawn_after_local_do_before_drain
                && $keyword eq 'await_any'
                && @pending_spawns > 1
                && (!$awaiting_multi_pending_drain || ($pending_local_do_before_drain && !$pending_generated_do_before_drain));
            confess "Transaction '$tn': $pending_local_do_label nested repeat spawn after local do while generated spawns are pending requires same-body '(await_all done)' drain; '(await_any done)' after the later spawn remains deferred\n"
                if defined $pending_local_do_label
                    && $spawn_after_local_do_before_drain
                    && $keyword eq 'await_any'
                    && !$allowed_local_spawn_after_do_before_post_await_any;
            my $allowed_generated_do_spawn_after_do_before_post_await_any =
                defined($pending_generated_do_label)
                && $spawn_after_generated_do_before_drain
                && (($spawn_after_generated_do_kind_before_drain // '') eq 'generated-child do'
                    || ($spawn_after_generated_do_kind_before_drain // '') eq 'generated do with static params'
                    || ($spawn_after_generated_do_kind_before_drain // '') eq 'generated do with static params and bindings'
                    || ($spawn_after_generated_do_kind_before_drain // '') eq 'generated do with static params and same-domain metadata')
                && $keyword eq 'await_any'
                && @pending_spawns > 1
                && (!$awaiting_multi_pending_drain
                    || ((($spawn_after_generated_do_kind_before_drain // '') eq 'generated-child do'
                            || ($spawn_after_generated_do_kind_before_drain // '') eq 'generated do with static params'
                            || ($spawn_after_generated_do_kind_before_drain // '') eq 'generated do with static params and bindings'
                            || ($spawn_after_generated_do_kind_before_drain // '') eq 'generated do with static params and same-domain metadata')
                        && $pending_generated_do_before_drain
                        && !$pending_local_do_before_drain));
            confess "Transaction '$tn': $pending_generated_do_label nested repeat spawn after $spawn_after_generated_do_kind_before_drain while generated spawns are pending requires same-body '(await_all done)' drain; '(await_any done)' after the later spawn remains deferred\n"
                if defined $pending_generated_do_label
                    && $spawn_after_generated_do_before_drain
                    && $keyword eq 'await_any'
                    && !$allowed_generated_do_spawn_after_do_before_post_await_any;
            my $allowed_branch_local_do_before_post_await_any =
                ($when_body_repeat || $switch_branch_repeat)
                && $pending_local_do_before_drain
                && !$pending_generated_do_before_drain
                && $keyword eq 'await_any'
                && @pending_spawns > 1
                && !$awaiting_multi_pending_drain;
            my $allowed_branch_generated_child_do_before_post_await_any =
                ($when_body_repeat || $switch_branch_repeat)
                && !$pending_local_do_before_drain
                && $pending_generated_do_before_drain
                && ($pending_generated_do_kind_before_drain // '') eq 'generated-child do'
                && $keyword eq 'await_any'
                && @pending_spawns > 1
                && !$awaiting_multi_pending_drain;
            my $allowed_branch_static_parameter_generated_do_before_post_await_any =
                ($when_body_repeat || $switch_branch_repeat)
                && !$pending_local_do_before_drain
                && $pending_generated_do_before_drain
                && ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params'
                && $keyword eq 'await_any'
                && @pending_spawns > 1
                && !$awaiting_multi_pending_drain;
            my $allowed_branch_static_bound_generated_do_before_post_await_any =
                ($when_body_repeat || $switch_branch_repeat)
                && !$pending_local_do_before_drain
                && $pending_generated_do_before_drain
                && ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params and bindings'
                && $keyword eq 'await_any'
                && @pending_spawns > 1
                && !$awaiting_multi_pending_drain;
            my $allowed_branch_static_domain_generated_do_before_post_await_any =
                ($when_body_repeat || $switch_branch_repeat)
                && !$pending_local_do_before_drain
                && $pending_generated_do_before_drain
                && ($pending_generated_do_kind_before_drain // '') eq 'generated do with static params and same-domain metadata'
                && $keyword eq 'await_any'
                && @pending_spawns > 1
                && !$awaiting_multi_pending_drain;
            confess "Transaction '$tn': $pending_local_do_label nested repeat local do while generated spawns are pending requires same-body '(await_all done)' drain; '(await_any done)' after the do remains deferred\n"
                if defined $pending_local_do_label
                    && $pending_local_do_before_drain
                    && $keyword eq 'await_any'
                    && !$allowed_branch_local_do_before_post_await_any
                    && !$allowed_local_spawn_after_do_before_post_await_any;
            confess "Transaction '$tn': $pending_generated_do_label nested repeat $pending_generated_do_kind_before_drain while generated spawns are pending requires same-body '(await_all done)' drain; '(await_any done)' after the do remains deferred\n"
                if defined $pending_generated_do_label
                    && $pending_generated_do_before_drain
                    && $keyword eq 'await_any'
                    && !$allowed_branch_generated_child_do_before_post_await_any
                    && !$allowed_branch_static_parameter_generated_do_before_post_await_any
                    && !$allowed_branch_static_bound_generated_do_before_post_await_any
                    && !$allowed_branch_static_domain_generated_do_before_post_await_any
                    && !$allowed_generated_do_spawn_after_do_before_post_await_any;
            if ($keyword eq 'await_any' && @pending_spawns > 1) {
                # A multi-pending (await_any done) is an observation point; the
                # outstanding children must still be drained by a later same-body
                # (await_all done) before the repeat check loops. This is allowed
                # at top-level / when-body / switch-branch and now also in
                # loop-contained / deeper-nested repeats; the end-of-routine
                # drain-requirement rejects the undrained case (@pending_spawns
                # still non-empty at the repeat end).
                $awaiting_multi_pending_drain = 1;
                next;
            }
            @pending_spawns = ();
            $awaiting_multi_pending_drain = 0;
            $pending_local_do_before_drain = 0;
            $pending_generated_do_before_drain = 0;
            $pending_generated_do_kind_before_drain = undef;
            $spawn_after_local_do_before_drain = 0;
            $spawn_after_generated_do_before_drain = 0;
            $spawn_after_generated_do_kind_before_drain = undef;
            $pending_loop_local_do_before_drain = 0;
            next;
        }
    }

    confess "Transaction '$tn': loop-contained repeat-body local do while generated spawns are pending requires later same-body '(await_all done)' before the repeat check can loop\n"
        if $pending_loop_local_do_before_drain && @pending_spawns;
    confess "Transaction '$tn': $pending_local_do_label nested repeat local do while generated spawns are pending requires later same-body '(await_all done)' before the nested repeat check can loop\n"
        if defined $pending_local_do_label && $pending_local_do_before_drain && @pending_spawns;
    confess "Transaction '$tn': $pending_generated_do_label nested repeat $pending_generated_do_kind_before_drain while generated spawns are pending requires later same-body '(await_all done)' before the nested repeat check can loop\n"
        if defined $pending_generated_do_label && $pending_generated_do_before_drain && @pending_spawns;
    confess "Transaction '$tn': when-body nested repeat multi-pending await_any requires later same-body '(await_all done)' before the nested repeat check can loop\n"
        if $when_body_repeat && $awaiting_multi_pending_drain;
    confess "Transaction '$tn': when-body nested repeat spawn requires same-body '(await_all done)' or single-pending '(await_any done)' before the nested repeat check can loop\n"
        if $when_body_repeat && @pending_spawns;
    confess "Transaction '$tn': switch-branch nested repeat multi-pending await_any requires later same-body '(await_all done)' before the nested repeat check can loop\n"
        if $switch_branch_repeat && $awaiting_multi_pending_drain;
    confess "Transaction '$tn': switch-branch nested repeat spawn requires same-body '(await_all done)' or single-pending '(await_any done)' before the nested repeat check can loop\n"
        if $switch_branch_repeat && @pending_spawns;
    confess "Transaction '$tn': repeat-body multi-pending await_any cannot be drained by parent-body '$parent_exit_sync_after_repeat->{form}' after the repeat exits; use same-body '(await_all done)' before the repeat check can loop\n"
        if $top_level_repeat && $awaiting_multi_pending_drain && $parent_exit_sync_after_repeat;
    confess "Transaction '$tn': repeat-body multi-pending await_any requires later same-body '(await_all done)' before the repeat check can loop\n"
        if $top_level_repeat && $awaiting_multi_pending_drain;
    confess "Transaction '$tn': repeat-body spawn cannot be drained by parent-body '$parent_exit_sync_after_repeat->{form}' after the repeat exits; use same-body '(await_all done)' before the repeat check can loop\n"
        if $top_level_repeat && @pending_spawns && $parent_exit_sync_after_repeat;
    confess "Transaction '$tn': repeat-body spawn requires same-body '(await_all done)' before the repeat check can loop\n"
        if $top_level_repeat && @pending_spawns;
    confess "Transaction '$tn': loop-contained repeat-body multi-pending await_any requires later same-body '(await_all done)' before the repeat check can loop\n"
        if $loop_body_repeat && $awaiting_multi_pending_drain;
    confess "Transaction '$tn': loop-contained repeat-body spawn requires same-body '(await_all done)' or single-pending '(await_any done)' before the repeat check can loop\n"
        if $loop_body_repeat && @pending_spawns;
    confess "Transaction '$tn': deeper-nested repeat-body multi-pending await_any requires later same-body '(await_all done)' before the repeat check can loop\n"
        if $deeper_nested_repeat && $awaiting_multi_pending_drain;
    confess "Transaction '$tn': deeper-nested repeat-body spawn requires same-body '(await_all done)' or single-pending '(await_any done)' before the repeat check can loop\n"
        if $deeper_nested_repeat && @pending_spawns;

    return 1;
}

sub _validate_repeat_body_do_subset {
    my ($ref, $actor) = @_;
    return 1 unless ref($ref) eq 'HASH'
        && ($ref->{keyword} // '') eq 'do'
        && ($ref->{label} // '') eq 'repeat body';

    my $tn = $ref->{tx_name};
    my $clause = $ref->{clause};
    my $target = $ref->{target};
    if (my $nested_do_label = _nested_repeat_local_do_label($ref->{repeat_parent_label})) {
        my @subclauses = ref($clause) eq 'ARRAY' ? @{$clause}[2 .. $#$clause] : ();
        my $uses_generated_params = _repeat_body_do_uses_generated_params($clause);
        my $uses_bindings = _repeat_body_do_uses_bindings($clause);
        my $uses_domain = _repeat_body_do_uses_domain($clause);

        if ($uses_domain && _repeat_body_do_is_cross_domain_attempt($actor, $tn, $target)) {
            my $context_label = $nested_do_label eq 'when-body'
                ? 'when-body nested repeat'
                : 'switch-branch nested repeat';
            confess "Transaction '$tn': $context_label generated do target '$target' is in a different clock domain than the calling transaction; cross-domain repeat-body do remains deferred\n";
        }

        if ($nested_do_label eq 'when-body') {
            for my $subclause (@subclauses) {
                confess "Transaction '$tn': when-body nested repeat do supports only plain '(do child)', static '(do child (params ...))', static bound '(do child (params ...) (bind ...))', or static same-domain '(do child (params ...) [(bind ...)] (domain ...))' in the current nested generated blocking-do subset\n"
                    unless ref($subclause) eq 'ARRAY'
                        && @$subclause
                        && defined($subclause->[0])
                        && !ref($subclause->[0])
                        && ($subclause->[0] eq 'params' || $subclause->[0] eq 'bind' || $subclause->[0] eq 'domain');
            }
            confess "Transaction '$tn': when-body nested repeat generated do bindings require static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                if $uses_bindings && !$uses_generated_params;
            confess "Transaction '$tn': when-body nested repeat generated do domain metadata requires static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                if $uses_domain && !$uses_generated_params;
        } elsif ($nested_do_label eq 'switch-branch') {
            for my $subclause (@subclauses) {
                confess "Transaction '$tn': switch-branch nested repeat do supports only plain '(do child)', static '(do child (params ...))', static bound '(do child (params ...) (bind ...))', or static same-domain '(do child (params ...) [(bind ...)] (domain ...))' in the current nested generated blocking-do subset\n"
                    unless ref($subclause) eq 'ARRAY'
                        && @$subclause
                        && defined($subclause->[0])
                        && !ref($subclause->[0])
                        && ($subclause->[0] eq 'params' || $subclause->[0] eq 'bind' || $subclause->[0] eq 'domain');
            }
            confess "Transaction '$tn': switch-branch nested repeat generated do bindings require static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                if $uses_bindings && !$uses_generated_params;
            confess "Transaction '$tn': switch-branch nested repeat generated do domain metadata requires static '(params ...)' overrides in the current nested generated blocking-do subset\n"
                if $uses_domain && !$uses_generated_params;
        }
        return 1;
    }

    my @subclauses = ref($clause) eq 'ARRAY' ? @{$clause}[2 .. $#$clause] : ();
    my $uses_generated_params = _repeat_body_do_uses_generated_params($clause);
    my $uses_bindings = _repeat_body_do_uses_bindings($clause);
    my $uses_domain = _repeat_body_do_uses_domain($clause);

    for my $subclause (@subclauses) {
        confess "Transaction '$tn': repeat-body generated do supports only static '(params ...)', '(bind ...)', and '(domain ...)' in the generated blocking-do subset\n"
            unless ref($subclause) eq 'ARRAY'
                && @$subclause
                && defined($subclause->[0])
                && !ref($subclause->[0])
                && ($subclause->[0] eq 'params' || $subclause->[0] eq 'bind' || $subclause->[0] eq 'domain');
    }

    if ($uses_domain && _repeat_body_do_is_cross_domain_attempt($actor, $tn, $target)) {
        confess "Transaction '$tn': repeat-body generated do target '$target' is in a different clock domain than the calling transaction; cross-domain repeat-body do remains deferred\n";
    }

    confess "Transaction '$tn': repeat-body generated do bindings require static '(params ...)' overrides in the current generated blocking-do subset\n"
        if $uses_bindings && !$uses_generated_params;
    confess "Transaction '$tn': repeat-body generated do domain metadata requires static '(params ...)' overrides in the current generated blocking-do subset\n"
        if $uses_domain && !$uses_generated_params;

    return 1;
}

sub _nested_repeat_local_do_label {
    my ($repeat_parent_label) = @_;
    return 'when-body'     if ($repeat_parent_label // '') eq 'when body';
    return 'switch-branch' if ($repeat_parent_label // '') eq 'switch branch';
    return undef;
}

sub _context_depths_match_exactly {
    my ($context_depths, $expected_depths) = @_;
    $context_depths ||= {};
    $expected_depths ||= {};

    my %names = map { $_ => 1 } (keys %$context_depths, keys %$expected_depths);
    for my $name (keys %names) {
        return 0 unless ($context_depths->{$name} // 0) == ($expected_depths->{$name} // 0);
    }

    return 1;
}

sub _repeat_body_context_is_loop_contained {
    my ($context_depths) = @_;
    return 0 unless ref($context_depths) eq 'HASH';
    return 1 if ($context_depths->{while} // 0) > 0;
    return 1 if ($context_depths->{until} // 0) > 0;
    return 0;
}

sub _repeat_body_context_is_deeper_nested {
    my ($label, $context_depths) = @_;
    return 0 unless defined($label);
    return 0 unless ref($context_depths) eq 'HASH';
    return 0 if _repeat_body_context_is_loop_contained($context_depths);
    my $when_depth = $context_depths->{when} // 0;
    my $switch_depth = $context_depths->{switch} // 0;
    if ($label eq 'when body') {
        return 1 if $when_depth > 1;
        return 1 if $switch_depth >= 1;
        return 0;
    }
    if ($label eq 'switch branch') {
        return 1 if $switch_depth > 1;
        return 1 if $when_depth >= 1;
        return 0;
    }
    return 0;
}

sub _repeat_body_context_is_while_then_when {
    my ($label, $context_depths) = @_;
    return 0 unless defined($label) && $label eq 'when body';
    return _context_depths_match_exactly($context_depths, { while => 1, when => 1 }) ? 1 : 0;
}

sub _validate_loop_clause {
    my ($clause, $tn, $label, $kind) = @_;

    confess "Transaction '$tn': $kind requires '($kind condition body...)' in $label\n"
        unless @$clause >= 3
            && defined($clause->[1])
            && (
                (ref($clause->[1]) eq 'ARRAY' && @{$clause->[1]})
                || (!ref($clause->[1]) && length($clause->[1]))
            );

    for my $body_clause (@{$clause}[2 .. $#$clause]) {
        confess "Transaction '$tn': $kind body clauses must be non-empty list forms in $label\n"
            unless ref($body_clause) eq 'ARRAY' && @$body_clause;
    }

    return 1;
}

sub _validate_wait_clause {
    my ($clause, $tn, $label, $actor) = @_;

    _confess_wait_requires($tn, $label)
        unless @$clause == 2
            && defined($clause->[1]);

    if (defined $actor) {
        _wait_cycles($clause, $tn, $label, $actor);
    } else {
        my $count = $clause->[1];
        if (ref($count)) {
            _confess_wait_requires($tn, $label)
                unless _is_wait_expression_shape($count);
        } else {
            _confess_wait_requires($tn, $label)
                unless defined(_non_negative_integer_from_literal($count))
                    || _is_hdl_identifier($count)
                    || _is_package_constant_reference_shape($count);
        }
    }

    return 1;
}

sub _wait_cycles {
    my ($clause, $tn, $label, $actor, $widths) = @_;

    my $spec = _wait_count_spec($clause, $tn, $label, $actor, $widths, 0);
    return $spec->{cycles};
}

sub _wait_count_spec {
    my ($clause, $tn, $label, $actor, $widths, $allow_dynamic) = @_;

    _confess_wait_requires($tn, $label)
        unless @$clause == 2
            && defined($clause->[1]);

    my $count = $clause->[1];
    if (!ref($count)) {
        my $literal_value = _non_negative_integer_from_literal($count);
        return {
            kind   => 'static',
            cycles => $literal_value,
            source => $count,
        } if defined $literal_value;

        if (my $package_constant = _actor_package_constant_reference($actor, $count)) {
            my ($package_name, $constant_name, $suffix) = @$package_constant;
            my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
            if (defined $constant_payload) {
                confess "Transaction '$tn': wait count token '$count' is ambiguous: it matches local enum member '$count' and imported package constant '$count' in $label\n"
                    if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
                confess "Transaction '$tn': wait count package constant '$package_name.$constant_name' aggregate/member path '$count' remains deferred; wait counts accept only qualified package scalar constants in this slice\n"
                    if $suffix ne '';
                my $constant_value = _package_constant_scalar_value($constant_payload);
                my $integer_value = defined($constant_value) && !ref($constant_value)
                    ? _non_negative_integer_from_literal($constant_value)
                    : undef;
                confess "Transaction '$tn': wait count package constant '$package_name.$constant_name' must resolve to a non-negative integer scalar in $label\n"
                    unless defined $integer_value;
                return {
                    kind   => 'static',
                    cycles => $integer_value,
                    source => $count,
                };
            }

            confess "Transaction '$tn': wait count references unknown package constant '$count' in $label\n"
                if $suffix eq '' && !_actor_local_enum_member_exists($actor, $package_name, $constant_name);
        }

        if (_is_hdl_identifier($count)) {
            if (_transaction_param_by_name($actor, $tn, $count)) {
                my $param_value = _transaction_param_wait_count_value($count, $actor, $tn);
                confess "Transaction '$tn': wait count transaction parameter '$count' must resolve to a non-negative integer literal in $label\n"
                    unless defined $param_value;
                return {
                    kind   => 'static',
                    cycles => $param_value,
                    source => $count,
                };
            }

            my $constant = _actor_constant_by_name($actor, $count);
            if ($constant) {
                my $constant_value = _non_negative_integer_from_literal(_constant_resolved_value($constant));
                confess "Transaction '$tn': wait constant '$count' must resolve to a non-negative integer literal in $label\n"
                    unless defined $constant_value;
                return {
                    kind   => 'static',
                    cycles => $constant_value,
                    source => $count,
                };
            }

            my $param = _actor_param_by_name($actor, $count);
            if ($param) {
                my $param_value = _non_negative_integer_from_literal(_param_resolved_value($param));
                confess "Transaction '$tn': wait parameter '$count' must resolve to a non-negative integer literal in $label\n"
                    unless defined $param_value;
                return {
                    kind   => 'static',
                    cycles => $param_value,
                    source => $count,
                };
            }

            my $width = _dynamic_wait_source_width($count, $widths);
            if (defined $width) {
                confess "Transaction '$tn': runtime dynamic wait count '$count' is not supported in $label in the current dynamic-wait slice\n"
                    unless $allow_dynamic;
                return {
                    kind   => 'runtime_scalar',
                    source => $count,
                    width  => $width,
                };
            }

            confess "Transaction '$tn': wait count '$count' is neither a same-transaction scalar parameter, declared actor constant, actor parameter, qualified package scalar constant, nor a known-width runtime scalar in $label\n";
        }

        _confess_wait_requires($tn, $label);
    }

    if (_is_wait_expression_shape($count)) {
        my $source = _format_isf_expr($count);
        confess "Transaction '$tn': runtime dynamic wait count expression '$source' must use a supported expression operator shape in $label\n"
            unless _is_supported_wait_expression_shape($count);

        my $unknown_ref = _first_unknown_wait_expression_ref($count, $widths);
        confess "Transaction '$tn': runtime dynamic wait count expression '$source' references unknown-width signal '$unknown_ref' in $label\n"
            if defined $unknown_ref;

        my $width = _wait_expression_width($count, $widths);
        if (defined $width) {
            confess "Transaction '$tn': runtime dynamic wait count expression '$source' is not supported in $label in the current dynamic-wait slice\n"
                unless $allow_dynamic;
            return {
                kind   => 'runtime_expression',
                source => $source,
                width  => $width,
            };
        }

        confess "Transaction '$tn': runtime dynamic wait count expression '$source' must have a known positive width in $label\n";
    }

    _confess_wait_requires($tn, $label);
}

sub _confess_wait_requires {
    my ($tn, $label) = @_;
    confess "Transaction '$tn': wait requires '(wait non_negative_integer_literal_or_constant_or_actor_parameter_or_transaction_parameter_or_qualified_package_scalar_constant_or_known_width_runtime_scalar_or_expression)' in $label\n";
}

sub _is_wait_expression_shape {
    my ($count) = @_;
    return ref($count) eq 'ARRAY' && @$count;
}

sub _is_supported_wait_expression_shape {
    my ($expr) = @_;
    return 1 unless ref($expr);
    return 0 unless ref($expr) eq 'ARRAY' && @$expr;

    my $op = $expr->[0];
    return 0 unless defined($op) && !ref($op);

    my @operands = grep { defined($_) } @{$expr}[1 .. $#$expr];
    return 0 unless @operands == @$expr - 1;
    return 0 unless _wait_expression_operator_accepts_arity($op, scalar(@operands));

    for my $operand (@operands) {
        return 0 unless _is_supported_wait_expression_shape($operand);
    }

    return 1;
}

sub _wait_expression_operator_accepts_arity {
    my ($op, $arity) = @_;
    # This bounded count grammar must survive unchanged carrier serialization.
    # Do not admit logical/bitwise aliases that the carrier cannot parse.
    return $arity >= 2 if $op eq 'concat';
    return $arity == 1 if $op eq '!';
    return $arity == 2 if $op =~ /\A(?:<<|>>)\z/;
    return $arity >= 2 if $op =~ /\A(?:\+|-|\*|\/|%|&|\||\^|==|!=|<|<=|>|>=)\z/;
    return 0;
}

sub _dynamic_wait_source_width {
    my ($source, $widths) = @_;
    return undef unless defined($source) && !ref($source) && _is_hdl_identifier($source);
    return undef unless ref($widths) eq 'HASH';
    return undef unless exists($widths->{$source});

    my $width = $widths->{$source};
    return undef unless defined($width) && !ref($width) && $width =~ /\A[1-9][0-9]*\z/;
    return 0 + $width;
}

sub _first_unknown_wait_expression_ref {
    my ($expr, $widths) = @_;
    return undef unless ref($widths) eq 'HASH';

    my %seen;
    for my $ref (_activation_binding_expr_signals($expr)) {
        next if $seen{$ref}++;
        return $ref unless exists($widths->{$ref})
            && defined($widths->{$ref})
            && !ref($widths->{$ref})
            && $widths->{$ref} =~ /\A[1-9][0-9]*\z/;
    }

    return undef;
}

sub _wait_expression_width {
    my ($expr, $widths) = @_;
    return undef unless ref($widths) eq 'HASH';
    my $width = _activation_binding_expr_width($expr, $widths);
    return undef unless defined($width) && !ref($width) && $width =~ /\A[1-9][0-9]*\z/;
    return 0 + $width;
}

sub _actor_constant_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $constant (@{$actor->{constants} || []}) {
        next unless ref($constant) eq 'HASH';
        return $constant if ($constant->{name} // '') eq $name;
    }

    return undef;
}

sub _actor_param_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $param (@{$actor->{params} || []}) {
        next unless ref($param) eq 'HASH';
        return $param if ($param->{name} // '') eq $name;
    }

    return undef;
}

sub _actor_interface_signal_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $direction (qw(inputs outputs)) {
        for my $port (@{($actor->{interface} || {})->{$direction} || []}) {
            next unless ref($port) eq 'HASH';
            return $port if ($port->{name} // '') eq $name;
        }
    }

    return undef;
}

sub _non_negative_integer_from_literal {
    my ($literal) = @_;
    return undef unless defined($literal) && !ref($literal);

    my $integer = FSM::Package::IntegerLiteralSupport->integer_from_literal_like($literal);
    return undef unless defined $integer;
    return undef unless $integer->bcmp(0) >= 0;
    return 0 + $integer->bstr;
}

sub _validate_update_clause {
    my ($clause, $tn, $label, $keyword) = @_;
    $keyword //= 'update';

    confess "Transaction '$tn': $keyword requires '($keyword var expr)' in $label\n"
        unless @$clause == 3
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1])
            && defined($clause->[2]);

    return 1;
}

sub _validate_bank_access_clause {
    my ($clause, $tn, $label) = @_;
    my $keyword = $clause->[0];

    if ($keyword eq 'store') {
        confess "Transaction '$tn': store requires '(store <bank-name> <index> <value>)' in $label\n"
            unless @$clause == 4
                && defined($clause->[1])
                && !ref($clause->[1])
                && length($clause->[1])
                && defined($clause->[2])
                && !ref($clause->[2])
                && length($clause->[2])
                && defined($clause->[3]);
        return 1;
    }

    confess "Transaction '$tn': load requires '(load <bank-name> <index> as <target>)' in $label\n"
        unless @$clause == 5
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1])
            && defined($clause->[2])
            && !ref($clause->[2])
            && length($clause->[2])
            && defined($clause->[3])
            && !ref($clause->[3])
            && $clause->[3] eq 'as'
            && defined($clause->[4])
            && !ref($clause->[4])
            && length($clause->[4]);

    return 1;
}

sub _validate_complete_clause {
    my ($clause, $tn, $label) = @_;

    confess "Transaction '$tn': complete requires '(complete port)' in $label\n"
        unless @$clause == 2
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1]);

    return 1;
}

sub _validate_sample_clause {
    my ($clause, $tn, $label) = @_;

    confess "Transaction '$tn': sample requires '(sample port as name)' in $label\n"
        unless @$clause == 4
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1])
            && defined($clause->[2])
            && !ref($clause->[2])
            && $clause->[2] eq 'as'
            && defined($clause->[3])
            && !ref($clause->[3])
            && length($clause->[3]);

    return 1;
}

# --- Individual clause → IR ---
sub _sample_assignments {
    my ($samples) = @_;
    my @assignments;

    for my $sample (@$samples) {
        next unless ref($sample) eq 'ARRAY' && @$sample >= 4;
        next unless $sample->[0] eq 'sample' && $sample->[2] eq 'as';
        push @assignments, { lhs => $sample->[3], rhs => $sample->[1], op => '<=', source_kind => 'sample_capture' };
    }

    return @assignments;
}

sub _push_sample_state {
    my ($states, $tn, $pending_samples, $state_index_ref) = @_;
    return unless $pending_samples && @$pending_samples;
    my $index = $$state_index_ref;
    $$state_index_ref++;
    push @$states, _ir_sample_state($tn, [splice @$pending_samples], $index);
}

sub _inline_on_samples {
    my ($cl) = @_;
    my @samples;

    for my $j (2 .. $#$cl) {
        my $sample = $cl->[$j];
        next unless ref($sample) eq 'ARRAY' && $sample->[0] eq 'sample';
        push @samples, $sample;
    }

    return _sample_assignments(\@samples);
}

# The bare `as NAME` activation label of an `(on SIGNAL as NAME)` clause, or undef (ISF-TRIGGER-ANCHOR.5b).
sub _on_activation_label {
    my ($cl) = @_;
    for my $j (2 .. $#$cl) {
        return $cl->[$j + 1]
            if defined($cl->[$j]) && !ref($cl->[$j]) && $cl->[$j] eq 'as';
    }
    return undef;
}

sub _ir_on {
    my ($cl, $tn, $i, $point_bindings) = @_;
    my $event = $cl->[1];
    my $guard = _entry_activation_guard($event);
    my @assignments = map { +{ %$_, guard => $guard } } _inline_on_samples($cl);
    my $state_name = "${tn}_idle_$i";

    # ISF-TRIGGER-ANCHOR.5b: a bare `as NAME` activation label binds NAME to the entry/accept state,
    # so `(at NAME)` anchors a check there (shares the module-wide name -> state map with (point …)).
    my $label = _on_activation_label($cl);
    if (defined($label) && ref($point_bindings) eq 'HASH') {
        confess "Transaction '$tn': duplicate point/activation name '$label'\n"
            if exists $point_bindings->{$label};
        $point_bindings->{$label} = $state_name;
    }

    return {
        name        => $state_name,
        kind        => 'entry',
        guard       => $guard,
        assignments => \@assignments,
        transitions => [],
    };
}

sub _ir_when_activation {
    my ($cl, $tn, $i) = @_;
    for my $body_clause (@{$cl}[2 .. $#$cl]) {
        confess "Transaction '$tn': when activation body supports only '(sample port as name)' clauses; "
            . "put actions after the entry guard or use '(on PORT)' followed by a branching '(when ...)'\n"
            unless ref($body_clause) eq 'ARRAY' && @$body_clause
                && defined($body_clause->[0]) && !ref($body_clause->[0])
                && $body_clause->[0] eq 'sample';
    }
    my $event = $cl->[1];
    my $guard = _entry_activation_guard($event);
    my @assignments = map { +{ %$_, guard => $guard } } _inline_on_samples($cl);

    return {
        name        => "${tn}_idle_$i",
        kind        => 'entry',
        guard       => $guard,
        assignments => \@assignments,
        transitions => [],
    };
}
sub _entry_activation_guard {
    my ($event) = @_;
    return { port => $event } unless ref($event);
    return {
        expr     => _format_isf_expr($event),
        expr_ast => _clone_isf_value($event),
    };
}
sub _ir_data_op  { my ($op,$cl,$tn,$i,$widths,$actor)=@_; $op eq'shift_left' ? _ir_shift_left($cl,$tn,$i,$widths,$actor) : $op eq'shift_right' ? _ir_shift_right($cl,$tn,$i,$widths,$actor) : $op eq'assemble' ? _ir_assemble($cl,$tn,$i,$actor) : $op eq'extract' ? _ir_extract($cl,$tn,$i,$widths,$actor) : _ir_update($cl,$tn,$i,$op) }
sub _ir_named_drive_call {
    my ($cl, $tn, $i, $def, $pending_samples) = @_;
    my $name = $cl->[1];
    my @params = @{$def->{params}};
    my @actuals = @{$cl}[2 .. $#$cl];
    my @assignments = (
        _sample_assignments($pending_samples || []),
        { lhs => "${name}_start", rhs => 1, op => '=', source_kind => 'drive_call_start' },
    );

    confess "Transaction '$tn': drive '$name' expects " . scalar(@params) . " actual(s), got " . scalar(@actuals) . "\n"
        if @actuals > @params;

    for my $pi (0 .. $#params) {
        my $arg = $actuals[$pi];
        confess "Transaction '$tn': drive '$name' missing actual for '$params[$pi]'\n"
            unless defined $arg;
        push @assignments, { lhs => "${name}_$params[$pi]", rhs => _format_isf_expr($arg), op => '=', source_kind => 'drive_call_param' };
    }

    return {
        name        => "${tn}_drive_$i",
        kind        => 'sequential',
        assignments => \@assignments,
        transitions => [],
    };
}
sub _ir_drive   { my ($cl,$tn,$ps,$i)=@_; my @a; for(@$ps){push @a,{lhs=>$_->[3],rhs=>$_->[1],op=>'<=',source_kind=>'sample_capture'}} my$first=(ref($cl->[1])eq'ARRAY')?1:2; for my $j($first..$#$cl){my$x=$cl->[$j];next unless ref($x)eq'ARRAY'&&@$x>=2;push @a,{lhs=>$x->[0],rhs=>_format_isf_expr($x->[1]),op=>'=',source_kind=>'inline_drive'}} {name=>"${tn}_drive_$i",kind=>'sequential',assignments=>\@a,transitions=>[]} }
sub _ir_drive_call { my ($body,$tn,$ps,$i)=@_; return undef; }

sub _is_inline_drive_clause {
    my ($cl) = @_;
    return 0 unless ref($cl) eq 'ARRAY' && @$cl >= 2;
    my $first = (ref($cl->[1]) eq 'ARRAY') ? 1 : 2;
    return 0 if $first > $#$cl;
    for my $entry (@{$cl}[$first .. $#$cl]) {
        return 1 if ref($entry) eq 'ARRAY' && @$entry >= 2;
    }
    return 0;
}

sub _ir_transaction_drive_clause {
    my ($cl, $tn, $state_index, $drives, $pending_samples) = @_;
    my $name = $cl->[1];
    if (!ref($name) && ($drives || {})->{$name}) {
        return _ir_named_drive_call($cl, $tn, $state_index, $drives->{$name}, $pending_samples);
    }
    confess "Transaction '$tn': drive '$name' not defined\n"
        if !ref($name) && !_is_inline_drive_clause($cl);
    return _ir_drive($cl, $tn, $pending_samples, $state_index);
}
sub _ir_await {
