# ISF-TRIGGER-ANCHOR.5: (point NAME) is a no-op labeled position in a transaction body — a
# pass-through state whose name a (at NAME) check resolves to (via `state_active`). Records the
# name -> state binding into the module-wide $point_bindings map.
sub _ir_point {
    my ($cl, $tn, $i, $point_bindings) = @_;
    my $name = $cl->[1];
    confess "Transaction '$tn': (point NAME) requires a scalar name\n"
        unless defined($name) && !ref($name) && length($name);
    confess "Transaction '$tn': (point '$name') name must be an HDL identifier\n"
        unless $name =~ /\A[A-Za-z_]\w*\z/;
    my $state_name = "${tn}_point_$i";
    if (ref($point_bindings) eq 'HASH') {
        confess "Transaction '$tn': duplicate point/activation name '$name'\n"
            if exists $point_bindings->{$name};
        $point_bindings->{$name} = $state_name;
    }
    return { name => $state_name, kind => 'sequential', assignments => [], transitions => [], point_name => $name };
}

# ISF-TRIGGER-ANCHOR.5: resolve (at NAME) leaves in check conditions to (state_active <state>) once
# the module-wide name -> state map is complete; an unknown NAME fails closed.
sub _resolve_at_references {
    my ($asserts, $bindings, $states, $counters) = @_;
    return unless ref($asserts) eq 'ARRAY';
    $bindings = {} unless ref($bindings) eq 'HASH';
    my %state_by_name =
        map { $_->{name} => $_ } grep { ref($_) eq 'HASH' && defined $_->{name} } @{$states || []};

    for my $a (@$asserts) {
        next unless ref($a) eq 'HASH' && defined $a->{condition} && !ref($a->{condition});
        $a->{condition} =~ s{\(at\s+([A-Za-z_]\w*)\)}{
            my $name = $1;
            confess "Check '" . ($a->{name} // '?') . "': (at $name) references unknown point/activation name '$name'; declare it with (point $name) or (on SIGNAL as $name)\n"
                unless exists $bindings->{$name};
            my $state_name = $bindings->{$name};
            my $signal = "${state_name}_active";
            # Keep the ISF/FSM boundary on the FSM side: the named position surfaces as a 1-bit
            # SIGNAL the named state drives high while active (combinational, like the monitor's arm),
            # generated lazily only for referenced points. The ISF-originated assertion references
            # this signal — never `current_state`. The signal's state-derivation is the FSM's job.
            if (my $st = $state_by_name{$state_name}) {
                unless (grep { ($_->{lhs} // '') eq $signal } @{$st->{assignments} || []}) {
                    push @{$st->{assignments}},
                        { lhs => $signal, rhs => 1, op => '=', source_kind => 'point_active' };
                    $counters->{$signal} = 1 if ref($counters) eq 'HASH';
                }
            }
            $signal;   # a bare signal leaf — `(sig)` would parse as a 1-arg operator call
        }ge;
    }
    return;
}
sub _ir_stage {
    my ($cl, $tn, $i, $actor) = @_;
    my $stage = _parse_stage_handshake_clause($cl, $tn, 'transaction body');
    my %inputs = map { $_->{name} => 1 } @{$actor->{interface}{inputs} || []};
    my %outputs = map { $_->{name} => 1 } @{$actor->{interface}{outputs} || []};

    confess "Transaction '$tn': stage '$stage->{name}' input '$stage->{ready}' is not an actor input\n"
        unless $inputs{$stage->{ready}};
    confess "Transaction '$tn': stage '$stage->{name}' output '$stage->{valid}' is not an actor output\n"
        unless $outputs{$stage->{valid}};

    return {
        name        => "${tn}_stage_$i",
        kind        => 'stage',
        stage_name  => $stage->{name},
        ready       => $stage->{ready},
        valid       => $stage->{valid},
        assignments => [
            { lhs => $stage->{valid}, rhs => 1, op => '=', source_kind => 'stage_valid' },
        ],
        transitions => [],
    };
}

# The arm/age/fail monitor signal set for a bounded-eventually monitor, keyed off a name prefix.
# Shared by `(contract …)` and the `(monitor …)` output-mode of a check (ISF-TRIGGER-ANCHOR).
sub _monitor_signals_for_prefix {
    my ($prefix) = @_;
    return {
        state   => $prefix,
        monitor => "${prefix}_monitor",
        arm     => "${prefix}_arm",
        pending => "${prefix}_pending",
        age     => "${prefix}_age",
        fail    => "${prefix}_fail",
    };
}

# Build the synthesizable bounded-eventually monitor (arm state + arm/pending/age/fail registers):
# from the cycle `arm` pulses (control reaches the positioned arm state), `$observed` must hold
# within `$within_cycles` cycles, else `fail` latches. Returns ($arm_state, $monitor_dt). Shared by
# `(contract …)` and the `(monitor …)` check output-mode (decision 0009) — identical hardware, so
# `(contract …)` is one caller of this engine and dissolves into it.
sub _build_eventually_monitor {
    my ($signals, $observed, $within_cycles, $counters, $storage_roles, $state_label) = @_;

    my ($arm, $pending, $age, $fail) = @{$signals}{qw(arm pending age fail)};
    my $last_cycle = $within_cycles - 1;
    my $age_width = _unsigned_width_for_max($last_cycle);
    $counters->{$arm} = 1;
    $counters->{$pending} = 1;
    $counters->{$age} = $age_width;
    $counters->{$fail} = 1;
    if (ref($storage_roles) eq 'HASH') {
        $storage_roles->{$pending} = 'temporal_contract_monitor';
        $storage_roles->{$age}     = 'temporal_contract_monitor';
        $storage_roles->{$fail}    = 'temporal_contract_monitor';
    }

    my $arm_start_guard = "(& $arm (! $pending))";
    my $expiry_guard = "(& $pending (! $observed) (== $age $last_cycle))";
    my $clear_guard = "(| (& $pending $observed) $expiry_guard)";
    my $fail_guard = "(| (& $arm $pending) $expiry_guard)";
    my @monitor_assignments = (
        {
            lhs         => $pending,
            rhs         => 1,
            op          => '<-',
            guard       => { expr => $arm_start_guard },
            source_kind => 'contract_pending_set',
        },
        {
            lhs         => $pending,
            rhs         => 0,
            op          => '<-',
            guard       => { expr => $clear_guard },
            source_kind => 'contract_pending_clear',
        },
        {
            lhs         => $age,
            rhs         => 0,
            op          => '<-',
            guard       => { expr => $arm_start_guard },
            source_kind => 'contract_age_reset',
        },
        {
            lhs         => $fail,
            rhs         => 1,
            op          => '<-',
            guard       => { expr => $fail_guard },
            source_kind => 'contract_fail',
        },
    );

    if ($within_cycles > 1) {
        my $advance_guard = "(& $pending (! $observed) (! (== $age $last_cycle)))";
        splice @monitor_assignments, 3, 0, {
            lhs         => $age,
            rhs         => "(+ $age 1)",
            op          => '<-',
            guard       => { expr => $advance_guard },
            source_kind => 'contract_age_increment',
        };
    }

    my $state = {
        name          => $signals->{state},
        kind          => 'contract',
        (defined $state_label ? (contract_name => $state_label) : ()),
        assignments   => [
            { lhs => $arm, rhs => 1, op => '=', source_kind => 'contract_arm_request' },
        ],
        transitions   => [],
    };
    my $dt = {
        name        => $signals->{monitor},
        kind        => 'temporal_contract_monitor',
        assignments => \@monitor_assignments,
    };
    return ($state, $dt);
}

# ISF-TRIGGER-ANCHOR (decision 0009): the synthesizable-monitor output-mode of a check. A check
# whose condition is `(monitor (within SIGNAL N))` placed in a transaction body anchors the
# bounded-eventually to its own position (the inline trigger): an arm state pulses where the clause
# sits, the monitor watches SIGNAL within N cycles, and the check asserts `(! fail)` — a same-cycle
# boolean, so the temporal logic lives in synthesizable hardware and the assertion is
# verilator-simulable. Returns ($arm_state, $monitor_dt, $assert_record).
sub _is_monitor_check {
    my ($cl) = @_;
    my $cond = $cl->[1];
    return ref($cond) eq 'ARRAY' && @$cond == 2 && defined($cond->[0])
        && !ref($cond->[0]) && $cond->[0] eq 'monitor';
}

sub _ir_monitor_check {
    my ($cl, $tn, $i, $actor, $widths, $counters, $storage_roles, $preallocation) = @_;
    my ($kind, $cond, $message) = @$cl;
    confess "Error: ($kind ...) in transaction '$tn' takes a condition and an optional message string only\n"
        if @$cl > 3;

    # (monitor (within SIGNAL N)) -> ['monitor', ['within', SIGNAL, N]] (plain nested arrays)
    my $inner = (ref($cond) eq 'ARRAY') ? $cond->[1] : undef;
    confess "Error: ($kind (monitor …)) in transaction '$tn' supports only '(monitor (within SIGNAL N))'\n"
        unless ref($inner) eq 'ARRAY' && @$inner == 3 && defined($inner->[0])
            && !ref($inner->[0]) && $inner->[0] eq 'within';
    my ($observed, $bound_token) = ($inner->[1], $inner->[2]);
    confess "Error: ($kind (monitor (within SIGNAL N))) in transaction '$tn' requires a scalar signal\n"
        unless defined($observed) && !ref($observed) && length($observed);
    confess "Error: ($kind (monitor (within SIGNAL N))) in transaction '$tn' requires a window count N\n"
        unless defined($bound_token) && !ref($bound_token);

    my %interface_signals = map { $_->{name} => 1 }
        (@{$actor->{interface}{inputs} || []}, @{$actor->{interface}{outputs} || []});
    confess "Error: ($kind (monitor (within '$observed' …))) in transaction '$tn': '$observed' is not an actor interface signal\n"
        unless $interface_signals{$observed};

    my $prefix = "${tn}_${kind}_$i";
    # N may be a literal, a same-transaction/actor scalar parameter, an actor constant, or a
    # qualified package scalar constant — the same window sources as (contract …) (ISF-TRIGGER-ANCHOR.4),
    # so the monitor output-mode loses no capability vs the construct it replaces. The common literal
    # case gets a clear monitor-specific message; identifier windows defer to the shared resolver.
    my $within_cycles;
    if ($bound_token =~ /\A[0-9]+\z/) {
        confess "Error: ($kind (monitor (within SIGNAL N))) in transaction '$tn' N must be a positive integer\n"
            unless $bound_token =~ /\A[1-9][0-9]*\z/;
        $within_cycles = $bound_token + 0;
    }
    else {
        $within_cycles = _resolve_monitor_window_cycles($bound_token, $actor, $tn, $prefix, 'transaction body');
    }

    my $signals = _monitor_signals_for_prefix($prefix);
    my @deferred_roles;
    for my $role (qw(arm pending age fail)) {
        my $signal = $signals->{$role};
        next unless $counters->{$signal} || ($widths && $widths->{$signal})
            || $interface_signals{$signal};
        # Only source-only preparation can postpone this physical collision.
        # Generated public ports, already projected declarations and fixed actor
        # or local identities must never receive this exemption. Executable
        # builds never pass the preparation context and retain the strict check.
        if ($preallocation && exists $preallocation->{formals}{$signal}
            && !$preallocation->{fixed_names}{$signal}
            && ($storage_roles->{$signal} // '') eq 'transaction_port') {
            push @deferred_roles, $role;
            next;
        }
        confess "Error: ($kind (monitor …)) in transaction '$tn': generated signal '$signal' collides with an existing signal\n";
    }

    my ($state, $dt) = _build_eventually_monitor(
        $signals, $observed, $within_cycles, $counters, $storage_roles);
    for my $role (@deferred_roles) {
        my $signal = $signals->{$role};
        push @{$preallocation->{collisions}}, {
            source_identity => ['transaction_port', $actor->{actor_name}, $tn, $signal],
            formal_declaration => _clone_isf_value($preallocation->{formals}{$signal}),
            generated_signal => $signal, monitor_role => $role,
            generated_width => $counters->{$signal}, monitor_state => $state->{name},
        };
    }

    my %assert = (
        name      => "${prefix}_holds",
        kind      => $kind,
        condition => "(! $signals->{fail})",
    );
    if (defined $message) {
        confess "Error: ($kind (monitor …) ...) in transaction '$tn' message must be a scalar string\n"
            if ref($message);
        $assert{message} = $message;
    }

    return ($state, $dt, \%assert);
}

sub _unsigned_width_for_max {
    my ($max_value) = @_;
    return 1 unless defined($max_value) && $max_value > 0;

    my $width = 1;
    my $max_representable = 1;
    while ($max_representable < $max_value) {
        ++$width;
        $max_representable = (2 ** $width) - 1;
    }
    return $width;
}
sub _ir_placeholder{ my ($cl,$tn,$i)=@_; {name=>"${tn}_$cl->[0]_$i",kind=>'sequential',assignments=>[],transitions=>[]} }
sub _ir_do {
    my ($cl, $tn, $i, $do_ref, $label) = @_;
    $label //= 'transaction body';
    my $c = $cl->[1];
    my $prefix = (ref($do_ref) eq 'HASH' && $do_ref->{generated_child})
        ? $do_ref->{instance}
        : $c;
    my @assignments;
    if (ref($do_ref) eq 'HASH' && $do_ref->{generated_child}) {
        @assignments = (
            { lhs => "${prefix}_start", rhs => 1, op => '=', source_kind => 'do_start' },
        );
    } else {
        my @bindings = @{_activation_bindings_from_clause($cl, $tn, $label)};
        @assignments = (
            _activation_input_assignments(\@bindings, 'do_input_binding'),
            { lhs => "${prefix}_start", rhs => 1, op => '=', source_kind => 'do_start' },
            _activation_output_assignments(\@bindings, "${prefix}_done", 'do_output_binding'),
        );
    }
    return {
        name        => "${tn}_do_$i",
        kind        => 'await',
        assignments => \@assignments,
        transitions => [],
        guard       => { port => "${prefix}_done" },
    };
}

sub _ir_spawn {
    my ($cl, $tn, $i) = @_;
    my $inst = $cl->[3] || "${tn}_$i";
    return {
        name        => "${tn}_spawn_$i",
        kind        => 'sequential',
        assignments => [{ lhs => "${inst}_start", rhs => 1, op => '=', source_kind => 'spawn_start' }],
        transitions => [],
    };
}

sub _activation_input_assignments {
    my ($bindings, $source_kind) = @_;
    return map {
        +{
            lhs         => $_->{port},
            rhs         => _activation_binding_actor_expr_text($_),
            op          => '=',
            source_kind => $source_kind,
        }
    } grep { $_->{role} eq 'input' } @$bindings;
}

sub _activation_output_assignments {
    my ($bindings, $done, $source_kind) = @_;
    return map {
        +{
            lhs         => $_->{actor_signal},
            rhs         => $_->{port},
            op          => '=',
            guard       => { port => $done },
            source_kind => $source_kind,
        }
    } grep { $_->{role} eq 'output' } @$bindings;
}
